        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        string sourceId,
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds)
    {
        var normalizedOperationId = string.IsNullOrWhiteSpace(operationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceOperationIds.None
            : operationId.Trim();

        return new CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus(state, description)
        {
            CategoryIds = categoryIds,
            OperationId = normalizedOperationId,
            ManagementMode = governance.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            DryRunState = dryRun.State,
            ExecutionIntentState = executionIntent.State,
            ExecutionApprovalState = executionApproval.State,
            CommandEnvelopeState = commandEnvelope.State,
            PrimaryActionId = actionPlan.PrimaryActionId,
            SourceId = sourceId,
            CommandEnvelopeSourceId = commandEnvelope.SourceId,
            ExecutionIntentConfidenceSourceId = executionIntent.ConfidenceSourceId,
            ExecutionApprovalSourceId = executionApproval.SourceId,
            PotentialChangeCount = commandEnvelope.PotentialChangeCount,
            WouldApplyChanges = commandEnvelope.WouldApplyChanges,
            RequiresExplicitApproval = commandEnvelope.RequiresExplicitApproval,
            IsDestructiveOperation = commandEnvelope.IsDestructiveOperation,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ConnectClusterId = commandEnvelope.ConnectClusterId,
            ConnectorClass = commandEnvelope.ConnectorClass,
            SourceProviderId = commandEnvelope.SourceProviderId,
            CommandFingerprint = commandEnvelope.CommandFingerprint,
            IssuanceFingerprint = CreateManagedConnectorCommandIssuanceFingerprint(
                state,
                normalizedOperationId,
                sourceId,
                commandEnvelope.State,
                commandEnvelope.CommandFingerprint,
                executionApproval.State,
                executionIntent.State,
                dryRun.State,
                commandEnvelope.RequiresExplicitApproval,
                commandEnvelope.WouldApplyChanges,
                commandEnvelope.IsDestructiveOperation)
        };
    }

    private static string[] CreateManagedConnectorCommandIssuanceCategories(
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        string operationId)
    {
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 18);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        if (executionIntent.IsDeferred ||
            string.Equals(
                commandEnvelope.State,
                CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStates.NotApplicable,
                StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ObserveOnlyMode);
        }

        if (remediation.IsBlocked ||
            commandEnvelope.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeCategories.BlockingRemediation,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.BlockingRemediation);
        }

        if (commandEnvelope.CategoryIds.Contains(
            CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeCategories.StaleObservation,
            StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.StaleObservation);
        }

        if (!reportingCoverage.HasFullCoverage ||
            commandEnvelope.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeCategories.IncompleteReportingCoverage,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.IncompleteReportingCoverage);
        }

        if (actionPlan.IsWaiting ||
            commandEnvelope.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase) ||
            preflight.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorPreflightCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase) ||
            writePathReadiness.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.RuntimeTruthIncomplete);
        }

        if (governance.IsOutOfPolicy)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.GovernanceOutOfPolicy);
        }

        if (commandEnvelope.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ControlPlaneOwnershipGap);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.OperatorOnly);
        }

        if (commandEnvelope.WouldApplyChanges || dryRun.WouldApplyChanges)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ChangePlanned);
        }

        if (WouldManagedConnectorDryRunRequireLifecycleChange(operationId, dryRun.WouldApplyChanges))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.LifecycleChange);
        }

        if (commandEnvelope.IsDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.DestructiveOperation);
        }

        if (executionApproval.IsApprovalRequired)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ApprovalRequired);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ApprovalGated);
        }
        else if (executionApproval.IsApprovalReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ApprovalReady);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.ApprovalGated);
        }

        if (ShouldRejectManagedConnectorCommandIssuance(commandEnvelope, dryRun, executionApproval))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.Rejected);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.NoExecutionNeeded);
        }
        else if (commandEnvelope.IsApprovalGated)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.Accepted);
        }
        else if (commandEnvelope.IsEngineReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.Issued);
        }

        return [.. categories];
    }

    private static string ResolveManagedConnectorCommandIssuanceSource(
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent)
    {
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(executionIntent);

        if (commandEnvelope.AppliesToManagedConnector ||
            string.Equals(
                commandEnvelope.State,
                CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStates.NotApplicable,
                StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceSources.CommandEnvelope;
        }

        if (executionApproval.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceSources.ExecutionApproval;
        }

        if (executionIntent.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceSources.ExecutionIntent;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceSources.Unknown;
    }

    private static string ResolveManagedConnectorCommandIssuanceOperationId(
        string? commandEnvelopeOperationId,
        string? executionApprovalOperationId,
        string? executionIntentOperationId)
    {
        if (!string.IsNullOrWhiteSpace(commandEnvelopeOperationId))
        {
            return commandEnvelopeOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(executionApprovalOperationId))
        {
            return executionApprovalOperationId.Trim();
        }

        return string.IsNullOrWhiteSpace(executionIntentOperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceOperationIds.None
            : executionIntentOperationId.Trim();
    }

    private static bool ShouldRejectManagedConnectorCommandIssuance(
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval)
    {
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionApproval);

        return commandEnvelope.IsEngineReady &&
               (!commandEnvelope.HasCommandTarget ||
                !commandEnvelope.WouldApplyChanges ||
                dryRun.IsNoOp ||
                commandEnvelope.CategoryIds.Contains(
                    CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeCategories.NoExecutionNeeded,
                    StringComparer.OrdinalIgnoreCase) ||
                executionApproval.CategoryIds.Contains(
                    CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalCategories.NoExecutionNeeded,
                    StringComparer.OrdinalIgnoreCase));
    }

    private static string CreateManagedConnectorCommandIssuanceFingerprint(
        string state,
        string operationId,
        string sourceId,
        string commandEnvelopeState,
        string commandFingerprint,
        string executionApprovalState,
        string executionIntentState,
        string dryRunState,
        bool requiresExplicitApproval,
        bool wouldApplyChanges,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentException.ThrowIfNullOrWhiteSpace(sourceId);
        ArgumentException.ThrowIfNullOrWhiteSpace(commandEnvelopeState);
        ArgumentException.ThrowIfNullOrWhiteSpace(commandFingerprint);
        ArgumentException.ThrowIfNullOrWhiteSpace(executionApprovalState);
        ArgumentException.ThrowIfNullOrWhiteSpace(executionIntentState);
        ArgumentException.ThrowIfNullOrWhiteSpace(dryRunState);

        return string.Join(
            "|",
            [
                "cephalon-managed-connector-command-issuance/v1",
                $"state={state.Trim()}",
                $"operation={operationId.Trim()}",
                $"source={sourceId.Trim()}",
                $"commandEnvelope={commandEnvelopeState.Trim()}",
                $"commandFingerprint={commandFingerprint.Trim()}",
                $"executionApproval={executionApprovalState.Trim()}",
                $"executionIntent={executionIntentState.Trim()}",
                $"dryRun={dryRunState.Trim()}",
                $"requiresExplicitApproval={requiresExplicitApproval.ToString().ToLowerInvariant()}",
                $"wouldApplyChanges={wouldApplyChanges.ToString().ToLowerInvariant()}",
                $"destructive={isDestructiveOperation.ToString().ToLowerInvariant()}"
            ]);
    }

    private CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus CreateManagedConnectorExecutionAdapter(
        CdcCaptureExecutionRuntimeDescriptor runtime,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        ManagedConnectorMetadataSnapshot metadataSnapshot)
    {
        ArgumentNullException.ThrowIfNull(runtime);
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(metadataSnapshot);

        var candidateExecutionAdapter = ResolveManagedConnectorExecutionAdapter(runtime);
        var adapterId = candidateExecutionAdapter?.AdapterId ?? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterIds.None;
        var operationId = ResolveManagedConnectorExecutionAdapterOperationId(
            commandIssuance.OperationId,
            commandEnvelope.OperationId,
            executionApproval.OperationId,
            executionIntent.OperationId);
        var sourceId = ResolveManagedConnectorExecutionAdapterSource(
            commandIssuance,
            commandEnvelope,
            executionApproval,
            executionIntent);
        string state;
        string description;

        if (!string.Equals(runtime.ExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(
                commandIssuance.State,
                CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStates.NotApplicable,
                StringComparison.OrdinalIgnoreCase))
        {
            state = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.NotApplicable;
            description = CreateManagedConnectorNotApplicableExecutionAdapterDescription(
                commandIssuance.Description,
                governance.Description);
        }
        else if (commandIssuance.IsOperatorOnly)
        {
            state = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.OperatorOnly;
            description = CreateManagedConnectorOperatorOnlyExecutionAdapterDescription(
                operationId,
                adapterId,
                commandIssuance.Description,
                executionApproval.Description);
        }
        else if (commandIssuance.IsBlocked)
        {
            state = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.Blocked;
            description = CreateManagedConnectorBlockedExecutionAdapterDescription(
                operationId,
                adapterId,
                commandIssuance.Description,
                executionApproval.Description);
        }
        else if (candidateExecutionAdapter is null)
        {
            state = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.Unavailable;
            description = CreateManagedConnectorUnavailableExecutionAdapterDescription(
                operationId,
                commandIssuance.Description);
        }
        else
        {
            state = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.Ready;
            description = CreateManagedConnectorReadyExecutionAdapterDescription(
                operationId,
                adapterId,
                commandIssuance);
        }

        var categories = CreateManagedConnectorExecutionAdapterCategories(
            runtime.ExecutionTopology,
            state,
            reportingCoverage,
            remediation,
            governance,
            drift,
            actionPlan,
            writePathReadiness,
            preflight,
            dryRun,
            executionIntent,
            executionApproval,
            commandEnvelope,
            commandIssuance,
            operationId);

        return CreateManagedConnectorExecutionAdapterStatus(
            state,
            description,
            categories,
            operationId,
            governance,
            reportingCoverage,
            remediation,
            drift,
            actionPlan,
            writePathReadiness,
            preflight,
            dryRun,
            executionIntent,
            executionApproval,
            commandEnvelope,
            commandIssuance,
            sourceId,
            adapterId,
            runtime.Id,
            runtime.CdcCaptureIds,
            metadataSnapshot);
    }

    private ICdcCaptureExecutionRuntimeManagedConnectorExecutionAdapter? ResolveManagedConnectorExecutionAdapter(
        CdcCaptureExecutionRuntimeDescriptor runtime)
    {
        ArgumentNullException.ThrowIfNull(runtime);

        foreach (var executionAdapter in executionAdapters)
        {
            if (executionAdapter.CanHandle(runtime))
            {
                return executionAdapter;
            }
        }

        return null;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult CreateManagedConnectorCommandExecution(
        CdcCaptureExecutionRuntimeDescriptor runtime,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestCommandExecution)
    {
        ArgumentNullException.ThrowIfNull(runtime);
        ArgumentNullException.ThrowIfNull(executionAdapter);

        if (latestCommandExecution is not null)
        {
            return latestCommandExecution;
        }

        var connectorId = runtime.Metadata.TryGetValue("connectorId", out var configuredConnectorId) &&
                          !string.IsNullOrWhiteSpace(configuredConnectorId)
            ? configuredConnectorId.Trim()
            : runtime.Id;
        var providerId = runtime.Metadata.TryGetValue("provider", out var configuredProviderId) &&
                         !string.IsNullOrWhiteSpace(configuredProviderId)
            ? configuredProviderId.Trim()
            : null;

        return new CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult(
            executionAdapter.AppliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Unrecorded
                : CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.NotApplicable,
            executionAdapter.AppliesToManagedConnector
                ? CreateManagedConnectorUnrecordedCommandExecutionDescription(executionAdapter)
                : "The execution runtime does not currently participate in a managed-connector command-execution lane.")
        {
            ExecutionRuntimeId = runtime.Id,
            RequestedOperationId = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None,
            ResolvedOperationId = CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None,
            ExecutionAdapterState = executionAdapter.State,
            CommandIssuanceState = executionAdapter.CommandIssuanceState,
            CommandEnvelopeState = executionAdapter.CommandEnvelopeState,
            AdapterId = executionAdapter.AdapterId,
            ProviderId = providerId,
            ConnectClusterId = executionAdapter.ConnectClusterId,
            ConnectorId = connectorId,
            ConnectorClass = executionAdapter.ConnectorClass,
            SourceProviderId = executionAdapter.SourceProviderId,
            ManagementMode = executionAdapter.ManagementMode,
            SourceId = executionAdapter.SourceId,
            InvocationSourceId = CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionInvocationSources.None,
            CommandFingerprint = executionAdapter.CommandFingerprint,
            IssuanceFingerprint = executionAdapter.IssuanceFingerprint,
            AdapterFingerprint = executionAdapter.AdapterFingerprint,
            ExecutionFingerprint = string.Empty,
            RequiresExplicitApproval = executionAdapter.RequiresExplicitApproval,
            IsDestructiveOperation = executionAdapter.IsDestructiveOperation,
            WouldApplyChanges = executionAdapter.WouldApplyChanges
        };
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus CreateManagedConnectorCommandRetry(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        IReadOnlyList<CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult> commandExecutionHistory,
        DateTimeOffset now)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(commandExecution);
        ArgumentNullException.ThrowIfNull(commandExecutionHistory);

        var operationId = ResolveManagedConnectorCommandRetryOperationId(
            executionAdapter.OperationId,
            commandExecution.RequestedOperationId,
            commandExecution.ResolvedOperationId,
            commandIssuance.OperationId);
        var latestRecordedCommand = commandExecutionHistory.Count > 0
            ? commandExecutionHistory[0]
            : null;
        var latestMatchingCommand = commandExecutionHistory.FirstOrDefault(
            entry => MatchesManagedConnectorCommandRetryFingerprint(
                operationId,
                executionAdapter,
                entry));
        var hasMatchingCommandFingerprint = latestMatchingCommand is not null &&
                                           string.Equals(
                                               latestMatchingCommand.CommandFingerprint,
                                               executionAdapter.CommandFingerprint,
                                               StringComparison.OrdinalIgnoreCase);
        var hasMatchingIssuanceFingerprint = latestMatchingCommand is not null &&
                                            string.Equals(
                                                latestMatchingCommand.IssuanceFingerprint,
                                                executionAdapter.IssuanceFingerprint,
                                                StringComparison.OrdinalIgnoreCase);
        var hasMatchingAdapterFingerprint = latestMatchingCommand is not null &&
                                          string.Equals(
                                              latestMatchingCommand.AdapterFingerprint,
                                              executionAdapter.AdapterFingerprint,
                                              StringComparison.OrdinalIgnoreCase);
        var hasMatchingRetryFingerprint = latestMatchingCommand is not null &&
                                         hasMatchingCommandFingerprint &&
                                         hasMatchingIssuanceFingerprint &&
                                         hasMatchingAdapterFingerprint;
        var latestMatchingApprovalApplied = latestMatchingCommand?.ApprovalApplied ?? false;
        var latestMatchingDestructiveAllowanceApplied = latestMatchingCommand?.DestructiveAllowanceApplied ?? false;
        var canReuseApprovalFromMatchingHistory =
            !executionAdapter.RequiresExplicitApproval ||
            latestMatchingApprovalApplied;
        var canReuseDestructiveAllowanceFromMatchingHistory =
            !executionAdapter.IsDestructiveOperation ||
            latestMatchingDestructiveAllowanceApplied;
        var latestCommandState = latestRecordedCommand?.State ?? commandExecution.State;
        var latestCommandSourceId = latestRecordedCommand?.SourceId ?? commandExecution.SourceId;
        var latestExecutionFingerprint = latestRecordedCommand?.ExecutionFingerprint ?? commandExecution.ExecutionFingerprint;
        var latestAttemptId = latestRecordedCommand?.AttemptId ?? string.Empty;
        var latestRecordedAtUtc = latestRecordedCommand?.RecordedAtUtc;
        var cooldownUntilUtc = ResolveManagedConnectorCommandRetryCooldownUntilUtc(latestMatchingCommand);
        var categories = CreateManagedConnectorCommandRetryCategories(
            executionTopology,
            reportingCoverage,
            remediation,
            governance,
            actionPlan,
            writePathReadiness,
            preflight,
            executionApproval,
            commandIssuance,
            executionAdapter,
            latestRecordedCommand,
            latestMatchingCommand,
            operationId,
            now);
        var sourceId = ResolveManagedConnectorCommandRetrySource(latestMatchingCommand, latestRecordedCommand, executionAdapter);
        var retryFingerprint = CreateManagedConnectorCommandRetryFingerprint(
            operationId,
            executionRuntimeId,
            executionAdapter.CommandFingerprint,
            executionAdapter.IssuanceFingerprint,
            executionAdapter.AdapterFingerprint,
            executionAdapter.RequiresExplicitApproval,
            executionAdapter.IsDestructiveOperation,
            executionAdapter.WouldApplyChanges);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            executionIntent.IsDeferred ||
            !executionAdapter.AppliesToManagedConnector)
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotApplicable,
                CreateManagedConnectorNotApplicableCommandRetryDescription(
                    executionAdapter.Description,
                    governance.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (executionAdapter.IsOperatorOnly || commandExecution.IsOperatorOnly)
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.OperatorOnly,
                CreateManagedConnectorOperatorOnlyCommandRetryDescription(
                    operationId,
                    executionAdapter.Description,
                    latestMatchingCommand?.Description ?? latestRecordedCommand?.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (commandIssuance.IsRejected ||
            !executionAdapter.WouldApplyChanges ||
            commandExecution.IsNoOp ||
            (latestMatchingCommand?.IsNoOp ?? false))
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotNeeded,
                CreateManagedConnectorNotNeededCommandRetryDescription(
                    operationId,
                    executionAdapter,
                    latestMatchingCommand,
                    latestRecordedCommand),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (latestMatchingCommand is null)
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotNeeded,
                CreateManagedConnectorNoMatchingHistoryCommandRetryDescription(
                    operationId,
                    latestRecordedCommand is null,
                    executionAdapter.Description,
                    latestRecordedCommand?.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (cooldownUntilUtc.HasValue &&
            cooldownUntilUtc.Value > now)
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.Cooldown,
                CreateManagedConnectorCooldownCommandRetryDescription(
                    operationId,
                    latestMatchingCommand,
                    cooldownUntilUtc.Value),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (latestMatchingCommand.IsAdapted)
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.Duplicate,
                CreateManagedConnectorDuplicateCommandRetryDescription(
                    operationId,
                    latestMatchingCommand,
                    executionAdapter.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (executionAdapter.IsBlocked ||
            executionAdapter.IsUnavailable ||
            ((executionApproval.IsApprovalRequired ||
              executionApproval.IsApprovalReady ||
              executionAdapter.RequiresExplicitApproval ||
              executionAdapter.IsDestructiveOperation) &&
             (!canReuseApprovalFromMatchingHistory || !canReuseDestructiveAllowanceFromMatchingHistory)))
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.RetryBlocked,
                CreateManagedConnectorRetryBlockedDescription(
                    operationId,
                    latestMatchingCommand,
                    executionAdapter,
                    executionApproval),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        if (latestMatchingCommand.IsFailed ||
            latestMatchingCommand.IsUnavailable ||
            latestMatchingCommand.IsBlocked)
        {
            return CreateManagedConnectorCommandRetryStatus(
                CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.RetryEligible,
                CreateManagedConnectorRetryEligibleDescription(
                    operationId,
                    latestMatchingCommand,
                    executionAdapter.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                latestCommandState,
                sourceId,
                latestCommandSourceId,
                executionRuntimeId,
                cdcCaptureIds,
                latestAttemptId,
                latestRecordedAtUtc,
                cooldownUntilUtc,
                latestExecutionFingerprint,
                retryFingerprint,
                hasMatchingRetryFingerprint,
                hasMatchingCommandFingerprint,
                hasMatchingIssuanceFingerprint,
                hasMatchingAdapterFingerprint,
                latestMatchingApprovalApplied,
                latestMatchingDestructiveAllowanceApplied,
                canReuseApprovalFromMatchingHistory,
                canReuseDestructiveAllowanceFromMatchingHistory);
        }

        return CreateManagedConnectorCommandRetryStatus(
            CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotNeeded,
            CreateManagedConnectorNotNeededCommandRetryDescription(
                operationId,
                executionAdapter,
                latestMatchingCommand,
                latestRecordedCommand),
            categories,
            operationId,
            governance,
            reportingCoverage,
            remediation,
            drift,
            actionPlan,
            writePathReadiness,
            preflight,
            dryRun,
            executionIntent,
            executionApproval,
            commandEnvelope,
            commandIssuance,
            executionAdapter,
            latestCommandState,
            sourceId,
            latestCommandSourceId,
            executionRuntimeId,
            cdcCaptureIds,
            latestAttemptId,
            latestRecordedAtUtc,
            cooldownUntilUtc,
            latestExecutionFingerprint,
            retryFingerprint,
            hasMatchingRetryFingerprint,
            hasMatchingCommandFingerprint,
            hasMatchingIssuanceFingerprint,
            hasMatchingAdapterFingerprint,
            latestMatchingApprovalApplied,
            latestMatchingDestructiveAllowanceApplied,
            canReuseApprovalFromMatchingHistory,
            canReuseDestructiveAllowanceFromMatchingHistory);
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus CreateManagedConnectorCommandRetryStatus(
        string state,
        string description,
        IReadOnlyList<string> categoryIds,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        string latestCommandExecutionState,
        string sourceId,
        string latestCommandExecutionSourceId,
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string latestAttemptId,
        DateTimeOffset? latestRecordedAtUtc,
        DateTimeOffset? cooldownUntilUtc,
        string latestExecutionFingerprint,
        string retryFingerprint,
        bool hasMatchingRetryFingerprint,
        bool hasMatchingCommandFingerprint,
        bool hasMatchingIssuanceFingerprint,
        bool hasMatchingAdapterFingerprint,
        bool latestMatchingApprovalApplied,
        bool latestMatchingDestructiveAllowanceApplied,
        bool canReuseApprovalFromMatchingHistory,
        bool canReuseDestructiveAllowanceFromMatchingHistory)
    {
        var normalizedOperationId = string.IsNullOrWhiteSpace(operationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandRetryOperationIds.None
            : operationId.Trim();

        return new CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus(state, description)
        {
            CategoryIds = categoryIds,
            OperationId = normalizedOperationId,
            ManagementMode = governance.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            DryRunState = dryRun.State,
            ExecutionIntentState = executionIntent.State,
            ExecutionApprovalState = executionApproval.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = string.IsNullOrWhiteSpace(latestCommandExecutionState)
                ? CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Unrecorded
                : latestCommandExecutionState.Trim(),
            PrimaryActionId = actionPlan.PrimaryActionId,
            SourceId = sourceId,
            ExecutionAdapterSourceId = executionAdapter.SourceId,
            LatestCommandExecutionSourceId = string.IsNullOrWhiteSpace(latestCommandExecutionSourceId)
                ? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterSources.Unknown
                : latestCommandExecutionSourceId.Trim(),
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ConnectClusterId = executionAdapter.ConnectClusterId,
            ConnectorClass = executionAdapter.ConnectorClass,
            SourceProviderId = executionAdapter.SourceProviderId,
            PotentialChangeCount = executionAdapter.PotentialChangeCount,
            WouldApplyChanges = executionAdapter.WouldApplyChanges,
            RequiresExplicitApproval = executionAdapter.RequiresExplicitApproval,
            LatestMatchingApprovalApplied = latestMatchingApprovalApplied,
            IsDestructiveOperation = executionAdapter.IsDestructiveOperation,
            LatestMatchingDestructiveAllowanceApplied = latestMatchingDestructiveAllowanceApplied,
            CanReuseApprovalFromMatchingHistory = canReuseApprovalFromMatchingHistory,
            CanReuseDestructiveAllowanceFromMatchingHistory = canReuseDestructiveAllowanceFromMatchingHistory,
            CommandFingerprint = executionAdapter.CommandFingerprint,
            IssuanceFingerprint = executionAdapter.IssuanceFingerprint,
            AdapterFingerprint = executionAdapter.AdapterFingerprint,
            RetryFingerprint = retryFingerprint,
            LatestExecutionFingerprint = latestExecutionFingerprint,
            LatestAttemptId = latestAttemptId,
            LatestRecordedAtUtc = latestRecordedAtUtc,
            CooldownUntilUtc = cooldownUntilUtc,
            HasMatchingRetryFingerprint = hasMatchingRetryFingerprint,
            HasMatchingCommandFingerprint = hasMatchingCommandFingerprint,
            HasMatchingIssuanceFingerprint = hasMatchingIssuanceFingerprint,
            HasMatchingAdapterFingerprint = hasMatchingAdapterFingerprint
        };
    }

    private static string[] CreateManagedConnectorCommandRetryCategories(
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestRecordedCommand,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestMatchingCommand,
        string operationId,
        DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(executionAdapter);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 24);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        if (!executionAdapter.AppliesToManagedConnector)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ObserveOnlyMode);
        }

        if (remediation.IsBlocked ||
            executionAdapter.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.BlockingRemediation,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.BlockingRemediation);
        }

        if (executionAdapter.CategoryIds.Contains(
            CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.StaleObservation,
            StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.StaleObservation);
        }

        if (!reportingCoverage.HasFullCoverage ||
            executionAdapter.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.IncompleteReportingCoverage,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.IncompleteReportingCoverage);
        }

        if (actionPlan.IsWaiting ||
            executionAdapter.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase) ||
            preflight.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorPreflightCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase) ||
            writePathReadiness.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.RuntimeTruthIncomplete);
        }

        if (governance.IsOutOfPolicy)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.GovernanceOutOfPolicy);
        }

        if (executionAdapter.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ControlPlaneOwnershipGap);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.OperatorOnly);
        }

        if (executionAdapter.WouldApplyChanges)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ChangePlanned);
        }

        if (WouldManagedConnectorDryRunRequireLifecycleChange(operationId, executionAdapter.WouldApplyChanges))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LifecycleChange);
        }

        if (executionAdapter.IsDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.DestructiveOperation);
        }

        if (executionApproval.IsApprovalRequired)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ApprovalRequired);
        }
        else if (executionApproval.IsApprovalReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ApprovalReady);
        }

        if (commandIssuance.IsRejected || !executionAdapter.WouldApplyChanges)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.NoExecutionNeeded);
        }

        if (latestRecordedCommand is null)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.NoRecordedCommand);
        }
        else if (latestMatchingCommand is null)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.NoMatchingCommandHistory);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.MatchingCommandFingerprint);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.MatchingIssuanceFingerprint);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.MatchingAdapterFingerprint);

            var cooldownUntilUtc = ResolveManagedConnectorCommandRetryCooldownUntilUtc(latestMatchingCommand);
            if (cooldownUntilUtc.HasValue &&
                cooldownUntilUtc.Value > now)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.CooldownActive);
            }

            if (latestMatchingCommand.IsAdapted)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.DuplicateCommand);
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionAdapted);
            }
            else if (latestMatchingCommand.IsFailed)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionFailed);
                if (!executionAdapter.IsBlocked &&
                    !executionAdapter.IsUnavailable &&
                    !executionApproval.IsApprovalRequired &&
                    !executionApproval.IsApprovalReady)
                {
                    AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.RetryEligible);
                }
            }
            else if (latestMatchingCommand.IsUnavailable)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionUnavailable);
                if (!executionAdapter.IsBlocked &&
                    !executionAdapter.IsUnavailable &&
                    !executionApproval.IsApprovalRequired &&
                    !executionApproval.IsApprovalReady)
                {
                    AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.RetryEligible);
                }
            }
            else if (latestMatchingCommand.IsBlocked)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionBlocked);
                if (!executionAdapter.IsBlocked &&
                    !executionAdapter.IsUnavailable &&
                    !executionApproval.IsApprovalRequired &&
                    !executionApproval.IsApprovalReady &&
                    !executionAdapter.RequiresExplicitApproval)
                {
                    AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.RetryEligible);
                }
            }
        }

        return [.. categories];
    }

    private static string ResolveManagedConnectorCommandRetrySource(
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestMatchingCommand,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestRecordedCommand,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter)
    {
        ArgumentNullException.ThrowIfNull(executionAdapter);

        if (latestMatchingCommand is not null)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandRetrySources.CommandExecutionHistory;
        }

        if (latestRecordedCommand is not null)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandRetrySources.CommandExecution;
        }

        return executionAdapter.AppliesToManagedConnector
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandRetrySources.ExecutionAdapter
            : CdcCaptureExecutionRuntimeManagedConnectorCommandRetrySources.Unknown;
    }

    private static string ResolveManagedConnectorCommandRetryOperationId(
        string? executionAdapterOperationId,
        string? requestedOperationId,
        string? resolvedOperationId,
        string? commandIssuanceOperationId)
    {
        if (!string.IsNullOrWhiteSpace(executionAdapterOperationId))
        {
            return executionAdapterOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(requestedOperationId))
        {
            return requestedOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(resolvedOperationId))
        {
            return resolvedOperationId.Trim();
        }

        return string.IsNullOrWhiteSpace(commandIssuanceOperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandRetryOperationIds.None
            : commandIssuanceOperationId.Trim();
    }

    private static bool MatchesManagedConnectorCommandRetryFingerprint(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult entry)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(entry);

        var matchesOperation = string.Equals(entry.RequestedOperationId, operationId, StringComparison.OrdinalIgnoreCase) ||
                               string.Equals(entry.ResolvedOperationId, operationId, StringComparison.OrdinalIgnoreCase);
        return matchesOperation &&
               string.Equals(entry.CommandFingerprint, executionAdapter.CommandFingerprint, StringComparison.OrdinalIgnoreCase) &&
               string.Equals(entry.IssuanceFingerprint, executionAdapter.IssuanceFingerprint, StringComparison.OrdinalIgnoreCase) &&
               string.Equals(entry.AdapterFingerprint, executionAdapter.AdapterFingerprint, StringComparison.OrdinalIgnoreCase);
    }

    private static DateTimeOffset? ResolveManagedConnectorCommandRetryCooldownUntilUtc(
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestMatchingCommand)
    {
        if (latestMatchingCommand?.RecordedAtUtc is not DateTimeOffset recordedAtUtc ||
            !ShouldManagedConnectorCommandRetryUseCooldown(latestMatchingCommand.State))
        {
            return null;
        }

        return recordedAtUtc.AddSeconds(ManagedConnectorCommandRetryCooldownSeconds);
    }

    private static bool ShouldManagedConnectorCommandRetryUseCooldown(string state)
    {
        if (string.IsNullOrWhiteSpace(state))
        {
            return false;
        }

        return string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Adapted, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Blocked, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Unavailable, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Failed, StringComparison.OrdinalIgnoreCase);
    }

    private static string CreateManagedConnectorCommandRetryFingerprint(
        string operationId,
        string executionRuntimeId,
        string commandFingerprint,
        string issuanceFingerprint,
        string adapterFingerprint,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool wouldApplyChanges)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);

        return string.Join(
            "|",
            [
                "cephalon-managed-connector-command-retry/v1",
                $"operation={operationId.Trim()}",
                $"runtime={executionRuntimeId.Trim()}",
                $"commandFingerprint={NormalizeManagedConnectorFingerprintSegment(commandFingerprint)}",
                $"issuanceFingerprint={NormalizeManagedConnectorFingerprintSegment(issuanceFingerprint)}",
                $"adapterFingerprint={NormalizeManagedConnectorFingerprintSegment(adapterFingerprint)}",
                $"requiresExplicitApproval={requiresExplicitApproval.ToString().ToLowerInvariant()}",
                $"destructive={isDestructiveOperation.ToString().ToLowerInvariant()}",
                $"wouldApplyChanges={wouldApplyChanges.ToString().ToLowerInvariant()}"
            ]);
    }

    private static string CreateManagedConnectorNotApplicableCommandRetryDescription(
        string? executionAdapterDescription,
        string? governanceDescription)
    {
        return AppendManagedConnectorCommandEnvelopeDetail(
            "Cephalon does not currently expose managed-connector retry posture while the shared runtime remains observe-only.",
            CombineManagedConnectorCommandEnvelopeDetail(executionAdapterDescription, governanceDescription));
    }

    private static string CreateManagedConnectorNotNeededCommandRetryDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestMatchingCommand,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestRecordedCommand)
    {
        ArgumentNullException.ThrowIfNull(executionAdapter);

        if (latestMatchingCommand?.IsNoOp == true ||
            latestRecordedCommand?.IsNoOp == true ||
            !executionAdapter.WouldApplyChanges)
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon does not currently recommend retrying {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the shared runtime truth indicates no additional provider command is needed.",
                CombineManagedConnectorCommandEnvelopeDetail(
                    latestMatchingCommand?.Description ?? latestRecordedCommand?.Description,
                    executionAdapter.Description));
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon does not currently recommend retrying {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}.",
            CombineManagedConnectorCommandEnvelopeDetail(
                latestMatchingCommand?.Description ?? latestRecordedCommand?.Description,
                executionAdapter.Description));
    }

    private static string CreateManagedConnectorNoMatchingHistoryCommandRetryDescription(
        string operationId,
        bool hasNoRecordedHistory,
        string? executionAdapterDescription,
        string? latestRecordedDescription)
    {
        var summary = hasNoRecordedHistory
            ? $"Cephalon does not currently recommend retrying {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because no matching command-execution outcome has been recorded yet. Use the shared command lane for the first attempt."
            : $"Cephalon does not currently recommend retrying {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the current command posture does not match any recorded command outcome.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(latestRecordedDescription, executionAdapterDescription));
    }

    private static string CreateManagedConnectorCooldownCommandRetryDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestMatchingCommand,
        DateTimeOffset cooldownUntilUtc)
    {
        ArgumentNullException.ThrowIfNull(latestMatchingCommand);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon recently recorded matching {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command attempt '{NormalizeManagedConnectorFingerprintSegment(latestMatchingCommand.AttemptId)}'. Wait until '{cooldownUntilUtc:O}' before reconsidering a retry.",
            latestMatchingCommand.Description);
    }

    private static string CreateManagedConnectorDuplicateCommandRetryDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestMatchingCommand,
        string? executionAdapterDescription)
    {
        ArgumentNullException.ThrowIfNull(latestMatchingCommand);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon already recorded matching {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command attempt '{NormalizeManagedConnectorFingerprintSegment(latestMatchingCommand.AttemptId)}'. Replaying it now would be duplicative until runtime truth changes.",
            CombineManagedConnectorCommandEnvelopeDetail(latestMatchingCommand.Description, executionAdapterDescription));
    }

    private static string CreateManagedConnectorRetryBlockedDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestMatchingCommand,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval)
    {
        ArgumentNullException.ThrowIfNull(latestMatchingCommand);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(executionApproval);

        var summary = executionApproval.IsApprovalRequired
            ? $"Cephalon recorded a prior {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} outcome, but a higher-risk approval gate still blocks a safe retry."
            : executionApproval.IsApprovalReady || executionAdapter.RequiresExplicitApproval
                ? $"Cephalon recorded a prior {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} outcome, but approval must still clear before a safe retry."
                : executionAdapter.IsUnavailable
                    ? $"Cephalon recorded a prior {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} outcome, but no provider execution adapter is currently available for a safe retry."
                    : $"Cephalon recorded a prior {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} outcome, but the current shared runtime truth still blocks a safe retry.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(latestMatchingCommand.Description, executionAdapter.Description));
    }

    private static string CreateManagedConnectorRetryEligibleDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestMatchingCommand,
        string? executionAdapterDescription)
    {
        ArgumentNullException.ThrowIfNull(latestMatchingCommand);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon recorded a prior {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} outcome and the current shared runtime truth now allows one safe retry.",
            CombineManagedConnectorCommandEnvelopeDetail(latestMatchingCommand.Description, executionAdapterDescription));
    }

    private static string CreateManagedConnectorOperatorOnlyCommandRetryDescription(
        string operationId,
        string? executionAdapterDescription,
        string? latestCommandDescription)
    {
        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon can track command history for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but retry remains operator-owned until a later managed control-plane slice ships.",
            CombineManagedConnectorCommandEnvelopeDetail(latestCommandDescription, executionAdapterDescription));
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus CreateManagedConnectorRetryExecutionPolicy(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        bool automaticRetryEnabled)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(commandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);

        var operationId = string.IsNullOrWhiteSpace(commandRetry.OperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyOperationIds.None
            : commandRetry.OperationId.Trim();
        var categories = CreateManagedConnectorRetryExecutionPolicyCategories(
            executionTopology,
            commandRetry,
            executionApproval,
            executionAdapter,
            automaticRetryEnabled);
        var sourceId = ResolveManagedConnectorRetryExecutionPolicySource(
            commandRetry,
            executionApproval,
            executionAdapter);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            executionIntent.IsDeferred ||
            !commandRetry.AppliesToManagedConnector)
        {
            return CreateManagedConnectorRetryExecutionPolicyStatus(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotApplicable,
                CreateManagedConnectorNotApplicableRetryExecutionPolicyDescription(
                    commandRetry.Description,
                    executionAdapter.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        if (commandRetry.IsOperatorOnly || executionAdapter.IsOperatorOnly)
        {
            return CreateManagedConnectorRetryExecutionPolicyStatus(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.OperatorOnly,
                CreateManagedConnectorOperatorOnlyRetryExecutionPolicyDescription(
                    operationId,
                    executionAdapter.Description,
                    commandRetry.Description),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        if (commandRetry.IsNotNeeded || commandRetry.IsDuplicate)
        {
            return CreateManagedConnectorRetryExecutionPolicyStatus(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotNeeded,
                CreateManagedConnectorNotNeededRetryExecutionPolicyDescription(
                    operationId,
                    commandRetry),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        if (commandRetry.IsCooldown)
        {
            return CreateManagedConnectorRetryExecutionPolicyStatus(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.Cooldown,
                CreateManagedConnectorCooldownRetryExecutionPolicyDescription(
                    operationId,
                    commandRetry),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        if (commandRetry.IsRetryBlocked &&
            (executionApproval.IsApprovalRequired ||
             executionApproval.IsApprovalReady ||
             commandRetry.RequiresExplicitApproval))
        {
            return CreateManagedConnectorRetryExecutionPolicyStatus(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.ManualApproval,
                CreateManagedConnectorManualApprovalRetryExecutionPolicyDescription(
                    operationId,
                    executionApproval,
                    commandRetry),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        if (commandRetry.IsRetryBlocked)
        {
            return CreateManagedConnectorRetryExecutionPolicyStatus(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.PolicyBlocked,
                CreateManagedConnectorPolicyBlockedRetryExecutionPolicyDescription(
                    operationId,
                    executionAdapter,
                    commandRetry),
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        if (commandRetry.IsRetryEligible)
        {
            var policyState = automaticRetryEnabled
                ? CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.RetryReady
                : CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.BackgroundRetryDisabled;
            var description = automaticRetryEnabled
                ? CreateManagedConnectorRetryReadyDescription(
                    operationId,
                    commandRetry)
                : CreateManagedConnectorBackgroundRetryDisabledDescription(
                    operationId,
                    commandRetry);

            return CreateManagedConnectorRetryExecutionPolicyStatus(
                policyState,
                description,
                categories,
                operationId,
                governance,
                reportingCoverage,
                remediation,
                drift,
                actionPlan,
                writePathReadiness,
                preflight,
                dryRun,
                executionIntent,
                executionApproval,
                commandEnvelope,
                commandIssuance,
                executionAdapter,
                commandExecution,
                commandRetry,
                sourceId,
                executionRuntimeId,
                cdcCaptureIds,
                automaticRetryEnabled);
        }

        return CreateManagedConnectorRetryExecutionPolicyStatus(
            CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotNeeded,
            CreateManagedConnectorNotNeededRetryExecutionPolicyDescription(
                operationId,
                commandRetry),
            categories,
            operationId,
            governance,
            reportingCoverage,
            remediation,
            drift,
            actionPlan,
            writePathReadiness,
            preflight,
            dryRun,
            executionIntent,
            executionApproval,
            commandEnvelope,
            commandIssuance,
            executionAdapter,
            commandExecution,
            commandRetry,
            sourceId,
            executionRuntimeId,
            cdcCaptureIds,
            automaticRetryEnabled);
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus CreateManagedConnectorRetryExecutionPolicyStatus(
        string state,
        string description,
        IReadOnlyList<string> categoryIds,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        string sourceId,
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        bool automaticRetryEnabled)
    {
        var normalizedOperationId = string.IsNullOrWhiteSpace(operationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyOperationIds.None
            : operationId.Trim();

        return new CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus(state, description)
        {
            CategoryIds = categoryIds,
            OperationId = normalizedOperationId,
            ManagementMode = governance.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            DryRunState = dryRun.State,
            ExecutionIntentState = executionIntent.State,
            ExecutionApprovalState = executionApproval.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            ExecutionAdapterState = executionAdapter.State,
            CommandRetryState = commandRetry.State,
            LatestCommandExecutionState = string.IsNullOrWhiteSpace(commandRetry.LatestCommandExecutionState)
                ? commandExecution.State
                : commandRetry.LatestCommandExecutionState.Trim(),
            PrimaryActionId = actionPlan.PrimaryActionId,
            SourceId = sourceId,
            CommandRetrySourceId = commandRetry.SourceId,
            ExecutionApprovalSourceId = executionApproval.SourceId,
            ExecutionAdapterSourceId = executionAdapter.SourceId,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ConnectClusterId = commandRetry.ConnectClusterId ?? executionAdapter.ConnectClusterId,
            ConnectorClass = commandRetry.ConnectorClass ?? executionAdapter.ConnectorClass,
            SourceProviderId = commandRetry.SourceProviderId ?? executionAdapter.SourceProviderId,
            PotentialChangeCount = commandRetry.PotentialChangeCount,
            WouldApplyChanges = commandRetry.WouldApplyChanges,
            RequiresExplicitApproval = commandRetry.RequiresExplicitApproval,
            LatestMatchingApprovalApplied = commandRetry.LatestMatchingApprovalApplied,
            IsDestructiveOperation = commandRetry.IsDestructiveOperation,
            LatestMatchingDestructiveAllowanceApplied = commandRetry.LatestMatchingDestructiveAllowanceApplied,
            CanReuseApprovalFromMatchingHistory = commandRetry.CanReuseApprovalFromMatchingHistory,
            CanReuseDestructiveAllowanceFromMatchingHistory = commandRetry.CanReuseDestructiveAllowanceFromMatchingHistory,
            IsAutomaticRetryEnabled = automaticRetryEnabled,
            CommandFingerprint = commandRetry.CommandFingerprint,
            IssuanceFingerprint = commandRetry.IssuanceFingerprint,
            AdapterFingerprint = commandRetry.AdapterFingerprint,
            RetryFingerprint = commandRetry.RetryFingerprint,
            LatestExecutionFingerprint = commandRetry.LatestExecutionFingerprint,
            LatestAttemptId = commandRetry.LatestAttemptId,
            LatestRecordedAtUtc = commandRetry.LatestRecordedAtUtc,
            CooldownUntilUtc = commandRetry.CooldownUntilUtc,
            HasMatchingRetryFingerprint = commandRetry.HasMatchingRetryFingerprint,
            HasMatchingCommandFingerprint = commandRetry.HasMatchingCommandFingerprint,
            HasMatchingIssuanceFingerprint = commandRetry.HasMatchingIssuanceFingerprint,
            HasMatchingAdapterFingerprint = commandRetry.HasMatchingAdapterFingerprint
        };
    }

    private static string[] CreateManagedConnectorRetryExecutionPolicyCategories(
        string executionTopology,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        bool automaticRetryEnabled)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(executionAdapter);

        var categories = new List<string>();

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        static void AddMirroredCategory(
            List<string> values,
            CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetryStatus,
            string retryCategory,
            string policyCategory)
        {
            if (commandRetryStatus.CategoryIds.Contains(retryCategory, StringComparer.OrdinalIgnoreCase))
            {
                AddCategory(values, policyCategory);
            }
        }

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ObserveOnlyMode, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ObserveOnlyMode);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.BlockingRemediation, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.BlockingRemediation);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.StaleObservation, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.StaleObservation);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.IncompleteReportingCoverage, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.IncompleteReportingCoverage);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.RuntimeTruthIncomplete, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.RuntimeTruthIncomplete);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.GovernanceOutOfPolicy, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.GovernanceOutOfPolicy);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ControlPlaneOwnershipGap, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ControlPlaneOwnershipGap);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.ChangePlanned, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ChangePlanned);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LifecycleChange, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.LifecycleChange);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.DestructiveOperation, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.DestructiveOperation);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.NoExecutionNeeded, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.NoExecutionNeeded);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.CooldownActive, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.CooldownActive);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.DuplicateCommand, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.DuplicateCommand);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.OperatorOnly, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.OperatorOnly);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionBlocked, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ProviderExecutionBlocked);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionUnavailable, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ProviderExecutionUnavailable);
        AddMirroredCategory(categories, commandRetry, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryCategories.LatestExecutionFailed, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ProviderExecutionFailed);

        if (executionApproval.IsApprovalRequired)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ManualApprovalRequired);
        }
        else if (executionApproval.IsApprovalReady || commandRetry.RequiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ManualApprovalReady);
        }

        if (commandRetry.IsRetryEligible)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.RetryCandidate);

            if (!automaticRetryEnabled)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.AutomaticRetryDisabled);
            }
        }

        if (executionAdapter.IsOperatorOnly || commandRetry.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.ControlPlaneOwnershipGap);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.OperatorOnly);
        }

        return [.. categories];
    }

    private static string ResolveManagedConnectorRetryExecutionPolicySource(
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(executionAdapter);

        if (commandRetry.IsRetryBlocked &&
            (executionApproval.IsApprovalRequired ||
             executionApproval.IsApprovalReady ||
             commandRetry.RequiresExplicitApproval))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicySources.ExecutionApproval;
        }

        if (commandRetry.IsOperatorOnly || executionAdapter.IsOperatorOnly)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicySources.ExecutionAdapter;
        }

        return commandRetry.AppliesToManagedConnector
            ? CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicySources.CommandRetry
            : CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicySources.Unknown;
    }

    private static string CreateManagedConnectorNotApplicableRetryExecutionPolicyDescription(
        string? commandRetryDescription,
        string? executionAdapterDescription)
    {
        return AppendManagedConnectorCommandEnvelopeDetail(
            "Cephalon does not currently expose automatic retry-execution policy while the shared runtime remains observe-only.",
            CombineManagedConnectorCommandEnvelopeDetail(commandRetryDescription, executionAdapterDescription));
    }

    private static string CreateManagedConnectorNotNeededRetryExecutionPolicyDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);

        var summary = commandRetry.IsDuplicate
            ? $"Cephalon does not currently schedule automatic {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry because replaying the matching command would be duplicative until runtime truth changes."
            : $"Cephalon does not currently schedule automatic {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry because the shared runtime truth indicates no further retry action is needed.";

        return AppendManagedConnectorCommandEnvelopeDetail(summary, commandRetry.Description);
    }

    private static string CreateManagedConnectorCooldownRetryExecutionPolicyDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);

        var summary = commandRetry.CooldownUntilUtc.HasValue
            ? $"Cephalon identified a matching {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry candidate, but retry-execution policy is waiting until '{commandRetry.CooldownUntilUtc.Value:O}' before reconsidering it."
            : $"Cephalon identified a matching {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry candidate, but retry-execution policy is still within its cooldown window.";

        return AppendManagedConnectorCommandEnvelopeDetail(summary, commandRetry.Description);
    }

    private static string CreateManagedConnectorManualApprovalRetryExecutionPolicyDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandRetry);

        var summary = executionApproval.IsApprovalRequired
            ? $"Cephalon identified a retry candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but a higher-risk manual approval gate still blocks automatic retry."
            : $"Cephalon identified a retry candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but manual approval must clear before retry-execution policy can act on it.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(executionApproval.Description, commandRetry.Description));
    }

    private static string CreateManagedConnectorPolicyBlockedRetryExecutionPolicyDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(commandRetry);

        var summary = executionAdapter.IsUnavailable
            ? $"Cephalon identified a retry candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but no provider execution adapter is currently available."
            : executionAdapter.IsBlocked
                ? $"Cephalon identified a retry candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but shared runtime truth still blocks a safe retry."
                : $"Cephalon identified a retry candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but current retry-execution policy still blocks automatic retry.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(executionAdapter.Description, commandRetry.Description));
    }

    private static string CreateManagedConnectorBackgroundRetryDisabledDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon identified one safe {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry candidate, but automatic background retry remains disabled in the current engine policy baseline.",
            commandRetry.Description);
    }

    private static string CreateManagedConnectorRetryReadyDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon identified one safe {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry candidate and the current engine policy allows automatic retry.",
            commandRetry.Description);
    }

    private static string CreateManagedConnectorOperatorOnlyRetryExecutionPolicyDescription(
        string operationId,
        string? executionAdapterDescription,
        string? commandRetryDescription)
    {
        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon can evaluate retry policy for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but execution remains operator-owned until a later managed control-plane slice ships.",
            CombineManagedConnectorCommandEnvelopeDetail(commandRetryDescription, executionAdapterDescription));
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus CreateManagedConnectorCommandJournal(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        ManagedConnectorCommandExecutionJournal commandJournal)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(commandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var state = ResolveManagedConnectorCommandJournalState(
            executionTopology,
            commandExecution,
            commandRetry,
            retryExecutionPolicy,
            commandJournal);
        var categories = CreateManagedConnectorCommandJournalCategories(
            executionTopology,
            reportingCoverage,
            governance,
            commandExecution,
            commandRetry,
            retryExecutionPolicy,
            commandJournal);
        var operationId = ResolveManagedConnectorCommandJournalOperationId(
            retryExecutionPolicy.OperationId,
            commandRetry.OperationId,
            commandExecution.RequestedOperationId,
            commandExecution.ResolvedOperationId);
        var sourceId = ResolveManagedConnectorCommandJournalSource(
            state,
            commandRetry,
            retryExecutionPolicy);
        var latestEntry = commandJournal.LatestEntry;
        var oldestRetainedEntry = commandJournal.OldestRetainedEntry;
        var description = state switch
        {
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable =>
                CreateManagedConnectorNotApplicableCommandJournalDescription(
                    commandRetry.Description,
                    retryExecutionPolicy.Description),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty =>
                CreateManagedConnectorEmptyCommandJournalDescription(
                    commandJournal,
                    commandExecution.Description,
                    retryExecutionPolicy.Description),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Truncated =>
                CreateManagedConnectorTruncatedCommandJournalDescription(
                    operationId,
                    commandJournal,
                    latestEntry?.Description,
                    retryExecutionPolicy.Description),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.CooldownActive =>
                CreateManagedConnectorCooldownActiveCommandJournalDescription(
                    operationId,
                    commandJournal,
                    commandRetry,
                    retryExecutionPolicy),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.DuplicateEvidencePresent =>
                CreateManagedConnectorDuplicateEvidenceCommandJournalDescription(
                    operationId,
                    commandJournal,
                    commandRetry,
                    retryExecutionPolicy),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.InsufficientForAutomation =>
                CreateManagedConnectorInsufficientAutomationCommandJournalDescription(
                    operationId,
                    retryExecutionPolicy,
                    commandRetry),
            _ => CreateManagedConnectorBoundedCommandJournalDescription(
                operationId,
                commandJournal,
                commandExecution.Description,
                commandRetry.Description)
        };

        return CreateManagedConnectorCommandJournalStatus(
            state,
            description,
            categories,
            operationId,
            governance,
            reportingCoverage,
            remediation,
            drift,
            actionPlan,
            writePathReadiness,
            preflight,
            dryRun,
            executionIntent,
            executionApproval,
            commandEnvelope,
            commandIssuance,
            executionAdapter,
            commandExecution,
            commandRetry,
            retryExecutionPolicy,
            sourceId,
            executionRuntimeId,
            cdcCaptureIds,
            commandJournal,
            latestEntry,
            oldestRetainedEntry);
    }

    private static string ResolveManagedConnectorCommandJournalState(
        string executionTopology,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        ManagedConnectorCommandExecutionJournal commandJournal)
    {
        ArgumentNullException.ThrowIfNull(commandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(commandExecution.State, CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(commandRetry.State, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(retryExecutionPolicy.State, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable;
        }

        if (!commandJournal.HasRecordedEntries)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty;
        }

        if (commandJournal.IsTruncated)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Truncated;
        }

        if (commandRetry.IsCooldown || retryExecutionPolicy.IsCooldown)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.CooldownActive;
        }

        if (commandRetry.IsDuplicate ||
            retryExecutionPolicy.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.DuplicateCommand,
                StringComparer.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.DuplicateEvidencePresent;
        }

        if (retryExecutionPolicy.IsOperatorOnly ||
            retryExecutionPolicy.IsPolicyBlocked ||
            retryExecutionPolicy.RequiresManualApproval ||
            retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.InsufficientForAutomation;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Bounded;
    }

    private static string[] CreateManagedConnectorCommandJournalCategories(
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        ManagedConnectorCommandExecutionJournal commandJournal)
    {
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(commandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        if (string.Equals(commandExecution.State, CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(commandRetry.State, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(retryExecutionPolicy.State, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.ObserveOnlyMode];
        }

        var categories = new List<string>(capacity: 16);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        if (!commandJournal.HasRecordedEntries)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.NoRecordedCommand);
            return [.. categories];
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.BoundedRetention);

        if (commandJournal.IsTruncated)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.HistoryTruncated);
        }

        if (!reportingCoverage.HasFullCoverage ||
            retryExecutionPolicy.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.RuntimeTruthIncomplete);
        }

        if (governance.IsOutOfPolicy ||
            retryExecutionPolicy.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.GovernanceOutOfPolicy,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.GovernanceOutOfPolicy);
        }

        if (commandRetry.HasMatchingCommandFingerprint || retryExecutionPolicy.HasMatchingCommandFingerprint)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.MatchingCommandFingerprint);
        }

        if (commandRetry.HasCooldownWindow || retryExecutionPolicy.HasCooldownWindow)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.CooldownActive);
        }

        if (commandRetry.IsDuplicate ||
            retryExecutionPolicy.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.DuplicateCommand,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.DuplicateCommand);
        }

        if (commandRetry.IsOperatorOnly || retryExecutionPolicy.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.ControlPlaneOwnershipGap);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.OperatorOnly);
        }

        if (retryExecutionPolicy.IsPolicyBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.PolicyBlocked);
        }

        if (retryExecutionPolicy.RequiresManualApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.ManualApprovalRequired);
        }

        if (retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.AutomaticRetryDisabled);
        }

        if (!commandExecution.WouldApplyChanges ||
            retryExecutionPolicy.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyCategories.NoExecutionNeeded,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.NoExecutionNeeded);
        }

        if (commandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.LatestExecutionBlocked);
        }
        else if (commandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.LatestExecutionUnavailable);
        }
        else if (commandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.LatestExecutionFailed);
        }
        else if (commandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.LatestExecutionAdapted);
        }

        return [.. categories];
    }

    private static string ResolveManagedConnectorCommandJournalSource(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy)
    {
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        return state switch
        {
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.CooldownActive or
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.DuplicateEvidencePresent =>
                CdcCaptureExecutionRuntimeManagedConnectorCommandJournalSources.CommandRetry,
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.InsufficientForAutomation =>
                CdcCaptureExecutionRuntimeManagedConnectorCommandJournalSources.RetryExecutionPolicy,
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable =>
                CdcCaptureExecutionRuntimeManagedConnectorCommandJournalSources.Unknown,
            _ => CdcCaptureExecutionRuntimeManagedConnectorCommandJournalSources.CommandExecutionHistory
        };
    }

    private static string ResolveManagedConnectorCommandJournalOperationId(
        string? retryExecutionPolicyOperationId,
        string? commandRetryOperationId,
        string? requestedOperationId,
        string? resolvedOperationId)
    {
        if (!string.IsNullOrWhiteSpace(retryExecutionPolicyOperationId))
        {
            return retryExecutionPolicyOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(commandRetryOperationId))
        {
            return commandRetryOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(requestedOperationId))
        {
            return requestedOperationId.Trim();
        }

        return string.IsNullOrWhiteSpace(resolvedOperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandJournalOperationIds.None
            : resolvedOperationId.Trim();
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus CreateManagedConnectorCommandJournalStatus(
        string state,
        string description,
        IReadOnlyList<string> categoryIds,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        string sourceId,
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        ManagedConnectorCommandExecutionJournal commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestEntry,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? oldestRetainedEntry)
    {
        var normalizedOperationId = string.IsNullOrWhiteSpace(operationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandJournalOperationIds.None
            : operationId.Trim();
        var commandFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.CommandFingerprint)
            ? retryExecutionPolicy.CommandFingerprint
            : commandRetry.CommandFingerprint;
        var retryFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.RetryFingerprint)
            ? retryExecutionPolicy.RetryFingerprint
            : commandRetry.RetryFingerprint;

        return new CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus(state, description)
        {
            CategoryIds = categoryIds,
            OperationId = normalizedOperationId,
            ManagementMode = retryExecutionPolicy.ManagementMode ?? commandRetry.ManagementMode ?? commandExecution.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            DryRunState = dryRun.State,
            ExecutionIntentState = executionIntent.State,
            ExecutionApprovalState = executionApproval.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = commandExecution.State,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            PrimaryActionId = actionPlan.PrimaryActionId,
            SourceId = sourceId,
            CommandRetrySourceId = commandRetry.SourceId,
            RetryExecutionPolicySourceId = retryExecutionPolicy.SourceId,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ConnectClusterId = retryExecutionPolicy.ConnectClusterId ?? commandRetry.ConnectClusterId ?? commandExecution.ConnectClusterId,
            ConnectorClass = retryExecutionPolicy.ConnectorClass ?? commandRetry.ConnectorClass ?? commandExecution.ConnectorClass,
            SourceProviderId = retryExecutionPolicy.SourceProviderId ?? commandRetry.SourceProviderId ?? commandExecution.SourceProviderId,
            TotalRecordedEntryCount = commandJournal.TotalRecordedEntryCount,
            RetainedEntryCount = commandJournal.RetainedEntryCount,
            MaximumRetainedEntryCount = commandJournal.MaximumRetainedEntryCount,
            PotentialChangeCount = Math.Max(retryExecutionPolicy.PotentialChangeCount, commandRetry.PotentialChangeCount),
            WouldApplyChanges = retryExecutionPolicy.WouldApplyChanges || commandRetry.WouldApplyChanges || commandExecution.WouldApplyChanges,
            RequiresExplicitApproval = retryExecutionPolicy.RequiresExplicitApproval || commandRetry.RequiresExplicitApproval || commandExecution.RequiresExplicitApproval,
            IsDestructiveOperation = retryExecutionPolicy.IsDestructiveOperation || commandRetry.IsDestructiveOperation || commandExecution.IsDestructiveOperation,
            IsAutomaticRetryEnabled = retryExecutionPolicy.IsAutomaticRetryEnabled,
            CommandFingerprint = commandFingerprint,
            RetryFingerprint = retryFingerprint,
            LatestExecutionFingerprint = latestEntry?.ExecutionFingerprint ?? commandRetry.LatestExecutionFingerprint,
            LatestAttemptId = latestEntry?.AttemptId ?? commandRetry.LatestAttemptId,
            OldestRetainedAttemptId = oldestRetainedEntry?.AttemptId ?? string.Empty,
            LatestRecordedAtUtc = latestEntry?.RecordedAtUtc ?? commandRetry.LatestRecordedAtUtc,
            OldestRetainedRecordedAtUtc = oldestRetainedEntry?.RecordedAtUtc,
            CooldownUntilUtc = retryExecutionPolicy.CooldownUntilUtc ?? commandRetry.CooldownUntilUtc,
            HasMatchingRetryFingerprint = commandRetry.HasMatchingRetryFingerprint || retryExecutionPolicy.HasMatchingRetryFingerprint,
            HasMatchingCommandFingerprint = commandRetry.HasMatchingCommandFingerprint || retryExecutionPolicy.HasMatchingCommandFingerprint
        };
    }

    private static string CreateManagedConnectorNotApplicableCommandJournalDescription(
        string? commandRetryDescription,
        string? retryExecutionPolicyDescription)
    {
        return AppendManagedConnectorCommandEnvelopeDetail(
            "Cephalon does not currently expose a managed-connector command journal while the shared runtime remains observe-only.",
            CombineManagedConnectorCommandEnvelopeDetail(commandRetryDescription, retryExecutionPolicyDescription));
    }

    private static string CreateManagedConnectorEmptyCommandJournalDescription(
        ManagedConnectorCommandExecutionJournal commandJournal,
        string? commandExecutionDescription,
        string? retryExecutionPolicyDescription)
    {
        ArgumentNullException.ThrowIfNull(commandJournal);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon has not yet recorded any managed-connector command outcomes for this runtime. The bounded journal is empty and can retain up to {commandJournal.MaximumRetainedEntryCount} recent entries once commands are recorded.",
            CombineManagedConnectorCommandEnvelopeDetail(commandExecutionDescription, retryExecutionPolicyDescription));
    }

    private static string CreateManagedConnectorTruncatedCommandJournalDescription(
        string operationId,
        ManagedConnectorCommandExecutionJournal commandJournal,
        string? latestCommandDescription,
        string? retryExecutionPolicyDescription)
    {
        ArgumentNullException.ThrowIfNull(commandJournal);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon retains only the newest {commandJournal.RetainedEntryCount} of {commandJournal.TotalRecordedEntryCount} recorded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command outcomes. Older entries have been truncated from the bounded journal.",
            CombineManagedConnectorCommandEnvelopeDetail(latestCommandDescription, retryExecutionPolicyDescription));
    }

    private static string CreateManagedConnectorCooldownActiveCommandJournalDescription(
        string operationId,
        ManagedConnectorCommandExecutionJournal commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy)
    {
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        var cooldownUntilUtc = retryExecutionPolicy.CooldownUntilUtc ?? commandRetry.CooldownUntilUtc;
        var summary = cooldownUntilUtc.HasValue
            ? $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command evidence, and matching recent history remains inside the cooldown window until '{cooldownUntilUtc.Value:O}'."
            : $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command evidence, and matching recent history still remains inside an active cooldown window.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(commandRetry.Description, retryExecutionPolicy.Description));
    }

    private static string CreateManagedConnectorDuplicateEvidenceCommandJournalDescription(
        string operationId,
        ManagedConnectorCommandExecutionJournal commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy)
    {
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        var latestAttemptId = NormalizeManagedConnectorFingerprintSegment(commandJournal.LatestEntry?.AttemptId);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command history showing matching prior attempt '{latestAttemptId}'. Replaying it now would be duplicative until shared runtime truth changes.",
            CombineManagedConnectorCommandEnvelopeDetail(commandRetry.Description, retryExecutionPolicy.Description));
    }

    private static string CreateManagedConnectorInsufficientAutomationCommandJournalDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry)
    {
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandRetry);

        string summary;
        if (retryExecutionPolicy.IsOperatorOnly)
        {
            summary = $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command history, but execution remains operator-owned until a later managed control-plane slice ships.";
        }
        else if (retryExecutionPolicy.RequiresManualApproval)
        {
            summary = $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command history, but manual approval must clear before automation should continue.";
        }
        else if (retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            summary = $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command history, but automatic background retry remains disabled in the current engine policy baseline.";
        }
        else
        {
            summary = $"Cephalon retains bounded {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command history, but current shared runtime truth still leaves the journal insufficient for automation.";
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, commandRetry.Description));
    }

    private static string CreateManagedConnectorBoundedCommandJournalDescription(
        string operationId,
        ManagedConnectorCommandExecutionJournal commandJournal,
        string? commandExecutionDescription,
        string? commandRetryDescription)
    {
        ArgumentNullException.ThrowIfNull(commandJournal);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon retains {commandJournal.RetainedEntryCount} recent {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} command outcome(s) in the bounded journal, and the retained evidence remains sufficient for operator-facing retry and idempotency answers.",
            CombineManagedConnectorCommandEnvelopeDetail(commandExecutionDescription, commandRetryDescription));
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus CreateManagedConnectorAutomaticRetryExecution(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionTopology,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult commandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        ManagedConnectorCommandExecutionJournal commandExecutionHistoryJournal,
        bool automaticRetryEnabled)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(commandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandExecutionHistoryJournal);

        var operationId = string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
            ? string.IsNullOrWhiteSpace(commandJournal.OperationId)
                ? string.IsNullOrWhiteSpace(commandRetry.OperationId)
                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
                    : commandRetry.OperationId.Trim()
                : commandJournal.OperationId.Trim()
            : retryExecutionPolicy.OperationId.Trim();
        var commandFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.CommandFingerprint)
            ? retryExecutionPolicy.CommandFingerprint
            : commandJournal.CommandFingerprint;
        var expectedIssuanceFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.IssuanceFingerprint)
            ? retryExecutionPolicy.IssuanceFingerprint
            : commandExecution.IssuanceFingerprint;
        var expectedAdapterFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.AdapterFingerprint)
            ? retryExecutionPolicy.AdapterFingerprint
            : commandExecution.AdapterFingerprint;
        var retryFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.RetryFingerprint)
            ? retryExecutionPolicy.RetryFingerprint
            : commandJournal.RetryFingerprint;
        var latestAutomaticExecution = commandExecutionHistoryJournal.Entries.FirstOrDefault(static entry => entry.IsAutomaticRetryInvocation);
        var latestMatchingAutomaticExecution = commandExecutionHistoryJournal.Entries.FirstOrDefault(entry =>
            entry.IsAutomaticRetryInvocation &&
            (string.Equals(entry.RequestedOperationId, operationId, StringComparison.OrdinalIgnoreCase) ||
             string.Equals(entry.ResolvedOperationId, operationId, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrWhiteSpace(commandFingerprint) ||
             string.Equals(entry.CommandFingerprint, commandFingerprint, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrWhiteSpace(expectedIssuanceFingerprint) ||
             string.Equals(entry.IssuanceFingerprint, expectedIssuanceFingerprint, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrWhiteSpace(expectedAdapterFingerprint) ||
             string.Equals(entry.AdapterFingerprint, expectedAdapterFingerprint, StringComparison.OrdinalIgnoreCase)));

        var state =
            !string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            executionIntent.IsDeferred ||
            !retryExecutionPolicy.AppliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.NotApplicable
                : latestMatchingAutomaticExecution is not null
                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Completed
                    : !automaticRetryEnabled || retryExecutionPolicy.IsBackgroundRetryDisabled
                        ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Disabled
                        : retryExecutionPolicy.CanExecuteRetryThroughPolicy
                            ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Eligible
                            : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Blocked;

        var categories = CreateManagedConnectorAutomaticRetryExecutionCategories(
            executionTopology,
            retryExecutionPolicy,
            commandJournal,
            latestAutomaticExecution,
            latestMatchingAutomaticExecution,
            automaticRetryEnabled);
        var sourceId =
            latestMatchingAutomaticExecution is not null || latestAutomaticExecution is not null
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionSources.AutomaticRetryHistory
                : retryExecutionPolicy.AppliesToManagedConnector
                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionSources.RetryExecutionPolicy
                    : commandJournal.AppliesToManagedConnector
                        ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionSources.CommandJournal
                        : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionSources.Unknown;
        var description = state switch
        {
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.NotApplicable =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon does not currently expose automatic background retry execution while the shared runtime remains observe-only.",
                    CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, commandJournal.Description)),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Disabled =>
                !automaticRetryEnabled
                    ? AppendManagedConnectorCommandEnvelopeDetail(
                        $"Cephalon identified shared managed-connector retry posture for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but automatic background retry is disabled by the current data runtime options.",
                        CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, commandJournal.Description))
                    : AppendManagedConnectorCommandEnvelopeDetail(
                        $"Cephalon identified a safe {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} retry candidate, but automatic background retry remains disabled in the current shared retry-execution policy baseline.",
                        CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, commandJournal.Description)),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Eligible =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    $"Cephalon can now run one automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the shared retry-execution policy is retry-ready and the bounded journal does not yet contain a matching automatic attempt.",
                    CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, commandJournal.Description)),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStates.Completed =>
                CreateManagedConnectorCompletedAutomaticRetryExecutionDescription(
                    operationId,
                    latestMatchingAutomaticExecution ?? latestAutomaticExecution,
                    retryExecutionPolicy.Description,
                    commandJournal.Description),
            _ => CreateManagedConnectorBlockedAutomaticRetryExecutionDescription(
                operationId,
                retryExecutionPolicy,
                commandJournal)
        };

        return new CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus(state, description)
        {
            CategoryIds = categories,
            OperationId = string.IsNullOrWhiteSpace(operationId)
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
                : operationId,
            ManagementMode = retryExecutionPolicy.ManagementMode ?? commandJournal.ManagementMode ?? commandExecution.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            DryRunState = dryRun.State,
            ExecutionIntentState = executionIntent.State,
            ExecutionApprovalState = executionApproval.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = commandExecution.State,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            PrimaryActionId = actionPlan.PrimaryActionId,
            SourceId = sourceId,
            RetryExecutionPolicySourceId = retryExecutionPolicy.SourceId,
            CommandJournalSourceId = commandJournal.SourceId,
            LatestCommandExecutionInvocationSourceId = commandExecution.InvocationSourceId,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ConnectClusterId = retryExecutionPolicy.ConnectClusterId ?? commandJournal.ConnectClusterId ?? commandExecution.ConnectClusterId,
            ConnectorClass = retryExecutionPolicy.ConnectorClass ?? commandJournal.ConnectorClass ?? commandExecution.ConnectorClass,
            SourceProviderId = retryExecutionPolicy.SourceProviderId ?? commandJournal.SourceProviderId ?? commandExecution.SourceProviderId,
            PotentialChangeCount = Math.Max(retryExecutionPolicy.PotentialChangeCount, commandJournal.PotentialChangeCount),
            WouldApplyChanges = retryExecutionPolicy.WouldApplyChanges || commandJournal.WouldApplyChanges || commandExecution.WouldApplyChanges,
            RequiresExplicitApproval = retryExecutionPolicy.RequiresExplicitApproval || commandJournal.RequiresExplicitApproval || commandExecution.RequiresExplicitApproval,
            LatestMatchingApprovalApplied = retryExecutionPolicy.LatestMatchingApprovalApplied,
            IsDestructiveOperation = retryExecutionPolicy.IsDestructiveOperation || commandJournal.IsDestructiveOperation || commandExecution.IsDestructiveOperation,
            LatestMatchingDestructiveAllowanceApplied = retryExecutionPolicy.LatestMatchingDestructiveAllowanceApplied,
            CanReuseApprovalFromMatchingHistory = retryExecutionPolicy.CanReuseApprovalFromMatchingHistory,
            CanReuseDestructiveAllowanceFromMatchingHistory = retryExecutionPolicy.CanReuseDestructiveAllowanceFromMatchingHistory,
            IsAutomaticRetryEnabled = automaticRetryEnabled,
            CommandFingerprint = commandFingerprint,
            RetryFingerprint = retryFingerprint,
            LatestExecutionFingerprint = latestMatchingAutomaticExecution?.ExecutionFingerprint ?? latestAutomaticExecution?.ExecutionFingerprint ?? commandExecution.ExecutionFingerprint,
            LatestAttemptId = latestMatchingAutomaticExecution?.AttemptId ?? latestAutomaticExecution?.AttemptId ?? string.Empty,
            LatestRecordedAtUtc = latestMatchingAutomaticExecution?.RecordedAtUtc ?? latestAutomaticExecution?.RecordedAtUtc,
            CooldownUntilUtc = retryExecutionPolicy.CooldownUntilUtc ?? commandJournal.CooldownUntilUtc,
            HasAutomaticRetryAttempt = latestAutomaticExecution is not null,
            HasMatchingAutomaticRetryAttempt = latestMatchingAutomaticExecution is not null,
            LatestAutomaticRetryState = latestAutomaticExecution?.State ?? CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Unrecorded,
            LatestAutomaticRetryAttemptId = latestAutomaticExecution?.AttemptId ?? string.Empty,
            LatestAutomaticRetryRecordedAtUtc = latestAutomaticExecution?.RecordedAtUtc,
            LatestAutomaticRetryExecutionFingerprint = latestAutomaticExecution?.ExecutionFingerprint ?? string.Empty
        };
    }

    private static string[] CreateManagedConnectorAutomaticRetryExecutionCategories(
        string executionTopology,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestAutomaticExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestMatchingAutomaticExecution,
        bool automaticRetryEnabled)
    {
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>();

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        if (commandJournal.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandJournalCategories.ObserveOnlyMode,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.ObserveOnlyMode);
        }

        if (!automaticRetryEnabled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.FeatureDisabled);
        }

        if (retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.PolicyDisabled);
        }

        if (retryExecutionPolicy.CanExecuteRetryThroughPolicy)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.RetryReady);
        }

        if (retryExecutionPolicy.IsCooldown || string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.CooldownActive, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.CooldownActive);
        }

        if (retryExecutionPolicy.RequiresManualApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.ManualApprovalRequired);
        }

        if (retryExecutionPolicy.IsPolicyBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.PolicyBlocked);
        }

        if (retryExecutionPolicy.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.OperatorOnly);
        }

        if (retryExecutionPolicy.IsNotNeeded)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.NoExecutionNeeded);
        }

        if (latestAutomaticExecution is not null)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.AutomaticAttemptRecorded);
        }

        if (latestMatchingAutomaticExecution is not null)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.MatchingAutomaticAttempt);
        }

        switch (latestMatchingAutomaticExecution?.State)
        {
            case CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.NoOp:
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.LatestExecutionNoOp);
                break;
            case CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Adapted:
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.LatestExecutionAdapted);
                break;
            case CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Blocked:
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.LatestExecutionBlocked);
                break;
            case CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Unavailable:
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.LatestExecutionUnavailable);
                break;
            case CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Failed:
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionCategories.LatestExecutionFailed);
                break;
        }

        return [.. categories];
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus CreateManagedConnectorAutomaticRetryCoordination(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        string? coordinationOwnerId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedCoordinationOwnerId = string.IsNullOrWhiteSpace(coordinationOwnerId)
            ? null
            : coordinationOwnerId.Trim();
        var reporterCoordination = summary.ReporterCoordination;
        var hasCoordinationOwner = !string.IsNullOrWhiteSpace(normalizedCoordinationOwnerId);
        var hasActiveReporterLease =
            !string.IsNullOrWhiteSpace(summary.ActiveReporterId) &&
            summary.ReporterLeaseExpiresAtUtc.HasValue;
        var usesReporterLeaseCoordination =
            string.Equals(normalizedExecutionOwnership, "external-managed", StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(
                reporterCoordination.State,
                CdcCaptureReporterCoordinationStates.NotConfigured,
                StringComparison.OrdinalIgnoreCase);

        var state =
            !string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            !automaticRetryExecution.AppliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.NotApplicable
                : retryExecutionPolicy.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.OperatorOnly
                    : string.Equals(
                            reporterCoordination.State,
                            CdcCaptureReporterCoordinationStates.Conflicted,
                            StringComparison.OrdinalIgnoreCase) ||
                      reporterCoordination.HasMultipleActiveReporters ||
                      string.Equals(
                            reporterCoordination.DegradedReason,
                            CdcCaptureReporterCoordinationIssueReasons.MultipleActiveReporters,
                            StringComparison.OrdinalIgnoreCase) ||
                      string.Equals(
                            reporterCoordination.DegradedReason,
                            CdcCaptureReporterCoordinationIssueReasons.RejectedReporterConflict,
                            StringComparison.OrdinalIgnoreCase)
                        ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Conflicted
                        : usesReporterLeaseCoordination
                            ? !hasActiveReporterLease ||
                              string.Equals(
                                  reporterCoordination.State,
                                  CdcCaptureReporterCoordinationStates.LeaseExpired,
                                  StringComparison.OrdinalIgnoreCase) ||
                              reporterCoordination.RequiresTakeover
                                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseMissing
                                : !hasCoordinationOwner
                                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Uncoordinated
                                    : string.Equals(
                                            normalizedCoordinationOwnerId,
                                            summary.ActiveReporterId,
                                            StringComparison.OrdinalIgnoreCase)
                                        ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseHeld
                                        : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Uncoordinated
                            : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.SingleNode;

        var categories = CreateManagedConnectorAutomaticRetryCoordinationCategories(
            state,
            usesReporterLeaseCoordination,
            hasCoordinationOwner,
            hasActiveReporterLease,
            normalizedCoordinationOwnerId,
            summary.ActiveReporterId,
            retryExecutionPolicy);
        var description = CreateManagedConnectorAutomaticRetryCoordinationDescription(
            state,
            normalizedCoordinationOwnerId,
            summary.ActiveReporterId,
            reporterCoordination,
            automaticRetryExecution,
            retryExecutionPolicy);
        var sourceId = ResolveManagedConnectorAutomaticRetryCoordinationSourceId(
            state,
            hasCoordinationOwner);

        return new CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            CoordinationOwnerId = automaticRetryExecution.AppliesToManagedConnector ? normalizedCoordinationOwnerId : null,
            ActiveReporterId = summary.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = summary.ReporterLeaseExpiresAtUtc,
            ReporterCoordinationState = reporterCoordination.State,
            ReporterCoordinationIssueReason = reporterCoordination.DegradedReason,
            ReporterTakeoverState = reporterCoordination.TakeoverState,
            AutomaticRetryExecutionState = automaticRetryExecution.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            SourceId = sourceId,
            ObservedEdgeNodeIds = summary.ObservedEdgeNodeIds
        };
    }

    private static string[] CreateManagedConnectorAutomaticRetryCoordinationCategories(
        string state,
        bool usesReporterLeaseCoordination,
        bool hasCoordinationOwner,
        bool hasActiveReporterLease,
        string? coordinationOwnerId,
        string? activeReporterId,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>();

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(
            categories,
            usesReporterLeaseCoordination
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.LeaseCoordinatedRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.SingleNodeRuntime);

        AddCategory(
            categories,
            hasCoordinationOwner
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.CoordinationOwnerConfigured
                : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.CoordinationOwnerMissing);

        if (retryExecutionPolicy.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.OperatorOnly);
        }

        if (hasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.ActiveReporterVisible);
        }
        else if (usesReporterLeaseCoordination)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.LeaseMissing);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Conflicted, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.ReporterConflict);
        }

        if (!string.IsNullOrWhiteSpace(coordinationOwnerId) &&
            !string.IsNullOrWhiteSpace(activeReporterId))
        {
            AddCategory(
                categories,
                string.Equals(coordinationOwnerId, activeReporterId, StringComparison.OrdinalIgnoreCase)
                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.OwnerMatch
                    : CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.OwnerMismatch);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseHeld, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationCategories.ActiveLeaseHeld);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorAutomaticRetryCoordinationDescription(
        string state,
        string? coordinationOwnerId,
        string? activeReporterId,
        CdcCaptureReporterCoordinationStatus reporterCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(reporterCoordination);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        var detail = string.Equals(
            state,
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.OperatorOnly,
            StringComparison.OrdinalIgnoreCase)
            ? CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, automaticRetryExecution.Description)
            : CombineManagedConnectorCommandEnvelopeDetail(reporterCoordination.Description, automaticRetryExecution.Description);

        return state switch
        {
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.NotApplicable =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon does not currently require automatic background retry coordination for this execution runtime.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.SingleNode =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon can evaluate automatic background retry on the current node without reporter-lease coordination.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseHeld =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    $"Reporter '{NormalizeManagedConnectorFingerprintSegment(activeReporterId)}' currently holds the active reporter lease for this execution runtime, so the current node can evaluate automatic background retry safely.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseMissing =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon cannot safely run automatic background retry on the current node because no active reporter lease is currently visible for the execution runtime.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Conflicted =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon cannot safely run automatic background retry while reporter coordination remains conflicted for the execution runtime.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.OperatorOnly =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon can observe automatic retry posture for this managed connector, but control-plane ownership still remains operator-owned outside Cephalon.",
                    detail),
            _ => string.IsNullOrWhiteSpace(coordinationOwnerId)
                ? AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon identified automatic retry posture for this managed connector, but the current host did not declare a local coordination owner id, so background retry remains uncoordinated on this node.",
                    detail)
                : AppendManagedConnectorCommandEnvelopeDetail(
                    $"Reporter '{NormalizeManagedConnectorFingerprintSegment(activeReporterId)}' currently holds the active reporter lease, but the current host declares coordination owner '{NormalizeManagedConnectorFingerprintSegment(coordinationOwnerId)}', so automatic background retry remains uncoordinated on this node.",
                    detail)
        };
    }

    private static string ResolveManagedConnectorAutomaticRetryCoordinationSourceId(
        string state,
        bool hasCoordinationOwner)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationSources.AutomaticRetryExecution;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.SingleNode, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationSources.ExecutionOwnership;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Conflicted, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseMissing, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationSources.ReporterCoordination;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.LeaseHeld, StringComparison.OrdinalIgnoreCase) ||
            (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStates.Uncoordinated, StringComparison.OrdinalIgnoreCase) && hasCoordinationOwner))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationSources.CoordinationOwner;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus CreateManagedConnectorCommandJournalDurability(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        ManagedConnectorCommandExecutionJournalDurabilitySnapshot durabilitySnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);

        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var state = ResolveManagedConnectorCommandJournalDurabilityState(
            normalizedExecutionTopology,
            commandJournal,
            durabilitySnapshot);
        var categories = CreateManagedConnectorCommandJournalDurabilityCategories(
            state,
            commandJournal,
            automaticRetryExecution,
            automaticRetryCoordination,
            durabilitySnapshot);
        var description = CreateManagedConnectorCommandJournalDurabilityDescription(
            state,
            commandJournal,
            automaticRetryExecution,
            automaticRetryCoordination,
            durabilitySnapshot);
        var sourceId = ResolveManagedConnectorCommandJournalDurabilitySourceId(
            state,
            durabilitySnapshot);

        return new CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            CommandJournalState = commandJournal.State,
            AutomaticRetryExecutionState = automaticRetryExecution.State,
            AutomaticRetryCoordinationState = automaticRetryCoordination.State,
            SourceId = sourceId,
            PersistencePath = durabilitySnapshot.PersistencePath,
            LastRecoveredAtUtc = durabilitySnapshot.LastRecoveredAtUtc,
            LastPersistedAtUtc = durabilitySnapshot.LastPersistedAtUtc,
            LastRecoveryError = durabilitySnapshot.LastRecoveryError,
            LastPersistenceError = durabilitySnapshot.LastPersistenceError,
            TotalRecordedEntryCount = commandJournal.TotalRecordedEntryCount,
            RetainedEntryCount = commandJournal.RetainedEntryCount,
            MaximumRetainedEntryCount = commandJournal.MaximumRetainedEntryCount,
            HasDurableStoreConfigured = durabilitySnapshot.HasDurableStoreConfigured,
            HasPersistedSnapshot = durabilitySnapshot.HasPersistedSnapshot,
            HasPersistedRecordedHistory = durabilitySnapshot.HasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = durabilitySnapshot.HasRecoveredPersistedHistory
        };
    }

    private static string ResolveManagedConnectorCommandJournalDurabilityState(
        string executionTopology,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        ManagedConnectorCommandExecutionJournalDurabilitySnapshot durabilitySnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionTopology);
        ArgumentNullException.ThrowIfNull(commandJournal);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            !commandJournal.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.NotApplicable;
        }

        if (durabilitySnapshot.HasRecoveryError)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.RecoveryFailed;
        }

        if (durabilitySnapshot.HasPersistenceError)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.PersistenceFailed;
        }

        if (!durabilitySnapshot.HasDurableStoreConfigured)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.InMemoryOnly;
        }

        return durabilitySnapshot.HasRecoveredPersistedHistory
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.Recovered
            : CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.Persisted;
    }

    private static string[] CreateManagedConnectorCommandJournalDurabilityCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        ManagedConnectorCommandExecutionJournalDurabilitySnapshot durabilitySnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>();

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        if (durabilitySnapshot.HasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.DurableStoreConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.InMemoryOnly);
        }

        if (durabilitySnapshot.HasPersistedSnapshot)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.PersistedSnapshotAvailable);
        }

        if (durabilitySnapshot.HasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.PersistedRecordedHistory);
        }

        if (durabilitySnapshot.HasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.RecoveredHistory);
        }

        if (durabilitySnapshot.HasRecoveryError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.RecoveryError);
        }

        if (durabilitySnapshot.HasPersistenceError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.PersistenceError);
        }

        if (durabilitySnapshot.HasDurableStoreConfigured &&
            !durabilitySnapshot.HasRecoveryError &&
            !durabilitySnapshot.HasPersistenceError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.PersistenceHealthy);
        }

        if (commandJournal.HasRecordedCommandHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.RecordedCommandHistory);
        }

        if (commandJournal.HasTruncatedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.TruncatedHistory);
        }

        if (automaticRetryExecution.IsEligible)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.AutomaticRetryEligible);
        }

        if (automaticRetryCoordination.CanExecuteOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityCategories.CoordinationReady);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorCommandJournalDurabilityDescription(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        ManagedConnectorCommandExecutionJournalDurabilitySnapshot durabilitySnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            commandJournal.Description,
            automaticRetryCoordination.CanExecuteOnCurrentNode
                ? automaticRetryCoordination.Description
                : automaticRetryExecution.Description);

        return state switch
        {
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.NotApplicable =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon does not currently expose durable managed-connector command-journal posture for this execution runtime.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.InMemoryOnly =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon currently keeps the bounded managed-connector command journal in memory only, so retry evidence would not survive process restart on this host.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.Recovered =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon recovered the bounded managed-connector command journal from the configured durable store after startup, so retained retry evidence now survives host restart.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.RecoveryFailed =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    $"Cephalon could not recover the configured durable managed-connector command journal after startup: {NormalizeManagedConnectorFingerprintSegment(durabilitySnapshot.LastRecoveryError)}.",
                    detail),
            CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.PersistenceFailed =>
                AppendManagedConnectorCommandEnvelopeDetail(
                    $"Cephalon could not persist the latest bounded managed-connector command journal snapshot: {NormalizeManagedConnectorFingerprintSegment(durabilitySnapshot.LastPersistenceError)}.",
                    detail),
            _ => durabilitySnapshot.HasPersistedRecordedHistory
                ? AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon now persists bounded managed-connector command-journal history for this execution runtime, so retained retry evidence survives process restart on the current host.",
                    detail)
                : AppendManagedConnectorCommandEnvelopeDetail(
                    "Cephalon configured a durable managed-connector command-journal store for this execution runtime and is ready to persist retained retry evidence as soon as command history is recorded.",
                    detail)
        };
    }

    private static string ResolveManagedConnectorCommandJournalDurabilitySourceId(
        string state,
        ManagedConnectorCommandExecutionJournalDurabilitySnapshot durabilitySnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilitySources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.InMemoryOnly, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilitySources.InMemoryHistoryStore;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.RecoveryFailed, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilitySources.RecoveryError;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStates.PersistenceFailed, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilitySources.PersistenceError;
        }

        return durabilitySnapshot.HasRecoveredPersistedHistory
            ? CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilitySources.RecoveredDurableJournalStore
            : CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilitySources.DurableJournalStore;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus CreateManagedConnectorDistributedRetryLease(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        IReadOnlyList<CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult> commandExecutionHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(commandExecutionHistory);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var retryFingerprint = automaticRetryExecution.RetryFingerprint;
        var latestAutomaticRetryExecutionFingerprint = automaticRetryExecution.LatestAutomaticRetryExecutionFingerprint;
        var automaticRetryAttempts = commandExecutionHistory
            .Where(static entry => entry.IsAutomaticRetryInvocation)
            .ToArray();
        var matchingAutomaticRetryAttemptCount = automaticRetryAttempts.Count(entry =>
            !string.IsNullOrWhiteSpace(latestAutomaticRetryExecutionFingerprint) &&
            string.Equals(
                entry.ExecutionFingerprint,
                latestAutomaticRetryExecutionFingerprint,
                StringComparison.OrdinalIgnoreCase));
        if (matchingAutomaticRetryAttemptCount == 0 &&
            automaticRetryExecution.HasMatchingAutomaticRetryAttempt)
        {
            matchingAutomaticRetryAttemptCount = 1;
        }

        var hasDuplicateAutomaticRetryAttempts = matchingAutomaticRetryAttemptCount > 1;
        var durableStoreHealthy =
            commandJournalDurability.HasDurableStoreConfigured &&
            !commandJournalDurability.HasRecoveryError &&
            !commandJournalDurability.HasPersistenceError;
        var hasDurableRetryEvidence =
            durableStoreHealthy &&
            (commandJournalDurability.HasPersistedRecordedHistory || commandJournalDurability.HasRecoveredPersistedHistory);
        var hasMatchingRetryFingerprintHistory = commandJournal.HasMatchingRetryFingerprint;
        var hasMatchingAutomaticRetryAttempt =
            automaticRetryExecution.HasMatchingAutomaticRetryAttempt ||
            matchingAutomaticRetryAttemptCount > 0;
        var state =
            !string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            !automaticRetryExecution.AppliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.NotApplicable
                : retryExecutionPolicy.IsOperatorOnly || automaticRetryCoordination.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.OperatorOnly
                    : automaticRetryCoordination.IsSingleNode
                        ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.SingleNode
                        : automaticRetryCoordination.IsLeaseMissing
                            ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseMissing
                            : automaticRetryCoordination.IsConflicted || automaticRetryCoordination.IsUncoordinated
                                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseConflicted
                                : automaticRetryCoordination.IsLeaseHeld
                                    ? !commandJournalDurability.HasDurableStoreConfigured ||
                                      commandJournalDurability.IsInMemoryOnly ||
                                      commandJournalDurability.HasRecoveryError ||
                                      commandJournalDurability.HasPersistenceError ||
                                      hasDuplicateAutomaticRetryAttempts ||
                                      (automaticRetryExecution.HasAutomaticRetryAttempt && !hasMatchingRetryFingerprintHistory)
                                        ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotencyRisk
                                        : hasDurableRetryEvidence ||
                                          hasMatchingRetryFingerprintHistory ||
                                          hasMatchingAutomaticRetryAttempt
                                            ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotentSafe
                                            : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseHeld
                                    : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseConflicted;

        var categories = CreateManagedConnectorDistributedRetryLeaseCategories(
            state,
            automaticRetryCoordination,
            retryExecutionPolicy,
            commandJournal,
            commandJournalDurability,
            hasMatchingAutomaticRetryAttempt,
            hasDuplicateAutomaticRetryAttempts);
        var description = CreateManagedConnectorDistributedRetryLeaseDescription(
            state,
            automaticRetryExecution,
            automaticRetryCoordination,
            retryExecutionPolicy,
            commandJournal,
            commandJournalDurability,
            hasDuplicateAutomaticRetryAttempts);
        var sourceId = ResolveManagedConnectorDistributedRetryLeaseSourceId(
            state,
            commandJournalDurability,
            hasDuplicateAutomaticRetryAttempts,
            hasMatchingRetryFingerprintHistory,
            hasMatchingAutomaticRetryAttempt);

        return new CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            CoordinationOwnerId = automaticRetryCoordination.CoordinationOwnerId,
            ActiveReporterId = automaticRetryCoordination.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = automaticRetryCoordination.ActiveReporterLeaseExpiresAtUtc,
            AutomaticRetryExecutionState = automaticRetryExecution.State,
            AutomaticRetryCoordinationState = automaticRetryCoordination.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            CommandJournalDurabilityState = commandJournalDurability.State,
            SourceId = sourceId,
            RetryFingerprint = retryFingerprint,
            LatestAutomaticRetryAttemptId = automaticRetryExecution.LatestAutomaticRetryAttemptId,
            LatestAutomaticRetryExecutionFingerprint = latestAutomaticRetryExecutionFingerprint,
            RetainedEntryCount = commandJournal.RetainedEntryCount,
            AutomaticRetryAttemptCount = automaticRetryAttempts.Length,
            MatchingAutomaticRetryAttemptCount = matchingAutomaticRetryAttemptCount,
            HasDurableStoreConfigured = commandJournalDurability.HasDurableStoreConfigured,
            HasPersistedRecordedHistory = commandJournalDurability.HasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = commandJournalDurability.HasRecoveredPersistedHistory,
            HasMatchingRetryFingerprintHistory = hasMatchingRetryFingerprintHistory,
            HasMatchingAutomaticRetryAttempt = hasMatchingAutomaticRetryAttempt,
            HasDuplicateAutomaticRetryAttempts = hasDuplicateAutomaticRetryAttempts
        };
    }

    private static string[] CreateManagedConnectorDistributedRetryLeaseCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        bool hasMatchingAutomaticRetryAttempt,
        bool hasDuplicateAutomaticRetryAttempts)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>();

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(
            categories,
            automaticRetryCoordination.IsSingleNode
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.SingleNodeRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.LeaseCoordinatedRuntime);

        AddCategory(
            categories,
            automaticRetryCoordination.HasCoordinationOwner
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.CoordinationOwnerConfigured
                : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.CoordinationOwnerMissing);

        if (automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.OwnerMatch);
        }
        else if (automaticRetryCoordination.HasCoordinationOwner &&
                 automaticRetryCoordination.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.OwnerMismatch);
        }

        if (automaticRetryCoordination.IsLeaseHeld ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotentSafe, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.LeaseHeld);
        }

        if (automaticRetryCoordination.IsLeaseMissing)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.LeaseMissing);
        }

        if (automaticRetryCoordination.IsConflicted ||
            automaticRetryCoordination.IsUncoordinated ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseConflicted, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.LeaseConflict);
        }

        if (retryExecutionPolicy.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.OperatorOnly);
        }

        if (commandJournalDurability.HasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.DurableJournalConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.InMemoryJournalOnly);
        }

        if (commandJournalDurability.IsDurable &&
            !commandJournalDurability.HasRecoveryError &&
            !commandJournalDurability.HasPersistenceError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.DurableJournalHealthy);
        }

        if (commandJournalDurability.HasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.PersistedHistory);
        }

        if (commandJournalDurability.HasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.RecoveredHistory);
        }

        if (commandJournalDurability.HasRecoveryError || commandJournalDurability.HasPersistenceError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.JournalFailure);
        }

        if (commandJournal.HasMatchingRetryFingerprint)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.RetryHistoryPresent);
        }

        if (automaticRetryCoordination.CanExecuteOnCurrentNode &&
            !string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.CurrentNodeExecutable);
        }

        if (commandJournalDurability.HasDurableStoreConfigured &&
            !commandJournalDurability.IsDurable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.DurableJournalConfigured);
        }

        if (hasDuplicateAutomaticRetryAttempts)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.DuplicateAutomaticRetryAttempts);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotentSafe, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.CrossNodeIdempotentSafe);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.CrossNodeIdempotencyRisk);
        }

        if (hasMatchingAutomaticRetryAttempt)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseCategories.MatchingAutomaticRetryAttempt);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorDistributedRetryLeaseDescription(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        bool hasDuplicateAutomaticRetryAttempts)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                automaticRetryCoordination.Description,
                commandJournalDurability.Description,
                commandJournal.Description),
            automaticRetryExecution.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently require distributed retry lease posture for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe cross-node retry posture for this managed connector, but distributed retry execution still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.SingleNode, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can evaluate automatic background retry on the current node without cross-node lease coordination or distributed idempotency evidence.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseMissing, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon cannot safely run automatic background retry on this node because no active retry lease is currently visible for the managed connector.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseConflicted, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon cannot safely run automatic background retry on this node because cross-node retry lease ownership remains conflicted or uncoordinated.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotentSafe, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Reporter '{NormalizeManagedConnectorFingerprintSegment(automaticRetryCoordination.ActiveReporterId)}' currently holds the active retry lease, and durable retained command history now provides restart-safe cross-node idempotency evidence for automatic retry on this node.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.IdempotencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            var riskReason =
                !commandJournalDurability.HasDurableStoreConfigured || commandJournalDurability.IsInMemoryOnly
                    ? "The runtime still depends on in-memory command history only."
                    : commandJournalDurability.HasRecoveryError || commandJournalDurability.HasPersistenceError
                        ? "The durable command-journal store currently reports a recovery or persistence failure."
                        : hasDuplicateAutomaticRetryAttempts
                            ? "The bounded command journal already retains multiple automatic retry attempts for the same retry posture."
                            : automaticRetryExecution.HasAutomaticRetryAttempt && !commandJournal.HasMatchingRetryFingerprint
                                ? "The bounded command journal does not currently retain matching retry history for the latest automatic retry attempt."
                                : "Cross-node retry evidence remains incomplete for the current retry posture.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Reporter '{NormalizeManagedConnectorFingerprintSegment(automaticRetryCoordination.ActiveReporterId)}' currently holds the active retry lease, but Cephalon still blocks automatic background retry on this node because cross-node idempotency evidence remains risky. {riskReason}",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Reporter '{NormalizeManagedConnectorFingerprintSegment(automaticRetryCoordination.ActiveReporterId)}' currently holds the active retry lease for this managed connector, but Cephalon has not yet promoted the retained history posture to cross-node idempotent-safe.",
            detail);
    }

    private static string ResolveManagedConnectorDistributedRetryLeaseSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        bool hasDuplicateAutomaticRetryAttempts,
        bool hasMatchingRetryFingerprintHistory,
        bool hasMatchingAutomaticRetryAttempt)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseSources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseSources.RetryExecutionPolicy;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.SingleNode, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseHeld, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseMissing, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStates.LeaseConflicted, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseSources.AutomaticRetryCoordination;
        }

        if (commandJournalDurability.IsInMemoryOnly ||
            commandJournalDurability.HasRecoveryError ||
            commandJournalDurability.HasPersistenceError ||
            commandJournalDurability.HasPersistedRecordedHistory ||
            commandJournalDurability.HasRecoveredPersistedHistory)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseSources.CommandJournalDurability;
        }

        if (hasDuplicateAutomaticRetryAttempts ||
            hasMatchingRetryFingerprintHistory ||
            hasMatchingAutomaticRetryAttempt)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseSources.CommandExecutionHistory;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseSources.AutomaticRetryCoordination;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus CreateManagedConnectorCrossNodeIdempotencyHardening(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        IReadOnlyList<CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult> commandExecutionHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(commandExecutionHistory);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var operationId = string.IsNullOrWhiteSpace(automaticRetryExecution.OperationId)
            ? string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
                : retryExecutionPolicy.OperationId.Trim()
            : automaticRetryExecution.OperationId.Trim();
        var normalizedCommandFingerprint = string.IsNullOrWhiteSpace(automaticRetryExecution.CommandFingerprint)
            ? commandJournal.CommandFingerprint
            : automaticRetryExecution.CommandFingerprint;
        var normalizedRetryFingerprint = string.IsNullOrWhiteSpace(automaticRetryExecution.RetryFingerprint)
            ? commandJournal.RetryFingerprint
            : automaticRetryExecution.RetryFingerprint;
        var automaticRetryAttempts = commandExecutionHistory
            .Where(static entry => entry.IsAutomaticRetryInvocation)
            .ToArray();
        var matchingCommandLineageEntryCount = string.IsNullOrWhiteSpace(normalizedCommandFingerprint)
            ? 0
            : commandExecutionHistory.Count(entry => string.Equals(
                entry.CommandFingerprint,
                normalizedCommandFingerprint,
                StringComparison.OrdinalIgnoreCase));
        var matchingAutomaticRetryAttemptCount = string.IsNullOrWhiteSpace(normalizedCommandFingerprint)
            ? automaticRetryAttempts.Length
            : automaticRetryAttempts.Count(entry => string.Equals(
                entry.CommandFingerprint,
                normalizedCommandFingerprint,
                StringComparison.OrdinalIgnoreCase));
        var hasMatchingRetryFingerprintHistory = commandJournal.HasMatchingRetryFingerprint || distributedRetryLease.HasMatchingRetryFingerprintHistory;
        var hasMatchingAutomaticRetryAttempt = automaticRetryExecution.HasMatchingAutomaticRetryAttempt ||
                                              distributedRetryLease.HasMatchingAutomaticRetryAttempt ||
                                              matchingAutomaticRetryAttemptCount > 0;
        var hasDuplicateAutomaticRetryAttempts = distributedRetryLease.HasDuplicateAutomaticRetryAttempts ||
                                                matchingAutomaticRetryAttemptCount > 1;
        var hasDuplicateCommandLineage = !string.IsNullOrWhiteSpace(normalizedCommandFingerprint) &&
                                         commandExecutionHistory
                                             .Where(entry => string.Equals(
                                                 entry.CommandFingerprint,
                                                 normalizedCommandFingerprint,
                                                 StringComparison.OrdinalIgnoreCase))
                                             .GroupBy(static entry => entry.InvocationSourceId, StringComparer.OrdinalIgnoreCase)
                                             .Any(static group => group.Count() > 1);
        var hasCrossNodeRuntime = string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
                                  automaticRetryExecution.AppliesToManagedConnector &&
                                  !automaticRetryCoordination.IsSingleNode &&
                                  !distributedRetryLease.IsSingleNode;
        var ownerMismatch = automaticRetryCoordination.HasCoordinationOwner &&
                            automaticRetryCoordination.HasActiveReporterLease &&
                            !automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter;
        var staleOwnerRisk = hasCrossNodeRuntime &&
                             (distributedRetryLease.IsLeaseMissing ||
                              distributedRetryLease.IsLeaseConflicted ||
                              automaticRetryCoordination.IsConflicted ||
                              automaticRetryCoordination.IsUncoordinated ||
                              ownerMismatch);
        var duplicateLineageRisk = hasCrossNodeRuntime &&
                                   (hasDuplicateCommandLineage || hasDuplicateAutomaticRetryAttempts);
        var replayWindowRisk = hasCrossNodeRuntime &&
                               !staleOwnerRisk &&
                               !duplicateLineageRisk &&
                               (!commandJournalDurability.HasDurableStoreConfigured ||
                                !commandJournalDurability.IsDurable ||
                                commandJournalDurability.HasRecoveryError ||
                                commandJournalDurability.HasPersistenceError ||
                                commandJournal.HasTruncatedHistory ||
                                !hasMatchingRetryFingerprintHistory ||
                                (automaticRetryExecution.HasAutomaticRetryAttempt && !hasMatchingAutomaticRetryAttempt) ||
                                distributedRetryLease.IsIdempotencyRisk);

        var state =
            !hasCrossNodeRuntime
                ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.NotApplicable
                : retryExecutionPolicy.IsOperatorOnly || distributedRetryLease.IsOperatorOnly || automaticRetryCoordination.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.OperatorOnly
                    : staleOwnerRisk
                        ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.StaleOwnerRisk
                        : duplicateLineageRisk
                            ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.DuplicateLineageRisk
                            : replayWindowRisk
                                ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.ReplayWindowRisk
                                : CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.IdempotentSafe;

        var categories = CreateManagedConnectorCrossNodeIdempotencyHardeningCategories(
            state,
            automaticRetryCoordination,
            commandJournal,
            commandJournalDurability,
            distributedRetryLease,
            hasCrossNodeRuntime,
            ownerMismatch,
            hasDuplicateCommandLineage,
            hasMatchingRetryFingerprintHistory,
            hasMatchingAutomaticRetryAttempt,
            hasDuplicateAutomaticRetryAttempts);
        var description = CreateManagedConnectorCrossNodeIdempotencyHardeningDescription(
            state,
            operationId,
            automaticRetryExecution,
            automaticRetryCoordination,
            retryExecutionPolicy,
            commandJournal,
            commandJournalDurability,
            distributedRetryLease,
            ownerMismatch,
            hasDuplicateCommandLineage,
            hasMatchingRetryFingerprintHistory,
            hasMatchingAutomaticRetryAttempt,
            hasDuplicateAutomaticRetryAttempts);
        var sourceId = ResolveManagedConnectorCrossNodeIdempotencyHardeningSourceId(
            state,
            automaticRetryCoordination,
            retryExecutionPolicy,
            commandJournal,
            commandJournalDurability,
            distributedRetryLease,
            ownerMismatch,
            hasDuplicateCommandLineage,
            hasMatchingRetryFingerprintHistory,
            hasMatchingAutomaticRetryAttempt,
            hasDuplicateAutomaticRetryAttempts);

        return new CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = operationId,
            CoordinationOwnerId = automaticRetryCoordination.CoordinationOwnerId,
            ActiveReporterId = automaticRetryCoordination.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = automaticRetryCoordination.ActiveReporterLeaseExpiresAtUtc,
            AutomaticRetryExecutionState = automaticRetryExecution.State,
            AutomaticRetryCoordinationState = automaticRetryCoordination.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            CommandJournalDurabilityState = commandJournalDurability.State,
            DistributedRetryLeaseState = distributedRetryLease.State,
            LatestCommandExecutionState = automaticRetryExecution.LatestCommandExecutionState,
            SourceId = sourceId,
            CommandFingerprint = normalizedCommandFingerprint ?? string.Empty,
            RetryFingerprint = normalizedRetryFingerprint ?? string.Empty,
            LatestAutomaticRetryAttemptId = automaticRetryExecution.LatestAutomaticRetryAttemptId,
            LatestAutomaticRetryExecutionFingerprint = automaticRetryExecution.LatestAutomaticRetryExecutionFingerprint,
            TotalRecordedEntryCount = commandJournal.TotalRecordedEntryCount,
            RetainedEntryCount = commandJournal.RetainedEntryCount,
            MatchingCommandLineageEntryCount = matchingCommandLineageEntryCount,
            AutomaticRetryAttemptCount = automaticRetryAttempts.Length,
            MatchingAutomaticRetryAttemptCount = matchingAutomaticRetryAttemptCount,
            HasDurableStoreConfigured = commandJournalDurability.HasDurableStoreConfigured,
            HasPersistedRecordedHistory = commandJournalDurability.HasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = commandJournalDurability.HasRecoveredPersistedHistory,
            HasMatchingRetryFingerprintHistory = hasMatchingRetryFingerprintHistory,
            HasMatchingAutomaticRetryAttempt = hasMatchingAutomaticRetryAttempt,
            HasDuplicateCommandLineage = hasDuplicateCommandLineage,
            HasDuplicateAutomaticRetryAttempts = hasDuplicateAutomaticRetryAttempts,
            CoordinationOwnerMatchesActiveReporter = automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter
        };
    }

    private static string[] CreateManagedConnectorCrossNodeIdempotencyHardeningCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        bool hasCrossNodeRuntime,
        bool ownerMismatch,
        bool hasDuplicateCommandLineage,
        bool hasMatchingRetryFingerprintHistory,
        bool hasMatchingAutomaticRetryAttempt,
        bool hasDuplicateAutomaticRetryAttempts)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);

        var categories = new List<string>(capacity: 18);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(
            categories,
            hasCrossNodeRuntime
                ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.CrossNodeRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.SingleNodeRuntime);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.OperatorOnly);
        }

        if (!string.IsNullOrWhiteSpace(automaticRetryCoordination.ActiveReporterId))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.ActiveReporterVisible);
        }

        if (automaticRetryCoordination.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.ActiveLeaseVisible);
        }

        if (automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.OwnerMatch);
        }
        else if (ownerMismatch)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.OwnerMismatch);
        }

        if (distributedRetryLease.IsLeaseMissing)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.LeaseMissing);
        }

        if (distributedRetryLease.IsLeaseConflicted || automaticRetryCoordination.IsConflicted || automaticRetryCoordination.IsUncoordinated)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.LeaseConflict);
        }

        if (commandJournalDurability.HasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.DurableJournalConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.InMemoryJournalOnly);
        }

        if (commandJournalDurability.HasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.PersistedHistory);
        }

        if (commandJournalDurability.HasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.RecoveredHistory);
        }

        if (hasMatchingRetryFingerprintHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.MatchingRetryHistory);
        }

        if (hasMatchingAutomaticRetryAttempt)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.MatchingAutomaticRetryAttempt);
        }

        if (hasDuplicateCommandLineage)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.DuplicateCommandLineage);
        }

        if (hasDuplicateAutomaticRetryAttempts)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.DuplicateAutomaticRetryAttempts);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.IdempotentSafe, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.IdempotentSafe);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.CurrentNodeExecutable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.StaleOwnerRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.StaleOwnerRisk);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.DuplicateLineageRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.DuplicateLineageRisk);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.ReplayWindowRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningCategories.ReplayWindowRisk);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorCrossNodeIdempotencyHardeningDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        bool ownerMismatch,
        bool hasDuplicateCommandLineage,
        bool hasMatchingRetryFingerprintHistory,
        bool hasMatchingAutomaticRetryAttempt,
        bool hasDuplicateAutomaticRetryAttempts)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                automaticRetryCoordination.Description,
                distributedRetryLease.Description,
                commandJournalDurability.Description),
            CombineManagedConnectorCommandEnvelopeDetail(
                commandJournal.Description,
                automaticRetryExecution.Description,
                retryExecutionPolicy.Description));

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            var summary = automaticRetryCoordination.IsSingleNode || distributedRetryLease.IsSingleNode
                ? "Cephalon does not currently require cross-node idempotency hardening for this execution runtime because retry coordination remains single-node."
                : "Cephalon does not currently require cross-node idempotency hardening for this execution runtime.";

            return AppendManagedConnectorCommandEnvelopeDetail(summary, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can observe cross-node idempotency posture for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but this hardening lane still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.IdempotentSafe, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Reporter '{NormalizeManagedConnectorFingerprintSegment(automaticRetryCoordination.ActiveReporterId)}' currently aligns with the active coordination owner, and durable retained command history now provides cross-node idempotency evidence for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.StaleOwnerRisk, StringComparison.OrdinalIgnoreCase))
        {
            var staleReason =
                distributedRetryLease.IsLeaseMissing
                    ? "No active retry lease is currently visible for the managed connector."
                    : ownerMismatch
                        ? "The configured coordination owner does not match the active reporter lease."
                        : "Reporter ownership or retry lease coordination still remains conflicted on the current node.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon still blocks cross-node automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because ownership truth looks stale. {staleReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.DuplicateLineageRisk, StringComparison.OrdinalIgnoreCase))
        {
            var duplicateReason = hasDuplicateAutomaticRetryAttempts
                ? "Retained history already contains multiple automatic retry attempts for the same retry posture."
                : hasDuplicateCommandLineage
                    ? "Retained history already contains duplicated command lineage for the same retry posture."
                    : "Retained command lineage already looks duplicated for the current retry posture.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon still blocks cross-node automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because retained command lineage could replay duplicate work. {duplicateReason}",
                detail);
        }

        var replayReason =
            !commandJournalDurability.HasDurableStoreConfigured || commandJournalDurability.IsInMemoryOnly
                ? "The runtime still depends on in-memory command history only."
                : commandJournalDurability.HasRecoveryError || commandJournalDurability.HasPersistenceError
                    ? "The durable command-journal store currently reports a recovery or persistence failure."
                    : commandJournal.HasTruncatedHistory
                        ? "The bounded command journal has already truncated older retained command lineage."
                        : !hasMatchingRetryFingerprintHistory
                            ? "Retained history does not currently expose matching retry-fingerprint evidence."
                            : automaticRetryExecution.HasAutomaticRetryAttempt && !hasMatchingAutomaticRetryAttempt
                                ? "Retained history does not currently expose a matching automatic retry attempt."
                                : "Cross-node replay evidence remains incomplete for the current retry posture.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon still blocks cross-node automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the durable replay window lacks enough retained evidence. {replayReason}",
            detail);
    }

    private static string ResolveManagedConnectorCrossNodeIdempotencyHardeningSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        bool ownerMismatch,
        bool hasDuplicateCommandLineage,
        bool hasMatchingRetryFingerprintHistory,
        bool hasMatchingAutomaticRetryAttempt,
        bool hasDuplicateAutomaticRetryAttempts)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.RetryExecutionPolicy;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.StaleOwnerRisk, StringComparison.OrdinalIgnoreCase))
        {
            return ownerMismatch || automaticRetryCoordination.IsConflicted || automaticRetryCoordination.IsUncoordinated
                ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.AutomaticRetryCoordination
                : CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.DistributedRetryLease;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.DuplicateLineageRisk, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.CommandExecutionHistory;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStates.ReplayWindowRisk, StringComparison.OrdinalIgnoreCase))
        {
            if (!commandJournalDurability.HasDurableStoreConfigured ||
                commandJournalDurability.IsInMemoryOnly ||
                commandJournalDurability.HasRecoveryError ||
                commandJournalDurability.HasPersistenceError ||
                commandJournal.HasTruncatedHistory)
            {
                return CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.CommandJournalDurability;
            }

            if (!hasMatchingRetryFingerprintHistory ||
                !hasMatchingAutomaticRetryAttempt ||
                hasDuplicateAutomaticRetryAttempts ||
                hasDuplicateCommandLineage)
            {
                return CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.CommandExecutionHistory;
            }

            return CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.DistributedRetryLease;
        }

        return distributedRetryLease.IsIdempotentSafe
            ? CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.DistributedRetryLease
            : CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningSources.CommandJournalDurability;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus CreateManagedConnectorDistributedRetryOrchestration(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening,
        int pollingIntervalSeconds)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedPollingIntervalSeconds = Math.Max(1, pollingIntervalSeconds);
        var operationId = string.IsNullOrWhiteSpace(automaticRetryExecution.OperationId)
            ? string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
                : retryExecutionPolicy.OperationId.Trim()
            : automaticRetryExecution.OperationId.Trim();
        var state =
            !string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) ||
            !automaticRetryExecution.AppliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.NotApplicable
                : retryExecutionPolicy.IsOperatorOnly || distributedRetryLease.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.OperatorOnly
                    : !automaticRetryExecution.IsAutomaticRetryEnabled ||
                      retryExecutionPolicy.IsBackgroundRetryDisabled ||
                      automaticRetryExecution.IsDisabled
                        ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Disabled
                        : retryExecutionPolicy.IsCooldown
                            ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Cooldown
                            : automaticRetryExecution.IsCompleted || retryExecutionPolicy.IsNotNeeded
                                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Completed
                                : automaticRetryExecution.IsEligible &&
                                  crossNodeIdempotencyHardening.CanExecuteAutomaticRetryOnCurrentNode
                                    ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Scheduled
                                    : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Blocked;

        var categories = CreateManagedConnectorDistributedRetryOrchestrationCategories(
            state,
            automaticRetryExecution,
            automaticRetryCoordination,
            retryExecutionPolicy,
            commandJournalDurability,
            distributedRetryLease,
            crossNodeIdempotencyHardening);
        var description = CreateManagedConnectorDistributedRetryOrchestrationDescription(
            state,
            operationId,
            automaticRetryExecution,
            automaticRetryCoordination,
            retryExecutionPolicy,
            commandJournalDurability,
            distributedRetryLease,
            crossNodeIdempotencyHardening);
        var sourceId = ResolveManagedConnectorDistributedRetryOrchestrationSourceId(
            state,
            automaticRetryExecution,
            retryExecutionPolicy,
            commandJournalDurability,
            distributedRetryLease,
            crossNodeIdempotencyHardening);

        return new CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            CoordinationOwnerId = distributedRetryLease.CoordinationOwnerId,
            ActiveReporterId = distributedRetryLease.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = distributedRetryLease.ActiveReporterLeaseExpiresAtUtc,
            AutomaticRetryExecutionState = automaticRetryExecution.State,
            AutomaticRetryCoordinationState = automaticRetryCoordination.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalDurabilityState = commandJournalDurability.State,
            DistributedRetryLeaseState = distributedRetryLease.State,
            SourceId = sourceId,
            SchedulerId = CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus.DefaultSchedulerId,
            SchedulerKind = CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus.DefaultSchedulerKind,
            PollingIntervalSeconds = normalizedPollingIntervalSeconds,
            OperationId = operationId,
            RetryFingerprint = automaticRetryExecution.RetryFingerprint,
            CooldownUntilUtc = retryExecutionPolicy.CooldownUntilUtc,
            LatestAutomaticRetryAttemptId = automaticRetryExecution.LatestAutomaticRetryAttemptId,
            LatestAutomaticRetryRecordedAtUtc = automaticRetryExecution.LatestAutomaticRetryRecordedAtUtc,
            HasDurableStoreConfigured = commandJournalDurability.HasDurableStoreConfigured,
            HasPersistedRecordedHistory = commandJournalDurability.HasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = commandJournalDurability.HasRecoveredPersistedHistory,
            CanScheduleAutomaticRetryOnCurrentNode = string.Equals(
                state,
                CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Scheduled,
                StringComparison.OrdinalIgnoreCase)
        };
    }

    private static string[] CreateManagedConnectorDistributedRetryOrchestrationCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>();

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.BoundedSharedScheduler);
        AddCategory(
            categories,
            automaticRetryExecution.IsAutomaticRetryEnabled && !retryExecutionPolicy.IsBackgroundRetryDisabled
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.SchedulerEnabled
                : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.SchedulerDisabled);
        AddCategory(
            categories,
            distributedRetryLease.IsSingleNode
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.SingleNodeRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.LeaseCoordinatedRuntime);

        if (automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.OwnerMatch);
        }
        else if (automaticRetryCoordination.HasCoordinationOwner &&
                 automaticRetryCoordination.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.OwnerMismatch);
        }

        if (commandJournalDurability.HasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.DurableJournalConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.InMemoryJournalOnly);
        }

        if (commandJournalDurability.IsDurable &&
            !commandJournalDurability.HasRecoveryError &&
            !commandJournalDurability.HasPersistenceError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.DurableJournalHealthy);
        }

        if (commandJournalDurability.HasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.PersistedHistory);
        }

        if (commandJournalDurability.HasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.RecoveredHistory);
        }

        if (crossNodeIdempotencyHardening.IsIdempotentSafe)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.CrossNodeIdempotentSafe);
        }

        if (crossNodeIdempotencyHardening.IsStaleOwnerRisk ||
            crossNodeIdempotencyHardening.IsDuplicateLineageRisk ||
            crossNodeIdempotencyHardening.IsReplayWindowRisk ||
            distributedRetryLease.IsIdempotencyRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.CrossNodeIdempotencyRisk);
        }

        if (automaticRetryExecution.HasAutomaticRetryAttempt)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.AutomaticRetryAttemptRecorded);
        }

        if (retryExecutionPolicy.IsCooldown ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Cooldown, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.CooldownWindow);
        }

        if (retryExecutionPolicy.IsNotNeeded ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Completed, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.NoFurtherRetryNeeded);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Scheduled, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.CurrentNodeSchedulable);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationCategories.OperatorOnly);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorDistributedRetryOrchestrationDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                crossNodeIdempotencyHardening.Description,
                distributedRetryLease.Description,
                retryExecutionPolicy.Description),
            automaticRetryExecution.Description,
            commandJournalDurability.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose distributed retry orchestration for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe distributed retry scheduling posture for this managed connector, but orchestration still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Disabled, StringComparison.OrdinalIgnoreCase))
        {
            var disabledReason = !automaticRetryExecution.IsAutomaticRetryEnabled
                ? "The shared automatic retry loop is disabled by the current data runtime options."
                : "The current retry-execution policy keeps background retry disabled even though shared retry truth is available.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon identified a managed-connector retry scheduling candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but distributed retry orchestration is disabled right now. {disabledReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Cooldown, StringComparison.OrdinalIgnoreCase))
        {
            var cooldownMessage = retryExecutionPolicy.CooldownUntilUtc.HasValue
                ? $"Cephalon is holding distributed retry orchestration for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} until the cooldown window ends at '{retryExecutionPolicy.CooldownUntilUtc.Value:O}'."
                : $"Cephalon is holding distributed retry orchestration for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} while the current cooldown window remains active.";

            return AppendManagedConnectorCommandEnvelopeDetail(cooldownMessage, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Completed, StringComparison.OrdinalIgnoreCase))
        {
            var completionReason = retryExecutionPolicy.IsNotNeeded
                ? $"Cephalon does not currently need to schedule another automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the shared runtime truth already converged."
                : $"Cephalon already recorded one bounded automatic retry attempt for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared command lane and will not schedule another until runtime truth changes.";

            return AppendManagedConnectorCommandEnvelopeDetail(completionReason, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Scheduled, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Reporter '{NormalizeManagedConnectorFingerprintSegment(automaticRetryCoordination.ActiveReporterId)}' currently holds the active retry lease, and Cephalon can schedule one bounded automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node through the shared automatic retry loop.",
                detail);
        }

        var blockedReason =
            crossNodeIdempotencyHardening.IsStaleOwnerRisk
                ? "Ownership or retry lease truth still looks stale on the current node."
                : crossNodeIdempotencyHardening.IsDuplicateLineageRisk
                    ? "Retained command lineage already looks duplicated for the current retry posture."
                    : crossNodeIdempotencyHardening.IsReplayWindowRisk || distributedRetryLease.IsIdempotencyRisk
                        ? "Cross-node replay evidence remains risky for the current retry fingerprint."
                        : "Shared runtime truth still blocks the next bounded retry scheduling step.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon cannot schedule the next bounded automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node. {blockedReason}",
            detail);
    }

    private static string ResolveManagedConnectorDistributedRetryOrchestrationSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Disabled, StringComparison.OrdinalIgnoreCase))
        {
            return automaticRetryExecution.IsDisabled
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.AutomaticRetryExecution
                : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.RetryExecutionPolicy;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Cooldown, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.RetryExecutionPolicy;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStates.Completed, StringComparison.OrdinalIgnoreCase))
        {
            return automaticRetryExecution.IsCompleted
                ? CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.AutomaticRetryExecution
                : CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.RetryExecutionPolicy;
        }

        if (crossNodeIdempotencyHardening.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.CrossNodeIdempotencyHardening;
        }

        if (distributedRetryLease.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.DistributedRetryLease;
        }

        if (commandJournalDurability.HasDurableStoreConfigured ||
            commandJournalDurability.HasPersistedRecordedHistory ||
            commandJournalDurability.HasRecoveredPersistedHistory)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.CommandJournalDurability;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationSources.AutomaticRetryExecution;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus CreateManagedConnectorMultiNodeLeaseExecution(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (automaticRetryCoordination.AppliesToManagedConnector ||
             distributedRetryLease.AppliesToManagedConnector ||
             crossNodeIdempotencyHardening.AppliesToManagedConnector ||
             distributedRetryOrchestration.AppliesToManagedConnector);
        var isSingleNodeRuntime = automaticRetryCoordination.IsSingleNode || distributedRetryLease.IsSingleNode;
        var canExecuteAutomaticRetryOnCurrentNode = false;
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.NotApplicable
                : distributedRetryOrchestration.IsOperatorOnly ||
                  distributedRetryLease.IsOperatorOnly ||
                  automaticRetryCoordination.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.OperatorOnly
                    : isSingleNodeRuntime
                        ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.SingleNode
                        : crossNodeIdempotencyHardening.IsStaleOwnerRisk
                            ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.StaleLeaseRisk
                            : distributedRetryLease.IsLeaseConflicted ||
                              automaticRetryCoordination.IsConflicted ||
                              automaticRetryCoordination.IsUncoordinated
                                ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseConflicted
                                : distributedRetryOrchestration.IsScheduled &&
                                  distributedRetryLease.CanExecuteAutomaticRetryOnCurrentNode &&
                                  crossNodeIdempotencyHardening.CanExecuteAutomaticRetryOnCurrentNode
                                    ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseExecutable
                                    : CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseBlocked;

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseExecutable, StringComparison.OrdinalIgnoreCase))
        {
            canExecuteAutomaticRetryOnCurrentNode = true;
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.SingleNode, StringComparison.OrdinalIgnoreCase) &&
                 distributedRetryOrchestration.CanScheduleAutomaticRetryOnCurrentNode)
        {
            canExecuteAutomaticRetryOnCurrentNode = true;
        }

        var categories = CreateManagedConnectorMultiNodeLeaseExecutionCategories(
            state,
            automaticRetryCoordination,
            distributedRetryLease,
            crossNodeIdempotencyHardening,
            distributedRetryOrchestration,
            isSingleNodeRuntime,
            canExecuteAutomaticRetryOnCurrentNode);
        var description = CreateManagedConnectorMultiNodeLeaseExecutionDescription(
            state,
            automaticRetryCoordination,
            distributedRetryLease,
            crossNodeIdempotencyHardening,
            distributedRetryOrchestration,
            canExecuteAutomaticRetryOnCurrentNode);
        var sourceId = ResolveManagedConnectorMultiNodeLeaseExecutionSourceId(
            state,
            automaticRetryCoordination,
            distributedRetryLease,
            crossNodeIdempotencyHardening,
            distributedRetryOrchestration);

        return new CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = distributedRetryOrchestration.OperationId,
            CoordinationOwnerId = distributedRetryLease.CoordinationOwnerId,
            ActiveReporterId = distributedRetryLease.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = distributedRetryLease.ActiveReporterLeaseExpiresAtUtc,
            AutomaticRetryCoordinationState = automaticRetryCoordination.State,
            DistributedRetryLeaseState = distributedRetryLease.State,
            CrossNodeIdempotencyHardeningState = crossNodeIdempotencyHardening.State,
            DistributedRetryOrchestrationState = distributedRetryOrchestration.State,
            SourceId = sourceId,
            SchedulerId = distributedRetryOrchestration.SchedulerId,
            SchedulerKind = distributedRetryOrchestration.SchedulerKind,
            PollingIntervalSeconds = distributedRetryOrchestration.PollingIntervalSeconds,
            RetryFingerprint = distributedRetryOrchestration.RetryFingerprint,
            CooldownUntilUtc = distributedRetryOrchestration.CooldownUntilUtc,
            LatestAutomaticRetryAttemptId = distributedRetryOrchestration.LatestAutomaticRetryAttemptId,
            LatestAutomaticRetryRecordedAtUtc = distributedRetryOrchestration.LatestAutomaticRetryRecordedAtUtc,
            CoordinationOwnerMatchesActiveReporter = automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter,
            CanExecuteAutomaticRetryOnCurrentNode = canExecuteAutomaticRetryOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorMultiNodeLeaseExecutionCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        bool isSingleNodeRuntime,
        bool canExecuteAutomaticRetryOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 16);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(
            categories,
            isSingleNodeRuntime
                ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.SingleNodeRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.LeaseCoordinatedRuntime);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.OperatorOnly);
        }

        if (!string.IsNullOrWhiteSpace(automaticRetryCoordination.ActiveReporterId))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.ActiveReporterVisible);
        }

        if (automaticRetryCoordination.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.ActiveLeaseVisible);
        }

        if (automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.OwnerMatch);
        }
        else if (automaticRetryCoordination.HasCoordinationOwner &&
                 automaticRetryCoordination.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.OwnerMismatch);
        }

        if (distributedRetryLease.IsLeaseHeld ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseExecutable, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.LeaseHeld);
        }

        if (distributedRetryLease.IsLeaseMissing)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.LeaseMissing);
        }

        if (distributedRetryLease.IsLeaseConflicted ||
            automaticRetryCoordination.IsConflicted ||
            automaticRetryCoordination.IsUncoordinated)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.LeaseConflict);
        }

        if (crossNodeIdempotencyHardening.IsIdempotentSafe)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.CrossNodeIdempotentSafe);
        }

        if (crossNodeIdempotencyHardening.IsStaleOwnerRisk ||
            crossNodeIdempotencyHardening.IsDuplicateLineageRisk ||
            crossNodeIdempotencyHardening.IsReplayWindowRisk ||
            distributedRetryLease.IsIdempotencyRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.CrossNodeIdempotencyRisk);
        }

        if (distributedRetryOrchestration.IsDisabled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.SchedulerDisabled);
        }

        if (distributedRetryOrchestration.IsCooldown)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.CooldownWindow);
        }

        if (distributedRetryOrchestration.IsCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.NoFurtherRetryNeeded);
        }

        AddCategory(
            categories,
            canExecuteAutomaticRetryOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.CurrentNodeExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.CurrentNodeBlocked);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseExecutable, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.LeaseExecutable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.LeaseBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.StaleLeaseRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionCategories.StaleLeaseRisk);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorMultiNodeLeaseExecutionDescription(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        bool canExecuteAutomaticRetryOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);

        var operationId = string.IsNullOrWhiteSpace(distributedRetryOrchestration.OperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
            : distributedRetryOrchestration.OperationId.Trim();
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                distributedRetryOrchestration.Description,
                crossNodeIdempotencyHardening.Description,
                distributedRetryLease.Description),
            automaticRetryCoordination.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose broader multi-node lease execution for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe broader multi-node lease-execution posture for this managed connector, but execution still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.SingleNode, StringComparison.OrdinalIgnoreCase))
        {
            var singleNodeMessage = canExecuteAutomaticRetryOnCurrentNode
                ? $"Cephalon does not currently need cross-node lease ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because this runtime is operating as a single-node automatic retry lane and the current node can execute the next bounded retry step."
                : $"Cephalon does not currently need cross-node lease ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because this runtime is operating as a single-node automatic retry lane, but the current node is not yet ready to execute the next bounded retry step.";

            return AppendManagedConnectorCommandEnvelopeDetail(singleNodeMessage, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.StaleLeaseRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot execute {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node because the broader multi-node lease posture still looks stale.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseConflicted, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot execute {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node because the broader multi-node lease posture remains conflicted or uncoordinated.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseExecutable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can execute {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node because the active lease, cross-node idempotency hardening, and bounded orchestration answers currently align.",
                detail);
        }

        var blockedReason =
            distributedRetryLease.IsLeaseMissing
                ? "No active lease currently backs the retry posture."
                : distributedRetryOrchestration.IsDisabled
                    ? "The shared bounded retry scheduler is disabled for this runtime."
                    : distributedRetryOrchestration.IsCooldown
                        ? "The current cooldown window is still active."
                        : distributedRetryOrchestration.IsCompleted
                            ? "The shared runtime truth does not currently need another retry attempt."
                            : crossNodeIdempotencyHardening.IsDuplicateLineageRisk
                                ? "Retained command lineage already looks duplicated for the current retry posture."
                                : crossNodeIdempotencyHardening.IsReplayWindowRisk || distributedRetryLease.IsIdempotencyRisk
                                    ? "Cross-node replay evidence remains risky for the current retry fingerprint."
                                    : "Shared broader lease-execution truth still blocks the current node.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon cannot execute {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on this node under the current broader multi-node lease posture. {blockedReason}",
            detail);
    }

    private static string ResolveManagedConnectorMultiNodeLeaseExecutionSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorCrossNodeIdempotencyHardeningStatus crossNodeIdempotencyHardening,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(crossNodeIdempotencyHardening);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.SingleNode, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.AutomaticRetryCoordination;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.StaleLeaseRisk, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.CrossNodeIdempotencyHardening;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseConflicted, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.DistributedRetryLease;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStates.LeaseExecutable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.DistributedRetryOrchestration;
        }

        if (crossNodeIdempotencyHardening.IsDuplicateLineageRisk ||
            crossNodeIdempotencyHardening.IsReplayWindowRisk)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.CrossNodeIdempotencyHardening;
        }

        if (distributedRetryLease.IsLeaseMissing ||
            distributedRetryLease.IsIdempotencyRisk)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.DistributedRetryLease;
        }

        return distributedRetryOrchestration.AppliesToManagedConnector
            ? CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.DistributedRetryOrchestration
            : CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionSources.AutomaticRetryCoordination;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus CreateManagedConnectorDurableSharedSchedulerOrchestration(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId = string.IsNullOrWhiteSpace(multiNodeLeaseExecution.OperationId)
            ? string.IsNullOrWhiteSpace(distributedRetryOrchestration.OperationId)
                ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
                : distributedRetryOrchestration.OperationId.Trim()
            : multiNodeLeaseExecution.OperationId.Trim();
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (automaticRetryCoordination.AppliesToManagedConnector ||
             commandJournalDurability.AppliesToManagedConnector ||
             distributedRetryOrchestration.AppliesToManagedConnector ||
             multiNodeLeaseExecution.AppliesToManagedConnector);
        var isSingleNodeRuntime = automaticRetryCoordination.IsSingleNode || multiNodeLeaseExecution.IsSingleNode;
        var ownerMismatch = automaticRetryCoordination.HasCoordinationOwner &&
                            automaticRetryCoordination.HasActiveReporterLease &&
                            !automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter;
        var recoveryNeeded =
            !isSingleNodeRuntime &&
            (commandJournalDurability.IsInMemoryOnly ||
             commandJournalDurability.IsRecoveryFailed ||
             commandJournalDurability.IsPersistenceFailed ||
             !commandJournalDurability.HasDurableStoreConfigured);
        var schedulerConflicted =
            !isSingleNodeRuntime &&
            (automaticRetryCoordination.IsConflicted ||
             automaticRetryCoordination.IsUncoordinated ||
             ownerMismatch ||
             multiNodeLeaseExecution.IsLeaseConflicted ||
             multiNodeLeaseExecution.IsStaleLeaseRisk);
        var canScheduleAutomaticRetryOnCurrentNode =
            distributedRetryOrchestration.CanScheduleAutomaticRetryOnCurrentNode &&
            multiNodeLeaseExecution.CanExecuteAutomaticRetryOnCurrentNode &&
            commandJournalDurability.IsDurable;
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.NotApplicable
                : multiNodeLeaseExecution.IsOperatorOnly ||
                  distributedRetryOrchestration.IsOperatorOnly ||
                  automaticRetryCoordination.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.OperatorOnly
                    : distributedRetryOrchestration.IsDisabled
                        ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Disabled
                        : isSingleNodeRuntime ||
                          distributedRetryOrchestration.IsCooldown ||
                          distributedRetryOrchestration.IsCompleted
                            ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Unscheduled
                            : schedulerConflicted
                                ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.SchedulerConflicted
                                : recoveryNeeded
                                    ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.RecoveryNeeded
                                    : canScheduleAutomaticRetryOnCurrentNode
                                        ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Scheduled
                                        : CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.LeaseBlocked;

        var categories = CreateManagedConnectorDurableSharedSchedulerOrchestrationCategories(
            state,
            automaticRetryCoordination,
            commandJournalDurability,
            distributedRetryOrchestration,
            multiNodeLeaseExecution,
            isSingleNodeRuntime,
            ownerMismatch,
            canScheduleAutomaticRetryOnCurrentNode);
        var description = CreateManagedConnectorDurableSharedSchedulerOrchestrationDescription(
            state,
            normalizedOperationId,
            automaticRetryCoordination,
            commandJournalDurability,
            distributedRetryOrchestration,
            multiNodeLeaseExecution,
            isSingleNodeRuntime,
            ownerMismatch);
        var sourceId = ResolveManagedConnectorDurableSharedSchedulerOrchestrationSourceId(
            state,
            automaticRetryCoordination,
            commandJournalDurability,
            distributedRetryOrchestration,
            multiNodeLeaseExecution,
            isSingleNodeRuntime,
            ownerMismatch);

        return new CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            CoordinationOwnerId = multiNodeLeaseExecution.CoordinationOwnerId,
            ActiveReporterId = multiNodeLeaseExecution.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = multiNodeLeaseExecution.ActiveReporterLeaseExpiresAtUtc,
            AutomaticRetryCoordinationState = automaticRetryCoordination.State,
            CommandJournalDurabilityState = commandJournalDurability.State,
            DistributedRetryOrchestrationState = distributedRetryOrchestration.State,
            MultiNodeLeaseExecutionState = multiNodeLeaseExecution.State,
            SourceId = sourceId,
            SchedulerId = multiNodeLeaseExecution.SchedulerId,
            SchedulerKind = multiNodeLeaseExecution.SchedulerKind,
            PollingIntervalSeconds = multiNodeLeaseExecution.PollingIntervalSeconds,
            RetryFingerprint = multiNodeLeaseExecution.RetryFingerprint,
            CooldownUntilUtc = multiNodeLeaseExecution.CooldownUntilUtc,
            LatestAutomaticRetryAttemptId = multiNodeLeaseExecution.LatestAutomaticRetryAttemptId,
            LatestAutomaticRetryRecordedAtUtc = multiNodeLeaseExecution.LatestAutomaticRetryRecordedAtUtc,
            HasDurableStoreConfigured = commandJournalDurability.HasDurableStoreConfigured,
            HasPersistedRecordedHistory = commandJournalDurability.HasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = commandJournalDurability.HasRecoveredPersistedHistory,
            CanScheduleAutomaticRetryOnCurrentNode = canScheduleAutomaticRetryOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorDurableSharedSchedulerOrchestrationCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        bool isSingleNodeRuntime,
        bool ownerMismatch,
        bool canScheduleAutomaticRetryOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 18);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.DurableSharedScheduler);
        AddCategory(
            categories,
            isSingleNodeRuntime
                ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.SingleNodeRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.LeaseCoordinatedRuntime);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.OperatorOnly);
        }

        if (!string.IsNullOrWhiteSpace(automaticRetryCoordination.ActiveReporterId))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.ActiveReporterVisible);
        }

        if (automaticRetryCoordination.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.ActiveLeaseVisible);
        }

        if (automaticRetryCoordination.CoordinationOwnerMatchesActiveReporter)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.OwnerMatch);
        }
        else if (ownerMismatch)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.OwnerMismatch);
        }

        if (commandJournalDurability.HasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.DurableJournalConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.InMemoryJournalOnly);
        }

        if (commandJournalDurability.IsDurable &&
            !commandJournalDurability.HasRecoveryError &&
            !commandJournalDurability.HasPersistenceError)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.DurableJournalHealthy);
        }

        if (commandJournalDurability.HasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.PersistedHistory);
        }

        if (commandJournalDurability.HasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.RecoveredHistory);
        }

        if (distributedRetryOrchestration.IsDisabled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.SchedulerDisabled);
        }

        if (distributedRetryOrchestration.IsCooldown)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.CooldownWindow);
        }

        if (distributedRetryOrchestration.IsCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.NoFurtherRetryNeeded);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Scheduled, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.Scheduled);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.CurrentNodeSchedulable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Unscheduled, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.Unscheduled);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.RecoveryNeeded, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.RecoveryNeeded);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.SchedulerConflicted, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.SchedulerConflicted);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.LeaseBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.LeaseBlocked);
        }

        if (!string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Unscheduled, StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Disabled, StringComparison.OrdinalIgnoreCase) &&
            !canScheduleAutomaticRetryOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationCategories.CurrentNodeBlocked);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorDurableSharedSchedulerOrchestrationDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        bool isSingleNodeRuntime,
        bool ownerMismatch)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                multiNodeLeaseExecution.Description,
                distributedRetryOrchestration.Description,
                commandJournalDurability.Description),
            automaticRetryCoordination.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose durable shared scheduler orchestration for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe durable shared scheduler orchestration posture for this managed connector, but scheduler ownership still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Disabled, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon identified a durable shared scheduler candidate for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but the shared scheduler lane is currently disabled for this runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Unscheduled, StringComparison.OrdinalIgnoreCase))
        {
            if (isSingleNodeRuntime)
            {
                return AppendManagedConnectorCommandEnvelopeDetail(
                    $"Cephalon does not currently need durable shared scheduler orchestration for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because this runtime still operates as a single-node retry lane.",
                    detail);
            }

            if (distributedRetryOrchestration.IsCooldown)
            {
                var cooldownMessage = distributedRetryOrchestration.CooldownUntilUtc.HasValue
                    ? $"Cephalon is keeping {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} off the durable shared scheduler until the cooldown window ends at '{distributedRetryOrchestration.CooldownUntilUtc.Value:O}'."
                    : $"Cephalon is keeping {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} off the durable shared scheduler while the current cooldown window remains active.";

                return AppendManagedConnectorCommandEnvelopeDetail(cooldownMessage, detail);
            }

            if (distributedRetryOrchestration.IsCompleted)
            {
                return AppendManagedConnectorCommandEnvelopeDetail(
                    $"Cephalon does not currently need to keep {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} scheduled on the durable shared scheduler because shared runtime truth already converged.",
                    detail);
            }

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon currently does not need to keep {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} scheduled on the durable shared scheduler.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.RecoveryNeeded, StringComparison.OrdinalIgnoreCase))
        {
            var recoveryReason =
                !commandJournalDurability.HasDurableStoreConfigured || commandJournalDurability.IsInMemoryOnly
                    ? "The bounded managed-connector command journal is still in memory only."
                    : commandJournalDurability.IsRecoveryFailed
                        ? $"The durable command journal still needs recovery after startup: {NormalizeManagedConnectorFingerprintSegment(commandJournalDurability.LastRecoveryError)}."
                        : commandJournalDurability.IsPersistenceFailed
                            ? $"The durable command journal could not persist the latest bounded scheduler evidence: {NormalizeManagedConnectorFingerprintSegment(commandJournalDurability.LastPersistenceError)}."
                            : "Durable command-journal recovery still needs to complete before the shared scheduler can continue.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot keep {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the durable shared scheduler yet. {recoveryReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.SchedulerConflicted, StringComparison.OrdinalIgnoreCase))
        {
            var conflictReason =
                ownerMismatch || automaticRetryCoordination.IsConflicted || automaticRetryCoordination.IsUncoordinated
                    ? "Reporter-lease ownership and local coordination truth still remain conflicted on the current node."
                    : multiNodeLeaseExecution.IsStaleLeaseRisk
                        ? "The broader multi-node lease posture still looks stale."
                        : "Shared scheduler ownership still remains conflicted across the current runtime truth.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot keep {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the durable shared scheduler right now. {conflictReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Scheduled, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Reporter '{NormalizeManagedConnectorFingerprintSegment(automaticRetryCoordination.ActiveReporterId)}' currently aligns with the local coordination owner, the bounded command journal is durable, and Cephalon can keep one bounded automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} scheduled on the shared durable scheduler.",
                detail);
        }

        var blockedReason =
            multiNodeLeaseExecution.IsLeaseBlocked
                ? "The broader multi-node lease-execution answer still blocks the current node."
                : distributedRetryOrchestration.IsBlocked
                    ? "Shared distributed retry orchestration still blocks the next bounded scheduling step."
                    : "Shared durable scheduler truth still blocks the current node.";

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon cannot keep {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} scheduled on the durable shared scheduler right now. {blockedReason}",
            detail);
    }

    private static string ResolveManagedConnectorDurableSharedSchedulerOrchestrationSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryCoordinationStatus automaticRetryCoordination,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        bool isSingleNodeRuntime,
        bool ownerMismatch)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(automaticRetryCoordination);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Disabled, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.DistributedRetryOrchestration;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Unscheduled, StringComparison.OrdinalIgnoreCase))
        {
            return isSingleNodeRuntime
                ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.MultiNodeLeaseExecution
                : CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.DistributedRetryOrchestration;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.RecoveryNeeded, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.CommandJournalDurability;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.SchedulerConflicted, StringComparison.OrdinalIgnoreCase))
        {
            return automaticRetryCoordination.IsConflicted ||
                   automaticRetryCoordination.IsUncoordinated ||
                   ownerMismatch
                ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.AutomaticRetryCoordination
                : CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.MultiNodeLeaseExecution;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStates.Scheduled, StringComparison.OrdinalIgnoreCase))
        {
            return commandJournalDurability.IsDurable
                ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.CommandJournalDurability
                : CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.MultiNodeLeaseExecution;
        }

        return multiNodeLeaseExecution.IsLeaseBlocked
            ? CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.MultiNodeLeaseExecution
            : CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationSources.DistributedRetryOrchestration;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus CreateManagedConnectorSchedulerRecoveryExecutionHardening(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        IReadOnlyList<CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult> commandExecutionHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandExecutionHistory);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId = string.IsNullOrWhiteSpace(durableSharedSchedulerOrchestration.OperationId)
            ? string.IsNullOrWhiteSpace(multiNodeLeaseExecution.OperationId)
                ? string.IsNullOrWhiteSpace(distributedRetryOrchestration.OperationId)
                    ? CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionOperationIds.None
                    : distributedRetryOrchestration.OperationId.Trim()
                : multiNodeLeaseExecution.OperationId.Trim()
            : durableSharedSchedulerOrchestration.OperationId.Trim();
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (commandJournalDurability.AppliesToManagedConnector ||
             distributedRetryOrchestration.AppliesToManagedConnector ||
             multiNodeLeaseExecution.AppliesToManagedConnector ||
             durableSharedSchedulerOrchestration.AppliesToManagedConnector);
        var isSingleNodeRuntime = multiNodeLeaseExecution.IsSingleNode;
        var latestAutomaticRetryEntry = commandExecutionHistory.FirstOrDefault(static entry => entry.IsAutomaticRetryInvocation);
        var hasAutomaticRetryAttemptRecorded = latestAutomaticRetryEntry is not null;
        var latestAutomaticRetryExecutionFingerprint = latestAutomaticRetryEntry?.ExecutionFingerprint ?? string.Empty;
        var latestCommandExecutionFingerprint = latestCommandExecution.IsUnrecorded
            ? string.Empty
            : latestCommandExecution.ExecutionFingerprint;
        var hasMatchingAutomaticRetryAttempt =
            !string.IsNullOrWhiteSpace(durableSharedSchedulerOrchestration.LatestAutomaticRetryAttemptId) &&
            commandExecutionHistory.Any(entry =>
                entry.IsAutomaticRetryInvocation &&
                string.Equals(
                    entry.AttemptId,
                    durableSharedSchedulerOrchestration.LatestAutomaticRetryAttemptId,
                    StringComparison.OrdinalIgnoreCase));
        var latestAutomaticExecutionSucceeded = latestAutomaticRetryEntry?.IsAdapted == true;
        var latestAutomaticExecutionRisk = latestAutomaticRetryEntry is not null &&
                                           (latestAutomaticRetryEntry.IsFailed ||
                                            latestAutomaticRetryEntry.IsBlocked ||
                                            latestAutomaticRetryEntry.IsOperatorOnly ||
                                            latestAutomaticRetryEntry.IsUnavailable);
        var canExecuteAutomaticRetryOnCurrentNode =
            durableSharedSchedulerOrchestration.CanScheduleAutomaticRetryOnCurrentNode &&
            !latestAutomaticExecutionRisk;
        var recoveryBlocked =
            durableSharedSchedulerOrchestration.IsRecoveryNeeded ||
            commandJournalDurability.IsInMemoryOnly ||
            commandJournalDurability.IsRecoveryFailed ||
            commandJournalDurability.IsPersistenceFailed ||
            !commandJournalDurability.HasDurableStoreConfigured;
        var executionRisk =
            durableSharedSchedulerOrchestration.IsSchedulerConflicted ||
            durableSharedSchedulerOrchestration.IsLeaseBlocked ||
            multiNodeLeaseExecution.IsLeaseConflicted ||
            multiNodeLeaseExecution.IsStaleLeaseRisk ||
            distributedRetryOrchestration.IsBlocked ||
            latestAutomaticExecutionRisk;
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.NotApplicable
                : durableSharedSchedulerOrchestration.IsOperatorOnly || multiNodeLeaseExecution.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.OperatorOnly
                    : recoveryBlocked
                        ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryBlocked
                        : executionRisk
                            ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionRisk
                            : commandJournalDurability.HasRecoveredPersistedHistory &&
                              canExecuteAutomaticRetryOnCurrentNode &&
                              hasMatchingAutomaticRetryAttempt
                                ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.Replaying
                                : commandJournalDurability.HasRecoveredPersistedHistory &&
                                  canExecuteAutomaticRetryOnCurrentNode
                                    ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryReady
                                    : commandJournalDurability.IsDurable &&
                                      (durableSharedSchedulerOrchestration.IsScheduled ||
                                       durableSharedSchedulerOrchestration.IsUnscheduled ||
                                       distributedRetryOrchestration.IsCompleted ||
                                       distributedRetryOrchestration.IsCooldown ||
                                       latestAutomaticExecutionSucceeded)
                                        ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionHardened
                                        : CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionRisk;

        var categories = CreateManagedConnectorSchedulerRecoveryExecutionHardeningCategories(
            state,
            commandJournalDurability,
            distributedRetryOrchestration,
            multiNodeLeaseExecution,
            durableSharedSchedulerOrchestration,
            latestAutomaticRetryEntry,
            isSingleNodeRuntime,
            hasAutomaticRetryAttemptRecorded,
            hasMatchingAutomaticRetryAttempt,
            canExecuteAutomaticRetryOnCurrentNode);
        var description = CreateManagedConnectorSchedulerRecoveryExecutionHardeningDescription(
            state,
            normalizedOperationId,
            commandJournalDurability,
            distributedRetryOrchestration,
            multiNodeLeaseExecution,
            durableSharedSchedulerOrchestration,
            latestAutomaticRetryEntry,
            isSingleNodeRuntime);
        var sourceId = ResolveManagedConnectorSchedulerRecoveryExecutionHardeningSourceId(
            state,
            commandJournalDurability,
            distributedRetryOrchestration,
            multiNodeLeaseExecution,
            durableSharedSchedulerOrchestration,
            latestAutomaticRetryEntry);

        return new CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            CoordinationOwnerId = durableSharedSchedulerOrchestration.CoordinationOwnerId,
            ActiveReporterId = durableSharedSchedulerOrchestration.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = durableSharedSchedulerOrchestration.ActiveReporterLeaseExpiresAtUtc,
            DurableSharedSchedulerOrchestrationState = durableSharedSchedulerOrchestration.State,
            MultiNodeLeaseExecutionState = multiNodeLeaseExecution.State,
            DistributedRetryOrchestrationState = distributedRetryOrchestration.State,
            CommandJournalDurabilityState = commandJournalDurability.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            SourceId = sourceId,
            SchedulerId = durableSharedSchedulerOrchestration.SchedulerId,
            SchedulerKind = durableSharedSchedulerOrchestration.SchedulerKind,
            PollingIntervalSeconds = durableSharedSchedulerOrchestration.PollingIntervalSeconds,
            RetryFingerprint = durableSharedSchedulerOrchestration.RetryFingerprint,
            LatestAutomaticRetryAttemptId = durableSharedSchedulerOrchestration.LatestAutomaticRetryAttemptId,
            LatestAutomaticRetryExecutionFingerprint = latestAutomaticRetryExecutionFingerprint,
            LatestCommandExecutionFingerprint = latestCommandExecutionFingerprint,
            LatestAutomaticRetryRecordedAtUtc = durableSharedSchedulerOrchestration.LatestAutomaticRetryRecordedAtUtc,
            HasDurableStoreConfigured = commandJournalDurability.HasDurableStoreConfigured,
            HasPersistedRecordedHistory = commandJournalDurability.HasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = commandJournalDurability.HasRecoveredPersistedHistory,
            HasMatchingAutomaticRetryAttempt = hasMatchingAutomaticRetryAttempt,
            CanExecuteAutomaticRetryOnCurrentNode = canExecuteAutomaticRetryOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorSchedulerRecoveryExecutionHardeningCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestAutomaticRetryEntry,
        bool isSingleNodeRuntime,
        bool hasAutomaticRetryAttemptRecorded,
        bool hasMatchingAutomaticRetryAttempt,
        bool canExecuteAutomaticRetryOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 24);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.SchedulerRecoveryExecutionHardening);
        AddCategory(
            categories,
            isSingleNodeRuntime
                ? CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.SingleNodeRuntime
                : CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.LeaseCoordinatedRuntime);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.RecoveryReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.RecoveryBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.Replaying, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.Replaying);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionHardened, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.ExecutionHardened);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.ExecutionRisk);
        }

        if (!string.IsNullOrWhiteSpace(durableSharedSchedulerOrchestration.ActiveReporterId))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.ActiveReporterVisible);
        }

        if (durableSharedSchedulerOrchestration.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.ActiveLeaseVisible);
        }

        if (multiNodeLeaseExecution.CoordinationOwnerMatchesActiveReporter)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.OwnerMatch);
        }
        else if (!string.IsNullOrWhiteSpace(multiNodeLeaseExecution.CoordinationOwnerId) &&
                 multiNodeLeaseExecution.HasActiveReporterLease)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.OwnerMismatch);
        }

        if (commandJournalDurability.HasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.DurableJournalConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.InMemoryJournalOnly);
        }

        if (commandJournalDurability.HasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.PersistedHistory);
        }

        if (commandJournalDurability.HasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.RecoveredHistory);
        }

        if (commandJournalDurability.IsRecoveryFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.RecoveryFailed);
        }

        if (commandJournalDurability.IsPersistenceFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.PersistenceFailed);
        }

        if (durableSharedSchedulerOrchestration.IsScheduled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.SchedulerScheduled);
        }
        else if (durableSharedSchedulerOrchestration.IsUnscheduled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.SchedulerUnscheduled);
        }
        else if (durableSharedSchedulerOrchestration.IsSchedulerConflicted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.SchedulerConflicted);
        }
        else if (durableSharedSchedulerOrchestration.IsLeaseBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.SchedulerLeaseBlocked);
        }

        if (distributedRetryOrchestration.IsCooldown)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.CooldownWindow);
        }

        if (distributedRetryOrchestration.IsCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.NoFurtherRetryNeeded);
        }

        if (hasAutomaticRetryAttemptRecorded)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.AutomaticRetryAttemptRecorded);
        }

        if (hasMatchingAutomaticRetryAttempt)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.MatchingAutomaticRetryAttempt);
        }

        if (latestAutomaticRetryEntry?.IsAdapted == true)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.LatestAutomaticExecutionAdapted);
        }
        else if (latestAutomaticRetryEntry?.IsFailed == true)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.LatestAutomaticExecutionFailed);
        }
        else if (latestAutomaticRetryEntry?.IsBlocked == true)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.LatestAutomaticExecutionBlocked);
        }
        else if (latestAutomaticRetryEntry?.IsOperatorOnly == true)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.LatestAutomaticExecutionOperatorOnly);
        }
        else if (latestAutomaticRetryEntry?.IsUnavailable == true)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.LatestAutomaticExecutionUnavailable);
        }

        if (canExecuteAutomaticRetryOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.CurrentNodeExecutable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryBlocked, StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningCategories.CurrentNodeBlocked);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorSchedulerRecoveryExecutionHardeningDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestAutomaticRetryEntry,
        bool isSingleNodeRuntime)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                CombineManagedConnectorCommandEnvelopeDetail(
                    durableSharedSchedulerOrchestration.Description,
                    multiNodeLeaseExecution.Description,
                    distributedRetryOrchestration.Description),
                commandJournalDurability.Description),
            latestAutomaticRetryEntry?.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose scheduler recovery and execution hardening for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe scheduler recovery and execution posture for this managed connector, but recovery and execution ownership still remain operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryBlocked, StringComparison.OrdinalIgnoreCase))
        {
            var recoveryReason =
                !commandJournalDurability.HasDurableStoreConfigured || commandJournalDurability.IsInMemoryOnly
                    ? "The bounded managed-connector command journal is still in memory only."
                    : commandJournalDurability.IsRecoveryFailed
                        ? $"The durable command journal still needs recovery after startup: {NormalizeManagedConnectorFingerprintSegment(commandJournalDurability.LastRecoveryError)}."
                        : commandJournalDurability.IsPersistenceFailed
                            ? $"The durable command journal could not persist the latest bounded scheduler evidence: {NormalizeManagedConnectorFingerprintSegment(commandJournalDurability.LastPersistenceError)}."
                            : "Shared scheduler recovery still needs durable journal evidence before bounded execution should continue.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot safely continue {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} yet. {recoveryReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.ExecutionRisk, StringComparison.OrdinalIgnoreCase))
        {
            var riskReason =
                latestAutomaticRetryEntry?.IsFailed == true
                    ? "The latest automatic retry attempt failed while Cephalon translated provider execution."
                    : latestAutomaticRetryEntry?.IsBlocked == true
                        ? "The latest automatic retry attempt was still blocked by shared runtime truth."
                        : latestAutomaticRetryEntry?.IsOperatorOnly == true
                            ? "The latest automatic retry attempt still remained operator-owned."
                            : latestAutomaticRetryEntry?.IsUnavailable == true
                                ? "The latest automatic retry attempt could not resolve a provider execution adapter."
                                : durableSharedSchedulerOrchestration.IsSchedulerConflicted
                                    ? "Durable shared scheduler ownership still remains conflicted across the current runtime truth."
                                    : durableSharedSchedulerOrchestration.IsLeaseBlocked || multiNodeLeaseExecution.IsLeaseBlocked
                                        ? "The broader multi-node lease-execution answer still blocks the current node."
                                        : multiNodeLeaseExecution.IsStaleLeaseRisk
                                            ? "The broader multi-node lease posture still looks stale."
                                            : distributedRetryOrchestration.IsBlocked
                                                ? "Shared distributed retry orchestration still blocks the next bounded execution step."
                                                : "Shared scheduler execution truth still remains risky on the current node.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot safely continue {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node right now. {riskReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.Replaying, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon recovered durable scheduler evidence and is replaying bounded execution truth for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon recovered durable scheduler evidence and can safely resume bounded execution for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node.",
                detail);
        }

        if (durableSharedSchedulerOrchestration.IsScheduled)
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"The durable shared scheduler, broader lease-execution truth, and retained journal evidence currently keep {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} hardened enough for bounded execution on the current node.",
                detail);
        }

        if (distributedRetryOrchestration.IsCooldown)
        {
            var cooldownMessage = distributedRetryOrchestration.CooldownUntilUtc.HasValue
                ? $"Cephalon already hardened bounded execution for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} and is waiting until the cooldown window ends at '{distributedRetryOrchestration.CooldownUntilUtc.Value:O}' before another step would run."
                : $"Cephalon already hardened bounded execution for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} and is still waiting for the current cooldown window to finish.";

            return AppendManagedConnectorCommandEnvelopeDetail(cooldownMessage, detail);
        }

        if (distributedRetryOrchestration.IsCompleted)
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon already hardened the bounded execution lane for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} and no further automatic retry is currently needed.",
                detail);
        }

        if (latestAutomaticRetryEntry?.IsAdapted == true)
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon already translated the latest automatic retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} and retained enough scheduler evidence to keep the execution lane hardened.",
                detail);
        }

        if (isSingleNodeRuntime)
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon currently keeps the bounded execution lane for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} hardened on a single node without broader cross-node scheduler recovery requirements.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon currently keeps the bounded execution lane for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} hardened enough for truthful shared scheduling and execution decisions.",
            detail);
    }

    private static string ResolveManagedConnectorSchedulerRecoveryExecutionHardeningSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalDurabilityStatus commandJournalDurability,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryOrchestrationStatus distributedRetryOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorMultiNodeLeaseExecutionStatus multiNodeLeaseExecution,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestAutomaticRetryEntry)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(commandJournalDurability);
        ArgumentNullException.ThrowIfNull(distributedRetryOrchestration);
        ArgumentNullException.ThrowIfNull(multiNodeLeaseExecution);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.Unknown;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryBlocked, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.RecoveryReady, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.CommandJournalDurability;
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStates.Replaying, StringComparison.OrdinalIgnoreCase) ||
            latestAutomaticRetryEntry is not null)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.CommandExecution;
        }

        if (durableSharedSchedulerOrchestration.IsSchedulerConflicted)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.DurableSharedSchedulerOrchestration;
        }

        if (durableSharedSchedulerOrchestration.IsLeaseBlocked ||
            multiNodeLeaseExecution.IsLeaseBlocked ||
            multiNodeLeaseExecution.IsLeaseConflicted ||
            multiNodeLeaseExecution.IsStaleLeaseRisk)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.MultiNodeLeaseExecution;
        }

        if (distributedRetryOrchestration.IsBlocked ||
            distributedRetryOrchestration.IsCooldown ||
            distributedRetryOrchestration.IsCompleted)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.DistributedRetryOrchestration;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningSources.DurableSharedSchedulerOrchestration;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus CreateManagedConnectorProviderOwnedWritePathExecution(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorDistributedRetryLeaseStatus distributedRetryLease,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(distributedRetryLease);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            !string.IsNullOrWhiteSpace(executionAdapter.OperationId)
                ? executionAdapter.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
                    ? retryExecutionPolicy.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(automaticRetryExecution.OperationId)
                        ? automaticRetryExecution.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(durableSharedSchedulerOrchestration.OperationId)
                            ? durableSharedSchedulerOrchestration.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.OperationId)
                                ? schedulerRecoveryExecutionHardening.OperationId.Trim()
                                : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (executionAdapter.AppliesToManagedConnector ||
             retryExecutionPolicy.AppliesToManagedConnector ||
             automaticRetryExecution.AppliesToManagedConnector ||
             distributedRetryLease.AppliesToManagedConnector ||
             durableSharedSchedulerOrchestration.AppliesToManagedConnector ||
             schedulerRecoveryExecutionHardening.AppliesToManagedConnector);
        var canExecuteProviderOwnedWritePathOnCurrentNode =
            executionAdapter.IsReady &&
            schedulerRecoveryExecutionHardening.CanExecuteAutomaticRetryOnCurrentNode &&
            (retryExecutionPolicy.IsRetryReady || automaticRetryExecution.IsEligible);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.NotApplicable
                : executionAdapter.IsOperatorOnly ||
                  retryExecutionPolicy.IsOperatorOnly ||
                  latestCommandExecution.IsOperatorOnly ||
                  schedulerRecoveryExecutionHardening.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.OperatorOnly
                    : latestCommandExecution.IsFailed ||
                      schedulerRecoveryExecutionHardening.IsRecoveryBlocked ||
                      schedulerRecoveryExecutionHardening.IsExecutionRisk
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedRisk
                        : latestCommandExecution.IsAdapted
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedExecuting
                            : latestCommandExecution.IsNoOp ||
                              automaticRetryExecution.IsCompleted ||
                              retryExecutionPolicy.IsNotNeeded
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedCompleted
                                : executionAdapter.IsBlocked ||
                                  executionAdapter.IsUnavailable ||
                                  latestCommandExecution.IsBlocked ||
                                  latestCommandExecution.IsUnavailable ||
                                  retryExecutionPolicy.IsPolicyBlocked ||
                                  retryExecutionPolicy.IsCooldown ||
                                  retryExecutionPolicy.RequiresManualApproval ||
                                  retryExecutionPolicy.IsBackgroundRetryDisabled ||
                                  automaticRetryExecution.IsDisabled ||
                                  automaticRetryExecution.IsBlocked
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderBlocked
                                    : canExecuteProviderOwnedWritePathOnCurrentNode
                                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderExecutable
                                        : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderBlocked;
        var wouldApplyChanges =
            executionAdapter.WouldApplyChanges ||
            retryExecutionPolicy.WouldApplyChanges ||
            automaticRetryExecution.WouldApplyChanges;
        var requiresExplicitApproval =
            executionAdapter.RequiresExplicitApproval ||
            retryExecutionPolicy.RequiresExplicitApproval ||
            automaticRetryExecution.RequiresExplicitApproval;
        var isDestructiveOperation =
            executionAdapter.IsDestructiveOperation ||
            retryExecutionPolicy.IsDestructiveOperation ||
            automaticRetryExecution.IsDestructiveOperation;
        var categories = CreateManagedConnectorProviderOwnedWritePathExecutionCategories(
            state,
            executionAdapter,
            latestCommandExecution,
            retryExecutionPolicy,
            automaticRetryExecution,
            canExecuteProviderOwnedWritePathOnCurrentNode,
            requiresExplicitApproval,
            isDestructiveOperation);
        var description = CreateManagedConnectorProviderOwnedWritePathExecutionDescription(
            state,
            normalizedOperationId,
            executionAdapter,
            latestCommandExecution,
            retryExecutionPolicy,
            automaticRetryExecution,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening);
        var sourceId = ResolveManagedConnectorProviderOwnedWritePathExecutionSourceId(
            state,
            executionAdapter,
            latestCommandExecution,
            retryExecutionPolicy,
            automaticRetryExecution,
            schedulerRecoveryExecutionHardening);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            AutomaticRetryExecutionState = automaticRetryExecution.State,
            DistributedRetryLeaseState = distributedRetryLease.State,
            DurableSharedSchedulerOrchestrationState = durableSharedSchedulerOrchestration.State,
            SchedulerRecoveryExecutionHardeningState = schedulerRecoveryExecutionHardening.State,
            AdapterId = executionAdapter.AdapterId,
            ProviderId = latestCommandExecution.ProviderId,
            ConnectClusterId = executionAdapter.ConnectClusterId ??
                               latestCommandExecution.ConnectClusterId ??
                               retryExecutionPolicy.ConnectClusterId ??
                               automaticRetryExecution.ConnectClusterId,
            ConnectorClass = executionAdapter.ConnectorClass ??
                             latestCommandExecution.ConnectorClass ??
                             retryExecutionPolicy.ConnectorClass ??
                             automaticRetryExecution.ConnectorClass,
            SourceProviderId = executionAdapter.SourceProviderId ??
                               latestCommandExecution.SourceProviderId ??
                               retryExecutionPolicy.SourceProviderId ??
                               automaticRetryExecution.SourceProviderId,
            CommandFingerprint = !string.IsNullOrWhiteSpace(executionAdapter.CommandFingerprint)
                ? executionAdapter.CommandFingerprint
                : !string.IsNullOrWhiteSpace(latestCommandExecution.CommandFingerprint)
                    ? latestCommandExecution.CommandFingerprint
                    : retryExecutionPolicy.CommandFingerprint,
            AdapterFingerprint = !string.IsNullOrWhiteSpace(executionAdapter.AdapterFingerprint)
                ? executionAdapter.AdapterFingerprint
                : !string.IsNullOrWhiteSpace(latestCommandExecution.AdapterFingerprint)
                    ? latestCommandExecution.AdapterFingerprint
                    : retryExecutionPolicy.AdapterFingerprint,
            LatestExecutionFingerprint = latestCommandExecution.IsUnrecorded
                ? string.Empty
                : latestCommandExecution.ExecutionFingerprint,
            RetryFingerprint = !string.IsNullOrWhiteSpace(retryExecutionPolicy.RetryFingerprint)
                ? retryExecutionPolicy.RetryFingerprint
                : !string.IsNullOrWhiteSpace(automaticRetryExecution.RetryFingerprint)
                    ? automaticRetryExecution.RetryFingerprint
                    : schedulerRecoveryExecutionHardening.RetryFingerprint,
            PotentialChangeCount = executionAdapter.PotentialChangeCount,
            LatestAttemptId = latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = latestCommandExecution.RecordedAtUtc,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            CanExecuteProviderOwnedWritePathOnCurrentNode = canExecuteProviderOwnedWritePathOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedWritePathExecutionCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        bool canExecuteProviderOwnedWritePathOnCurrentNode,
        bool requiresExplicitApproval,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 16);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderOwnedWritePathExecution);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderExecutable, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderExecutable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedExecuting, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderOwnedExecuting);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedCompleted, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderOwnedCompleted);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderOwnedRisk);
        }

        if (executionAdapter.IsReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.AdapterReady);
        }

        if (executionAdapter.IsUnavailable || latestCommandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.AdapterUnavailable);
        }

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.DestructiveOperation);
        }

        if (canExecuteProviderOwnedWritePathOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.CurrentNodeExecutable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderBlocked, StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.CurrentNodeBlocked);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderCommandOperatorOnly);
        }
        else if (latestCommandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderCommandUnavailable);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.ProviderCommandFailed);
        }

        if (retryExecutionPolicy.IsRetryReady || automaticRetryExecution.IsEligible)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.RetryReady);
        }

        if (retryExecutionPolicy.IsCooldown)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionCategories.CooldownWindow);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorProviderOwnedWritePathExecutionDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                CombineManagedConnectorCommandEnvelopeDetail(
                    CombineManagedConnectorCommandEnvelopeDetail(
                        executionAdapter.Description,
                        retryExecutionPolicy.Description,
                        automaticRetryExecution.Description),
                    durableSharedSchedulerOrchestration.Description),
                schedulerRecoveryExecutionHardening.Description),
            latestCommandExecution.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose provider-owned write-path execution for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe provider-owned write-path execution for this managed connector, but provider execution ownership still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedRisk, StringComparison.OrdinalIgnoreCase))
        {
            var riskReason =
                latestCommandExecution.IsFailed
                    ? "The latest provider-owned command failed while Cephalon translated provider execution."
                    : schedulerRecoveryExecutionHardening.IsRecoveryBlocked
                        ? "Scheduler recovery still needs durable journal evidence before provider-owned execution should continue."
                        : schedulerRecoveryExecutionHardening.IsExecutionRisk
                            ? "Broader scheduler and lease execution truth still remains unsafe on the current node."
                            : "The current shared provider execution lane still looks risky.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot safely continue {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node right now. {riskReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string blockReason;
            if (executionAdapter.IsBlocked)
            {
                blockReason = "The current provider execution adapter still remains blocked by shared runtime truth.";
            }
            else if (executionAdapter.IsUnavailable || latestCommandExecution.IsUnavailable)
            {
                blockReason = "No matching provider execution adapter is currently available for the managed connector.";
            }
            else if (latestCommandExecution.IsBlocked)
            {
                blockReason = "The latest provider-owned command remained blocked by the current shared runtime truth.";
            }
            else if (retryExecutionPolicy.RequiresManualApproval)
            {
                blockReason = "Explicit approval still needs to clear before Cephalon should execute the provider-owned write path.";
            }
            else if (retryExecutionPolicy.IsCooldown)
            {
                blockReason = retryExecutionPolicy.CooldownUntilUtc.HasValue
                    ? $"The shared retry policy is waiting until '{retryExecutionPolicy.CooldownUntilUtc.Value:O}' before another provider-owned step should run."
                    : "The shared retry policy is still waiting for the current cooldown window to finish.";
            }
            else if (retryExecutionPolicy.IsBackgroundRetryDisabled || automaticRetryExecution.IsDisabled)
            {
                blockReason = "Automatic provider-owned background execution is currently disabled on the shared lane.";
            }
            else
            {
                blockReason = "The current provider execution lane is not yet ready for another shared write-path step.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot execute {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} yet. {blockReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedExecuting, StringComparison.OrdinalIgnoreCase))
        {
            var attemptId = NormalizeManagedConnectorFingerprintSegment(latestCommandExecution.AttemptId);
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon already translated provider-owned command shape for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} during attempt '{attemptId}'.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.ProviderOwnedCompleted, StringComparison.OrdinalIgnoreCase))
        {
            var summary = latestCommandExecution.IsNoOp
                ? $"Cephalon determined that no provider command is currently needed for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}."
                : $"Cephalon does not currently need another provider-owned write-path step for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared lane.";

            return AppendManagedConnectorCommandEnvelopeDetail(summary, detail);
        }

        var adapterId = NormalizeManagedConnectorFingerprintSegment(executionAdapter.AdapterId);
        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon can execute provider-owned write-path for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node through adapter '{adapterId}'.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedWritePathExecutionSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorAutomaticRetryExecutionStatus automaticRetryExecution,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(automaticRetryExecution);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.Unknown;
        }

        if (latestCommandExecution.IsAdapted ||
            latestCommandExecution.IsNoOp ||
            latestCommandExecution.IsFailed ||
            latestCommandExecution.IsBlocked ||
            latestCommandExecution.IsUnavailable ||
            latestCommandExecution.IsOperatorOnly)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.CommandExecution;
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryBlocked ||
            schedulerRecoveryExecutionHardening.IsRecoveryReady ||
            schedulerRecoveryExecutionHardening.IsReplaying ||
            schedulerRecoveryExecutionHardening.IsExecutionHardened ||
            schedulerRecoveryExecutionHardening.IsExecutionRisk)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.SchedulerRecoveryExecutionHardening;
        }

        if (automaticRetryExecution.IsEligible ||
            automaticRetryExecution.IsCompleted ||
            automaticRetryExecution.IsBlocked ||
            automaticRetryExecution.IsDisabled)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.AutomaticRetryExecution;
        }

        if (retryExecutionPolicy.IsRetryReady ||
            retryExecutionPolicy.IsNotNeeded ||
            retryExecutionPolicy.IsCooldown ||
            retryExecutionPolicy.IsPolicyBlocked ||
            retryExecutionPolicy.RequiresManualApproval ||
            retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.RetryExecutionPolicy;
        }

        if (executionAdapter.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.ExecutionAdapter;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus CreateManagedConnectorProviderExecutionOrchestration(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.OperationId)
                ? providerOwnedWritePathExecution.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(executionAdapter.OperationId)
                    ? executionAdapter.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(commandJournal.OperationId)
                        ? commandJournal.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(durableSharedSchedulerOrchestration.OperationId)
                            ? durableSharedSchedulerOrchestration.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.OperationId)
                                ? schedulerRecoveryExecutionHardening.OperationId.Trim()
                                : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerOwnedWritePathExecution.AppliesToManagedConnector ||
             executionAdapter.AppliesToManagedConnector ||
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
             durableSharedSchedulerOrchestration.AppliesToManagedConnector ||
             schedulerRecoveryExecutionHardening.AppliesToManagedConnector);
        var hasCommandJournalEvidence =
            !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase);
        var hasDurableStoreConfigured =
            schedulerRecoveryExecutionHardening.HasDurableStoreConfigured ||
            durableSharedSchedulerOrchestration.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            schedulerRecoveryExecutionHardening.HasPersistedRecordedHistory ||
            durableSharedSchedulerOrchestration.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            schedulerRecoveryExecutionHardening.HasRecoveredPersistedHistory ||
            durableSharedSchedulerOrchestration.HasRecoveredPersistedHistory;
        var canOrchestrateProviderExecutionOnCurrentNode =
            providerOwnedWritePathExecution.CanExecuteProviderOwnedWritePathOnCurrentNode &&
            (providerOwnedWritePathExecution.IsProviderExecutable || providerOwnedWritePathExecution.IsProviderBlocked);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.NotApplicable
                : providerOwnedWritePathExecution.IsOperatorOnly ||
                  durableSharedSchedulerOrchestration.IsOperatorOnly ||
                  schedulerRecoveryExecutionHardening.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OperatorOnly
                    : providerOwnedWritePathExecution.IsProviderOwnedRisk ||
                      schedulerRecoveryExecutionHardening.IsRecoveryBlocked ||
                      schedulerRecoveryExecutionHardening.IsExecutionRisk ||
                      durableSharedSchedulerOrchestration.IsSchedulerConflicted
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationRisk
                        : providerOwnedWritePathExecution.IsProviderOwnedCompleted
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationCompleted
                            : providerOwnedWritePathExecution.IsProviderOwnedExecuting
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationExecuting
                                : canOrchestrateProviderExecutionOnCurrentNode || providerOwnedWritePathExecution.IsProviderExecutable
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationReady
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationBlocked;
        var wouldApplyChanges =
            providerOwnedWritePathExecution.WouldApplyChanges ||
            executionAdapter.WouldApplyChanges ||
            retryExecutionPolicy.WouldApplyChanges;
        var requiresExplicitApproval =
            providerOwnedWritePathExecution.RequiresExplicitApproval ||
            executionAdapter.RequiresExplicitApproval ||
            retryExecutionPolicy.RequiresExplicitApproval;
        var isDestructiveOperation =
            providerOwnedWritePathExecution.IsDestructiveOperation ||
            executionAdapter.IsDestructiveOperation ||
            retryExecutionPolicy.IsDestructiveOperation;
        var categories = CreateManagedConnectorProviderExecutionOrchestrationCategories(
            state,
            providerOwnedWritePathExecution,
            latestCommandExecution,
            commandJournal,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening,
            canOrchestrateProviderExecutionOnCurrentNode,
            requiresExplicitApproval,
            isDestructiveOperation,
            hasCommandJournalEvidence,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory);
        var description = CreateManagedConnectorProviderExecutionOrchestrationDescription(
            state,
            normalizedOperationId,
            providerOwnedWritePathExecution,
            latestCommandExecution,
            commandJournal,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening);
        var sourceId = ResolveManagedConnectorProviderExecutionOrchestrationSourceId(
            state,
            providerOwnedWritePathExecution,
            executionAdapter,
            latestCommandExecution,
            commandJournal,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            DurableSharedSchedulerOrchestrationState = durableSharedSchedulerOrchestration.State,
            SchedulerRecoveryExecutionHardeningState = schedulerRecoveryExecutionHardening.State,
            AdapterId = !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.AdapterId)
                ? providerOwnedWritePathExecution.AdapterId
                : executionAdapter.AdapterId,
            ProviderId = providerOwnedWritePathExecution.ProviderId ?? latestCommandExecution.ProviderId,
            ConnectClusterId = providerOwnedWritePathExecution.ConnectClusterId ??
                               executionAdapter.ConnectClusterId ??
                               latestCommandExecution.ConnectClusterId ??
                               retryExecutionPolicy.ConnectClusterId,
            ConnectorClass = providerOwnedWritePathExecution.ConnectorClass ??
                             executionAdapter.ConnectorClass ??
                             latestCommandExecution.ConnectorClass ??
                             retryExecutionPolicy.ConnectorClass,
            SourceProviderId = providerOwnedWritePathExecution.SourceProviderId ??
                               executionAdapter.SourceProviderId ??
                               latestCommandExecution.SourceProviderId ??
                               retryExecutionPolicy.SourceProviderId,
            CommandFingerprint = !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.CommandFingerprint)
                ? providerOwnedWritePathExecution.CommandFingerprint
                : !string.IsNullOrWhiteSpace(latestCommandExecution.CommandFingerprint)
                    ? latestCommandExecution.CommandFingerprint
                    : executionAdapter.CommandFingerprint,
            AdapterFingerprint = !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.AdapterFingerprint)
                ? providerOwnedWritePathExecution.AdapterFingerprint
                : !string.IsNullOrWhiteSpace(executionAdapter.AdapterFingerprint)
                    ? executionAdapter.AdapterFingerprint
                    : latestCommandExecution.AdapterFingerprint,
            LatestExecutionFingerprint = !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.LatestExecutionFingerprint)
                ? providerOwnedWritePathExecution.LatestExecutionFingerprint
                : latestCommandExecution.IsUnrecorded
                    ? string.Empty
                    : latestCommandExecution.ExecutionFingerprint,
            RetryFingerprint = !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.RetryFingerprint)
                ? providerOwnedWritePathExecution.RetryFingerprint
                : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.RetryFingerprint)
                    ? schedulerRecoveryExecutionHardening.RetryFingerprint
                    : durableSharedSchedulerOrchestration.RetryFingerprint,
            PotentialChangeCount = providerOwnedWritePathExecution.PotentialChangeCount > 0
                ? providerOwnedWritePathExecution.PotentialChangeCount
                : executionAdapter.PotentialChangeCount,
            LatestAttemptId = !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.LatestAttemptId)
                ? providerOwnedWritePathExecution.LatestAttemptId
                : latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = providerOwnedWritePathExecution.LatestRecordedAtUtc ?? latestCommandExecution.RecordedAtUtc,
            CoordinationOwnerId = schedulerRecoveryExecutionHardening.CoordinationOwnerId ?? durableSharedSchedulerOrchestration.CoordinationOwnerId,
            ActiveReporterId = schedulerRecoveryExecutionHardening.ActiveReporterId ?? durableSharedSchedulerOrchestration.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = schedulerRecoveryExecutionHardening.ActiveReporterLeaseExpiresAtUtc ?? durableSharedSchedulerOrchestration.ActiveReporterLeaseExpiresAtUtc,
            SchedulerId = !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.SchedulerId)
                ? schedulerRecoveryExecutionHardening.SchedulerId
                : durableSharedSchedulerOrchestration.SchedulerId,
            SchedulerKind = !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.SchedulerKind)
                ? schedulerRecoveryExecutionHardening.SchedulerKind
                : durableSharedSchedulerOrchestration.SchedulerKind,
            PollingIntervalSeconds = schedulerRecoveryExecutionHardening.PollingIntervalSeconds > 0
                ? schedulerRecoveryExecutionHardening.PollingIntervalSeconds
                : durableSharedSchedulerOrchestration.PollingIntervalSeconds,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            HasCommandJournalEvidence = hasCommandJournalEvidence,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanOrchestrateProviderExecutionOnCurrentNode = canOrchestrateProviderExecutionOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderExecutionOrchestrationCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening,
        bool canOrchestrateProviderExecutionOnCurrentNode,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool hasCommandJournalEvidence,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 20);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderExecutionOrchestration);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.OrchestrationReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.OrchestrationBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationExecuting, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.OrchestrationExecuting);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationCompleted, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.OrchestrationCompleted);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.OrchestrationRisk);
        }

        if (canOrchestrateProviderExecutionOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.CurrentNodeOrchestratable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationBlocked, StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.CurrentNodeBlocked);
        }

        if (providerOwnedWritePathExecution.IsProviderExecutable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderExecutable);
        }

        if (providerOwnedWritePathExecution.IsProviderBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderBlocked);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderOwnedExecuting);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderOwnedCompleted);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderOwnedRisk);
        }

        if (durableSharedSchedulerOrchestration.IsScheduled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.SchedulerScheduled);
        }

        if (durableSharedSchedulerOrchestration.IsUnscheduled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.SchedulerUnscheduled);
        }

        if (durableSharedSchedulerOrchestration.IsRecoveryNeeded)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.RecoveryNeeded);
        }

        if (durableSharedSchedulerOrchestration.IsSchedulerConflicted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.SchedulerConflicted);
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.RecoveryReady);
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.RecoveryBlocked);
        }

        if (schedulerRecoveryExecutionHardening.IsExecutionHardened)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ExecutionHardened);
        }

        if (schedulerRecoveryExecutionHardening.IsExecutionRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ExecutionRisk);
        }

        if (hasCommandJournalEvidence)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.CommandJournalEvidence);
        }
        else if (string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.NoRecordedCommand);
        }

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.DurableJournalConfigured);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationBlocked, StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.InMemoryJournalOnly);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.PersistedHistory);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.RecoveredHistory);
        }

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.DestructiveOperation);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderCommandOperatorOnly);
        }
        else if (latestCommandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderCommandUnavailable);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationCategories.ProviderCommandFailed);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorProviderExecutionOrchestrationDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                CombineManagedConnectorCommandEnvelopeDetail(
                    providerOwnedWritePathExecution.Description,
                    commandJournal.Description,
                    durableSharedSchedulerOrchestration.Description),
                schedulerRecoveryExecutionHardening.Description),
            latestCommandExecution.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose broader provider execution orchestration for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe broader provider execution orchestration for this managed connector, but provider execution ownership still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationRisk, StringComparison.OrdinalIgnoreCase))
        {
            var riskReason =
                schedulerRecoveryExecutionHardening.IsRecoveryBlocked
                    ? "Scheduler recovery still needs durable journal evidence before provider orchestration should continue."
                    : durableSharedSchedulerOrchestration.IsSchedulerConflicted
                        ? "Shared scheduler coordination still remains conflicted across ownership or lease truth."
                        : schedulerRecoveryExecutionHardening.IsExecutionRisk
                            ? "Broader scheduler and lease execution truth still remains unsafe on the current node."
                            : "The current shared provider execution orchestration lane still looks risky.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot safely continue provider execution orchestration for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node right now. {riskReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string blockReason;
            if (durableSharedSchedulerOrchestration.IsRecoveryNeeded)
            {
                blockReason = "The durable shared scheduler still needs recovery hardening before Cephalon should orchestrate another provider step.";
            }
            else if (durableSharedSchedulerOrchestration.IsLeaseBlocked)
            {
                blockReason = "The durable shared scheduler is still blocked by broader lease-execution truth.";
            }
            else if (string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.InsufficientForAutomation, StringComparison.OrdinalIgnoreCase))
            {
                blockReason = "Retained command-journal evidence is still insufficient for broader provider orchestration.";
            }
            else if (string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase))
            {
                blockReason = "No provider-execution command evidence has been recorded yet for the broader orchestration lane.";
            }
            else if (latestCommandExecution.IsBlocked)
            {
                blockReason = "The latest provider execution remained blocked by the current shared runtime truth.";
            }
            else if (latestCommandExecution.IsUnavailable)
            {
                blockReason = "No matching provider execution adapter is currently available for the broader orchestration lane.";
            }
            else
            {
                blockReason = "The broader provider execution orchestration lane is not yet ready for another shared step.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot orchestrate {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} yet. {blockReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationExecuting, StringComparison.OrdinalIgnoreCase))
        {
            var attemptId = NormalizeManagedConnectorFingerprintSegment(
                !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.LatestAttemptId)
                    ? providerOwnedWritePathExecution.LatestAttemptId
                    : latestCommandExecution.AttemptId);

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is currently orchestrating provider execution for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared lane; latest attempt '{attemptId}' already translated provider command shape.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.OrchestrationCompleted, StringComparison.OrdinalIgnoreCase))
        {
            var summary = latestCommandExecution.IsNoOp
                ? $"Cephalon determined that no additional provider execution orchestration step is currently needed for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}."
                : $"Cephalon does not currently need another provider execution orchestration step for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared lane.";

            return AppendManagedConnectorCommandEnvelopeDetail(summary, detail);
        }

        var schedulerId = NormalizeManagedConnectorFingerprintSegment(
            !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.SchedulerId)
                ? schedulerRecoveryExecutionHardening.SchedulerId
                : durableSharedSchedulerOrchestration.SchedulerId);
        var adapterId = NormalizeManagedConnectorFingerprintSegment(providerOwnedWritePathExecution.AdapterId);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon can orchestrate provider execution for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node through scheduler '{schedulerId}' and adapter '{adapterId}'.",
            detail);
    }

    private static string ResolveManagedConnectorProviderExecutionOrchestrationSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.Unknown;
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryBlocked ||
            schedulerRecoveryExecutionHardening.IsExecutionRisk)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.SchedulerRecoveryExecutionHardening;
        }

        if (durableSharedSchedulerOrchestration.IsSchedulerConflicted ||
            durableSharedSchedulerOrchestration.IsRecoveryNeeded ||
            durableSharedSchedulerOrchestration.IsLeaseBlocked)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.DurableSharedSchedulerOrchestration;
        }

        if (providerOwnedWritePathExecution.IsProviderExecutable ||
            providerOwnedWritePathExecution.IsProviderBlocked ||
            providerOwnedWritePathExecution.IsProviderOwnedExecuting ||
            providerOwnedWritePathExecution.IsProviderOwnedCompleted ||
            providerOwnedWritePathExecution.IsProviderOwnedRisk ||
            providerOwnedWritePathExecution.IsOperatorOnly)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.ProviderOwnedWritePathExecution;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.CommandJournal;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.CommandExecution;
        }

        if (executionAdapter.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.ExecutionAdapter;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus CreateManagedConnectorProviderOwnedControlPlaneOwnership(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            !string.IsNullOrWhiteSpace(providerExecutionOrchestration.OperationId)
                ? providerExecutionOrchestration.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.OperationId)
                    ? providerOwnedWritePathExecution.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(executionAdapter.OperationId)
                        ? executionAdapter.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(commandJournal.OperationId)
                            ? commandJournal.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(durableSharedSchedulerOrchestration.OperationId)
                                ? durableSharedSchedulerOrchestration.OperationId.Trim()
                                : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.OperationId)
                                    ? schedulerRecoveryExecutionHardening.OperationId.Trim()
                                    : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerExecutionOrchestration.AppliesToManagedConnector ||
             providerOwnedWritePathExecution.AppliesToManagedConnector ||
             executionAdapter.AppliesToManagedConnector ||
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) ||
             durableSharedSchedulerOrchestration.AppliesToManagedConnector ||
             schedulerRecoveryExecutionHardening.AppliesToManagedConnector);
        var hasCommandJournalEvidence =
            !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase);
        var hasDurableStoreConfigured =
            providerExecutionOrchestration.HasDurableStoreConfigured ||
            schedulerRecoveryExecutionHardening.HasDurableStoreConfigured ||
            durableSharedSchedulerOrchestration.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            providerExecutionOrchestration.HasPersistedRecordedHistory ||
            schedulerRecoveryExecutionHardening.HasPersistedRecordedHistory ||
            durableSharedSchedulerOrchestration.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            providerExecutionOrchestration.HasRecoveredPersistedHistory ||
            schedulerRecoveryExecutionHardening.HasRecoveredPersistedHistory ||
            durableSharedSchedulerOrchestration.HasRecoveredPersistedHistory;
        var wouldApplyChanges =
            providerExecutionOrchestration.WouldApplyChanges ||
            providerOwnedWritePathExecution.WouldApplyChanges ||
            executionAdapter.WouldApplyChanges ||
            retryExecutionPolicy.WouldApplyChanges;
        var requiresExplicitApproval =
            providerExecutionOrchestration.RequiresExplicitApproval ||
            providerOwnedWritePathExecution.RequiresExplicitApproval ||
            executionAdapter.RequiresExplicitApproval ||
            retryExecutionPolicy.RequiresExplicitApproval;
        var isDestructiveOperation =
            providerExecutionOrchestration.IsDestructiveOperation ||
            providerOwnedWritePathExecution.IsDestructiveOperation ||
            executionAdapter.IsDestructiveOperation ||
            retryExecutionPolicy.IsDestructiveOperation;
        var canExerciseProviderOwnedControlPlaneOnCurrentNode = providerExecutionOrchestration.CanOrchestrateProviderExecutionOnCurrentNode;
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.NotApplicable
                : providerExecutionOrchestration.IsOperatorOnly ||
                  providerOwnedWritePathExecution.IsOperatorOnly ||
                  durableSharedSchedulerOrchestration.IsOperatorOnly ||
                  schedulerRecoveryExecutionHardening.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OperatorOnly
                    : providerExecutionOrchestration.IsOrchestrationRisk ||
                      providerOwnedWritePathExecution.IsProviderOwnedRisk ||
                      schedulerRecoveryExecutionHardening.IsRecoveryBlocked ||
                      schedulerRecoveryExecutionHardening.IsExecutionRisk ||
                      durableSharedSchedulerOrchestration.IsSchedulerConflicted
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipRisk
                        : providerExecutionOrchestration.IsOrchestrationExecuting ||
                          providerOwnedWritePathExecution.IsProviderOwnedExecuting
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipActive
                            : providerExecutionOrchestration.IsOrchestrationReady &&
                              canExerciseProviderOwnedControlPlaneOnCurrentNode &&
                              !requiresExplicitApproval &&
                              !isDestructiveOperation
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipReady
                                : providerExecutionOrchestration.IsOrchestrationReady ||
                                  providerExecutionOrchestration.IsOrchestrationCompleted ||
                                  providerOwnedWritePathExecution.IsProviderOwnedCompleted ||
                                  providerOwnedWritePathExecution.IsProviderExecutable ||
                                  requiresExplicitApproval ||
                                  isDestructiveOperation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipPartial
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipBlocked;
        var categories = CreateManagedConnectorProviderOwnedControlPlaneOwnershipCategories(
            state,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            latestCommandExecution,
            commandJournal,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening,
            canExerciseProviderOwnedControlPlaneOnCurrentNode,
            requiresExplicitApproval,
            isDestructiveOperation,
            hasCommandJournalEvidence,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory);
        var description = CreateManagedConnectorProviderOwnedControlPlaneOwnershipDescription(
            state,
            normalizedOperationId,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            latestCommandExecution,
            commandJournal,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening,
            requiresExplicitApproval,
            isDestructiveOperation);
        var sourceId = ResolveManagedConnectorProviderOwnedControlPlaneOwnershipSourceId(
            state,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            executionAdapter,
            latestCommandExecution,
            commandJournal,
            durableSharedSchedulerOrchestration,
            schedulerRecoveryExecutionHardening);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            DurableSharedSchedulerOrchestrationState = durableSharedSchedulerOrchestration.State,
            SchedulerRecoveryExecutionHardeningState = schedulerRecoveryExecutionHardening.State,
            AdapterId = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.AdapterId)
                ? providerExecutionOrchestration.AdapterId
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.AdapterId)
                    ? providerOwnedWritePathExecution.AdapterId
                    : executionAdapter.AdapterId,
            ProviderId = providerExecutionOrchestration.ProviderId ??
                         providerOwnedWritePathExecution.ProviderId ??
                         latestCommandExecution.ProviderId,
            ConnectClusterId = providerExecutionOrchestration.ConnectClusterId ??
                               providerOwnedWritePathExecution.ConnectClusterId ??
                               executionAdapter.ConnectClusterId ??
                               latestCommandExecution.ConnectClusterId ??
                               retryExecutionPolicy.ConnectClusterId,
            ConnectorClass = providerExecutionOrchestration.ConnectorClass ??
                             providerOwnedWritePathExecution.ConnectorClass ??
                             executionAdapter.ConnectorClass ??
                             latestCommandExecution.ConnectorClass ??
                             retryExecutionPolicy.ConnectorClass,
            SourceProviderId = providerExecutionOrchestration.SourceProviderId ??
                               providerOwnedWritePathExecution.SourceProviderId ??
                               executionAdapter.SourceProviderId ??
                               latestCommandExecution.SourceProviderId ??
                               retryExecutionPolicy.SourceProviderId,
            CommandFingerprint = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.CommandFingerprint)
                ? providerExecutionOrchestration.CommandFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.CommandFingerprint)
                    ? providerOwnedWritePathExecution.CommandFingerprint
                    : !string.IsNullOrWhiteSpace(latestCommandExecution.CommandFingerprint)
                        ? latestCommandExecution.CommandFingerprint
                        : executionAdapter.CommandFingerprint,
            AdapterFingerprint = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.AdapterFingerprint)
                ? providerExecutionOrchestration.AdapterFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.AdapterFingerprint)
                    ? providerOwnedWritePathExecution.AdapterFingerprint
                    : !string.IsNullOrWhiteSpace(executionAdapter.AdapterFingerprint)
                        ? executionAdapter.AdapterFingerprint
                        : latestCommandExecution.AdapterFingerprint,
            LatestExecutionFingerprint = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.LatestExecutionFingerprint)
                ? providerExecutionOrchestration.LatestExecutionFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.LatestExecutionFingerprint)
                    ? providerOwnedWritePathExecution.LatestExecutionFingerprint
                    : latestCommandExecution.IsUnrecorded
                        ? string.Empty
                        : latestCommandExecution.ExecutionFingerprint,
            RetryFingerprint = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.RetryFingerprint)
                ? providerExecutionOrchestration.RetryFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.RetryFingerprint)
                    ? providerOwnedWritePathExecution.RetryFingerprint
                    : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.RetryFingerprint)
                        ? schedulerRecoveryExecutionHardening.RetryFingerprint
                        : durableSharedSchedulerOrchestration.RetryFingerprint,
            PotentialChangeCount = providerExecutionOrchestration.PotentialChangeCount > 0
                ? providerExecutionOrchestration.PotentialChangeCount
                : providerOwnedWritePathExecution.PotentialChangeCount > 0
                    ? providerOwnedWritePathExecution.PotentialChangeCount
                    : executionAdapter.PotentialChangeCount,
            LatestAttemptId = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.LatestAttemptId)
                ? providerExecutionOrchestration.LatestAttemptId
                : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.LatestAttemptId)
                    ? providerOwnedWritePathExecution.LatestAttemptId
                    : latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = providerExecutionOrchestration.LatestRecordedAtUtc ??
                                  providerOwnedWritePathExecution.LatestRecordedAtUtc ??
                                  latestCommandExecution.RecordedAtUtc,
            CoordinationOwnerId = providerExecutionOrchestration.CoordinationOwnerId ??
                                  schedulerRecoveryExecutionHardening.CoordinationOwnerId ??
                                  durableSharedSchedulerOrchestration.CoordinationOwnerId,
            ActiveReporterId = providerExecutionOrchestration.ActiveReporterId ??
                               schedulerRecoveryExecutionHardening.ActiveReporterId ??
                               durableSharedSchedulerOrchestration.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = providerExecutionOrchestration.ActiveReporterLeaseExpiresAtUtc ??
                                              schedulerRecoveryExecutionHardening.ActiveReporterLeaseExpiresAtUtc ??
                                              durableSharedSchedulerOrchestration.ActiveReporterLeaseExpiresAtUtc,
            SchedulerId = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.SchedulerId)
                ? providerExecutionOrchestration.SchedulerId
                : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.SchedulerId)
                    ? schedulerRecoveryExecutionHardening.SchedulerId
                    : durableSharedSchedulerOrchestration.SchedulerId,
            SchedulerKind = !string.IsNullOrWhiteSpace(providerExecutionOrchestration.SchedulerKind)
                ? providerExecutionOrchestration.SchedulerKind
                : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.SchedulerKind)
                    ? schedulerRecoveryExecutionHardening.SchedulerKind
                    : durableSharedSchedulerOrchestration.SchedulerKind,
            PollingIntervalSeconds = providerExecutionOrchestration.PollingIntervalSeconds > 0
                ? providerExecutionOrchestration.PollingIntervalSeconds
                : schedulerRecoveryExecutionHardening.PollingIntervalSeconds > 0
                    ? schedulerRecoveryExecutionHardening.PollingIntervalSeconds
                    : durableSharedSchedulerOrchestration.PollingIntervalSeconds,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            HasCommandJournalEvidence = hasCommandJournalEvidence,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExerciseProviderOwnedControlPlaneOnCurrentNode = canExerciseProviderOwnedControlPlaneOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedControlPlaneOwnershipCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening,
        bool canExerciseProviderOwnedControlPlaneOnCurrentNode,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool hasCommandJournalEvidence,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 24);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderOwnedControlPlaneOwnership);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.OwnershipReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.OwnershipBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipActive, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.OwnershipActive);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipPartial, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.OwnershipPartial);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.OwnershipRisk);
        }

        if (canExerciseProviderOwnedControlPlaneOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.CurrentNodeExecutable);
        }
        else if (!string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.CurrentNodeBlocked);
        }

        if (providerExecutionOrchestration.IsOrchestrationReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderExecutionReady);
        }

        if (providerExecutionOrchestration.IsOrchestrationBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderExecutionBlocked);
        }

        if (providerExecutionOrchestration.IsOrchestrationExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderExecutionExecuting);
        }

        if (providerExecutionOrchestration.IsOrchestrationCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderExecutionCompleted);
        }

        if (providerExecutionOrchestration.IsOrchestrationRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderExecutionRisk);
        }

        if (providerOwnedWritePathExecution.IsProviderExecutable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderExecutable);
        }

        if (providerOwnedWritePathExecution.IsProviderBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderBlocked);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderOwnedExecuting);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderOwnedCompleted);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderOwnedRisk);
        }

        if (durableSharedSchedulerOrchestration.IsScheduled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.SchedulerScheduled);
        }

        if (durableSharedSchedulerOrchestration.IsUnscheduled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.SchedulerUnscheduled);
        }

        if (durableSharedSchedulerOrchestration.IsRecoveryNeeded)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.RecoveryNeeded);
        }

        if (durableSharedSchedulerOrchestration.IsSchedulerConflicted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.SchedulerConflicted);
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.RecoveryReady);
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.RecoveryBlocked);
        }

        if (schedulerRecoveryExecutionHardening.IsExecutionHardened)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ExecutionHardened);
        }

        if (schedulerRecoveryExecutionHardening.IsExecutionRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ExecutionRisk);
        }

        if (hasCommandJournalEvidence)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.CommandJournalEvidence);
        }
        else if (string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.NoRecordedCommand);
        }

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.DurableJournalConfigured);
        }
        else if (!string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.InMemoryJournalOnly);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.PersistedHistory);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.RecoveredHistory);
        }

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.DestructiveOperation);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderCommandOperatorOnly);
        }
        else if (latestCommandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderCommandUnavailable);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipCategories.ProviderCommandFailed);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorProviderOwnedControlPlaneOwnershipDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening,
        bool requiresExplicitApproval,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                CombineManagedConnectorCommandEnvelopeDetail(
                    providerExecutionOrchestration.Description,
                    providerOwnedWritePathExecution.Description,
                    commandJournal.Description),
                durableSharedSchedulerOrchestration.Description,
                schedulerRecoveryExecutionHardening.Description),
            latestCommandExecution.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose provider-owned control-plane ownership for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can observe bounded provider-owned control-plane ownership for this managed connector, but control-plane ownership still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipRisk, StringComparison.OrdinalIgnoreCase))
        {
            var riskReason =
                schedulerRecoveryExecutionHardening.IsRecoveryBlocked
                    ? "Scheduler recovery still needs durable journal evidence before Cephalon should assert broader control-plane ownership."
                    : durableSharedSchedulerOrchestration.IsSchedulerConflicted
                        ? "Shared scheduler coordination still remains conflicted across ownership or lease truth."
                        : schedulerRecoveryExecutionHardening.IsExecutionRisk
                            ? "Broader scheduler and lease execution truth still remains unsafe on the current node."
                            : "The bounded provider-owned control-plane lane still looks risky right now.";

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot safely assert provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node right now. {riskReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string blockReason;
            if (providerExecutionOrchestration.IsOrchestrationBlocked)
            {
                blockReason = "Broader provider execution orchestration still remains blocked on the shared lane.";
            }
            else if (durableSharedSchedulerOrchestration.IsRecoveryNeeded)
            {
                blockReason = "The durable shared scheduler still needs recovery hardening before Cephalon should own another provider-facing step.";
            }
            else if (durableSharedSchedulerOrchestration.IsLeaseBlocked)
            {
                blockReason = "The durable shared scheduler is still blocked by broader lease-execution truth.";
            }
            else if (string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.InsufficientForAutomation, StringComparison.OrdinalIgnoreCase))
            {
                blockReason = "Retained command-journal evidence is still insufficient for bounded control-plane ownership.";
            }
            else if (string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase))
            {
                blockReason = "No provider-execution command evidence has been recorded yet for the bounded control-plane lane.";
            }
            else if (latestCommandExecution.IsBlocked)
            {
                blockReason = "The latest provider execution remained blocked by the current shared runtime truth.";
            }
            else if (latestCommandExecution.IsUnavailable)
            {
                blockReason = "No matching provider execution adapter is currently available for the bounded control-plane lane.";
            }
            else
            {
                blockReason = "The bounded provider-owned control-plane lane is not yet ready for another shared step.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon cannot currently assert provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}. {blockReason}",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipActive, StringComparison.OrdinalIgnoreCase))
        {
            var attemptId = NormalizeManagedConnectorFingerprintSegment(
                !string.IsNullOrWhiteSpace(providerExecutionOrchestration.LatestAttemptId)
                    ? providerExecutionOrchestration.LatestAttemptId
                    : !string.IsNullOrWhiteSpace(providerOwnedWritePathExecution.LatestAttemptId)
                        ? providerOwnedWritePathExecution.LatestAttemptId
                        : latestCommandExecution.AttemptId);

            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is currently exercising bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared lane; latest attempt '{attemptId}' already translated provider command shape.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.OwnershipPartial, StringComparison.OrdinalIgnoreCase))
        {
            string summary;
            if (requiresExplicitApproval)
            {
                summary = $"Cephalon exposes bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but explicit approval still gates execution.";
            }
            else if (isDestructiveOperation)
            {
                summary = $"Cephalon exposes bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but destructive execution still needs deliberate operator confirmation.";
            }
            else if (providerExecutionOrchestration.IsOrchestrationCompleted || latestCommandExecution.IsNoOp)
            {
                summary = $"Cephalon currently retains bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but no additional provider step is needed right now.";
            }
            else if (!providerExecutionOrchestration.CanOrchestrateProviderExecutionOnCurrentNode)
            {
                summary = $"Cephalon exposes bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but the current node is not the active control-plane owner.";
            }
            else
            {
                summary = $"Cephalon exposes bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but the lane remains partial while broader provider ownership stays intentionally limited.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(summary, detail);
        }

        var schedulerId = NormalizeManagedConnectorFingerprintSegment(
            !string.IsNullOrWhiteSpace(providerExecutionOrchestration.SchedulerId)
                ? providerExecutionOrchestration.SchedulerId
                : !string.IsNullOrWhiteSpace(schedulerRecoveryExecutionHardening.SchedulerId)
                    ? schedulerRecoveryExecutionHardening.SchedulerId
                    : durableSharedSchedulerOrchestration.SchedulerId);
        var adapterId = NormalizeManagedConnectorFingerprintSegment(
            !string.IsNullOrWhiteSpace(providerExecutionOrchestration.AdapterId)
                ? providerExecutionOrchestration.AdapterId
                : providerOwnedWritePathExecution.AdapterId);

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon can exercise bounded provider-owned control-plane ownership for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the current node through scheduler '{schedulerId}' and adapter '{adapterId}'.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedControlPlaneOwnershipSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorDurableSharedSchedulerOrchestrationStatus durableSharedSchedulerOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorSchedulerRecoveryExecutionHardeningStatus schedulerRecoveryExecutionHardening)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(durableSharedSchedulerOrchestration);
        ArgumentNullException.ThrowIfNull(schedulerRecoveryExecutionHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.Unknown;
        }

        if (schedulerRecoveryExecutionHardening.IsRecoveryBlocked ||
            schedulerRecoveryExecutionHardening.IsExecutionRisk)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.SchedulerRecoveryExecutionHardening;
        }

        if (durableSharedSchedulerOrchestration.IsSchedulerConflicted ||
            durableSharedSchedulerOrchestration.IsRecoveryNeeded ||
            durableSharedSchedulerOrchestration.IsLeaseBlocked)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.DurableSharedSchedulerOrchestration;
        }

        if (providerExecutionOrchestration.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.ProviderExecutionOrchestration;
        }

        if (providerOwnedWritePathExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.ProviderOwnedWritePathExecution;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.CommandJournal;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.CommandExecution;
        }

        if (executionAdapter.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.ExecutionAdapter;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus CreateManagedConnectorProviderOwnedControlPlaneMutationReconcile(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.OperationId)
                ? providerOwnedControlPlaneOwnership.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(commandIssuance.OperationId)
                    ? commandIssuance.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(commandEnvelope.OperationId)
                        ? commandEnvelope.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
                            ? retryExecutionPolicy.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(commandRetry.OperationId)
                                ? commandRetry.OperationId.Trim()
                                : !string.IsNullOrWhiteSpace(latestCommandExecution.ResolvedOperationId)
                                    ? latestCommandExecution.ResolvedOperationId.Trim()
                                    : !string.IsNullOrWhiteSpace(latestCommandExecution.RequestedOperationId)
                                        ? latestCommandExecution.RequestedOperationId.Trim()
                                        : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
             providerExecutionOrchestration.AppliesToManagedConnector ||
             providerOwnedWritePathExecution.AppliesToManagedConnector ||
             commandEnvelope.AppliesToManagedConnector ||
             commandIssuance.AppliesToManagedConnector ||
             commandRetry.AppliesToManagedConnector ||
             retryExecutionPolicy.AppliesToManagedConnector ||
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase));
        var hasTargetOperation = !string.Equals(
            normalizedOperationId,
            CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None,
            StringComparison.OrdinalIgnoreCase);
        var isReconcileOperation = hasTargetOperation &&
                                   string.Equals(
                                       normalizedOperationId,
                                       CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.Reconcile,
                                       StringComparison.OrdinalIgnoreCase);
        var isMutationOperation = hasTargetOperation && !isReconcileOperation;
        var hasCommandJournalEvidence =
            providerOwnedControlPlaneOwnership.HasCommandJournalEvidence ||
            (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) &&
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase));
        var hasDurableStoreConfigured = providerOwnedControlPlaneOwnership.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory = providerOwnedControlPlaneOwnership.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory = providerOwnedControlPlaneOwnership.HasRecoveredPersistedHistory;
        var wouldApplyChanges =
            providerOwnedControlPlaneOwnership.WouldApplyChanges ||
            commandEnvelope.WouldApplyChanges ||
            commandIssuance.WouldApplyChanges ||
            commandRetry.WouldApplyChanges ||
            retryExecutionPolicy.WouldApplyChanges ||
            latestCommandExecution.WouldApplyChanges;
        var requiresExplicitApproval =
            providerOwnedControlPlaneOwnership.RequiresExplicitApproval ||
            commandEnvelope.RequiresExplicitApproval ||
            commandIssuance.RequiresExplicitApproval ||
            commandRetry.RequiresExplicitApproval ||
            retryExecutionPolicy.RequiresExplicitApproval ||
            latestCommandExecution.RequiresExplicitApproval;
        var isDestructiveOperation =
            providerOwnedControlPlaneOwnership.IsDestructiveOperation ||
            commandEnvelope.IsDestructiveOperation ||
            commandIssuance.IsDestructiveOperation ||
            commandRetry.IsDestructiveOperation ||
            retryExecutionPolicy.IsDestructiveOperation ||
            latestCommandExecution.IsDestructiveOperation;
        var canExerciseProviderOwnedControlPlaneOnCurrentNode = providerOwnedControlPlaneOwnership.CanExerciseProviderOwnedControlPlaneOnCurrentNode;
        var canMutateOrReconcileOnCurrentNode =
            hasTargetOperation &&
            canExerciseProviderOwnedControlPlaneOnCurrentNode &&
            !requiresExplicitApproval &&
            !isDestructiveOperation &&
            (providerOwnedControlPlaneOwnership.IsOwnershipReady ||
             providerOwnedControlPlaneOwnership.IsOwnershipPartial ||
             providerOwnedControlPlaneOwnership.IsOwnershipActive ||
             providerExecutionOrchestration.IsOrchestrationReady ||
             providerExecutionOrchestration.IsOrchestrationCompleted ||
             providerOwnedWritePathExecution.IsProviderExecutable ||
             providerOwnedWritePathExecution.IsProviderOwnedCompleted ||
             commandEnvelope.IsEngineReady ||
             commandIssuance.IsAccepted ||
             commandIssuance.IsIssued ||
             retryExecutionPolicy.IsRetryReady);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.NotApplicable
                : providerOwnedControlPlaneOwnership.IsOperatorOnly ||
                  commandEnvelope.IsOperatorOnly ||
                  commandIssuance.IsOperatorOnly ||
                  commandRetry.IsOperatorOnly ||
                  retryExecutionPolicy.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.OperatorOnly
                    : providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
                      providerExecutionOrchestration.IsOrchestrationRisk ||
                      providerOwnedWritePathExecution.IsProviderOwnedRisk ||
                      latestCommandExecution.IsFailed
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationRisk
                        : providerOwnedControlPlaneOwnership.IsOwnershipActive ||
                          providerExecutionOrchestration.IsOrchestrationExecuting ||
                          providerOwnedWritePathExecution.IsProviderOwnedExecuting ||
                          latestCommandExecution.IsAdapted
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationExecuting
                            : isReconcileOperation
                                ? canMutateOrReconcileOnCurrentNode
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.ReconcileReady
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.ReconcileBlocked
                                : isMutationOperation && canMutateOrReconcileOnCurrentNode
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationReady
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationBlocked;
        var categories = CreateManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories(
            state,
            isMutationOperation,
            isReconcileOperation,
            providerOwnedControlPlaneOwnership,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            commandEnvelope,
            commandIssuance,
            latestCommandExecution,
            commandRetry,
            retryExecutionPolicy,
            canMutateOrReconcileOnCurrentNode,
            wouldApplyChanges,
            requiresExplicitApproval,
            isDestructiveOperation,
            hasCommandJournalEvidence,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory);
        var description = CreateManagedConnectorProviderOwnedControlPlaneMutationReconcileDescription(
            state,
            normalizedOperationId,
            hasTargetOperation,
            isReconcileOperation,
            providerOwnedControlPlaneOwnership,
            commandEnvelope,
            commandIssuance,
            latestCommandExecution,
            commandRetry,
            retryExecutionPolicy,
            commandJournal,
            canMutateOrReconcileOnCurrentNode);
        var sourceId = ResolveManagedConnectorProviderOwnedControlPlaneMutationReconcileSourceId(
            state,
            providerOwnedControlPlaneOwnership,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            commandEnvelope,
            commandIssuance,
            latestCommandExecution,
            commandRetry,
            retryExecutionPolicy,
            hasCommandJournalEvidence);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            AdapterId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.AdapterId)
                ? providerOwnedControlPlaneOwnership.AdapterId
                : providerOwnedWritePathExecution.AdapterId,
            ProviderId = providerOwnedControlPlaneOwnership.ProviderId ??
                         providerOwnedWritePathExecution.ProviderId ??
                         latestCommandExecution.ProviderId,
            ConnectClusterId = providerOwnedControlPlaneOwnership.ConnectClusterId ??
                               providerOwnedWritePathExecution.ConnectClusterId ??
                               commandIssuance.ConnectClusterId ??
                               commandEnvelope.ConnectClusterId ??
                               retryExecutionPolicy.ConnectClusterId ??
                               commandRetry.ConnectClusterId ??
                               latestCommandExecution.ConnectClusterId,
            ConnectorClass = providerOwnedControlPlaneOwnership.ConnectorClass ??
                             providerOwnedWritePathExecution.ConnectorClass ??
                             commandIssuance.ConnectorClass ??
                             commandEnvelope.ConnectorClass ??
                             retryExecutionPolicy.ConnectorClass ??
                             commandRetry.ConnectorClass ??
                             latestCommandExecution.ConnectorClass,
            SourceProviderId = providerOwnedControlPlaneOwnership.SourceProviderId ??
                               providerOwnedWritePathExecution.SourceProviderId ??
                               commandIssuance.SourceProviderId ??
                               commandEnvelope.SourceProviderId ??
                               retryExecutionPolicy.SourceProviderId ??
                               commandRetry.SourceProviderId ??
                               latestCommandExecution.SourceProviderId,
            CommandFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.CommandFingerprint)
                ? providerOwnedControlPlaneOwnership.CommandFingerprint
                : !string.IsNullOrWhiteSpace(commandIssuance.CommandFingerprint)
                    ? commandIssuance.CommandFingerprint
                    : !string.IsNullOrWhiteSpace(commandEnvelope.CommandFingerprint)
                        ? commandEnvelope.CommandFingerprint
                        : !string.IsNullOrWhiteSpace(commandRetry.CommandFingerprint)
                            ? commandRetry.CommandFingerprint
                            : latestCommandExecution.CommandFingerprint,
            IssuanceFingerprint = !string.IsNullOrWhiteSpace(commandIssuance.IssuanceFingerprint)
                ? commandIssuance.IssuanceFingerprint
                : !string.IsNullOrWhiteSpace(commandRetry.IssuanceFingerprint)
                    ? commandRetry.IssuanceFingerprint
                    : retryExecutionPolicy.IssuanceFingerprint,
            LatestExecutionFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.LatestExecutionFingerprint)
                ? providerOwnedControlPlaneOwnership.LatestExecutionFingerprint
                : !string.IsNullOrWhiteSpace(latestCommandExecution.ExecutionFingerprint)
                    ? latestCommandExecution.ExecutionFingerprint
                    : retryExecutionPolicy.LatestExecutionFingerprint,
            RetryFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.RetryFingerprint)
                ? providerOwnedControlPlaneOwnership.RetryFingerprint
                : !string.IsNullOrWhiteSpace(commandRetry.RetryFingerprint)
                    ? commandRetry.RetryFingerprint
                    : retryExecutionPolicy.RetryFingerprint,
            PotentialChangeCount = providerOwnedControlPlaneOwnership.PotentialChangeCount > 0
                ? providerOwnedControlPlaneOwnership.PotentialChangeCount
                : commandIssuance.PotentialChangeCount > 0
                    ? commandIssuance.PotentialChangeCount
                    : commandEnvelope.PotentialChangeCount > 0
                        ? commandEnvelope.PotentialChangeCount
                        : commandRetry.PotentialChangeCount > 0
                            ? commandRetry.PotentialChangeCount
                            : retryExecutionPolicy.PotentialChangeCount,
            LatestAttemptId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.LatestAttemptId)
                ? providerOwnedControlPlaneOwnership.LatestAttemptId
                : !string.IsNullOrWhiteSpace(latestCommandExecution.AttemptId)
                    ? latestCommandExecution.AttemptId
                    : !string.IsNullOrWhiteSpace(commandRetry.LatestAttemptId)
                        ? commandRetry.LatestAttemptId
                        : retryExecutionPolicy.LatestAttemptId,
            LatestRecordedAtUtc = providerOwnedControlPlaneOwnership.LatestRecordedAtUtc ??
                                  latestCommandExecution.RecordedAtUtc ??
                                  commandRetry.LatestRecordedAtUtc ??
                                  retryExecutionPolicy.LatestRecordedAtUtc,
            CoordinationOwnerId = providerOwnedControlPlaneOwnership.CoordinationOwnerId,
            ActiveReporterId = providerOwnedControlPlaneOwnership.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = providerOwnedControlPlaneOwnership.ActiveReporterLeaseExpiresAtUtc,
            SchedulerId = providerOwnedControlPlaneOwnership.SchedulerId,
            SchedulerKind = providerOwnedControlPlaneOwnership.SchedulerKind,
            PollingIntervalSeconds = providerOwnedControlPlaneOwnership.PollingIntervalSeconds,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            HasTargetOperation = hasTargetOperation,
            IsMutationOperation = isMutationOperation,
            IsReconcileOperation = isReconcileOperation,
            HasCommandJournalEvidence = hasCommandJournalEvidence,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExerciseProviderOwnedControlPlaneOnCurrentNode = canExerciseProviderOwnedControlPlaneOnCurrentNode,
            CanMutateOrReconcileOnCurrentNode = canMutateOrReconcileOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories(
        string state,
        bool isMutationOperation,
        bool isReconcileOperation,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        bool canMutateOrReconcileOnCurrentNode,
        bool wouldApplyChanges,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool hasCommandJournalEvidence,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 32);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderOwnedControlPlaneMutationReconcile);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.MutationReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.ReconcileReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ReconcileReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.MutationBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.ReconcileBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ReconcileBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationExecuting, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.MutationExecuting);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.MutationRisk);
        }

        if (isMutationOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.MutationOperation);
        }
        else if (isReconcileOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ReconcileOperation);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.NoTargetOperation);
        }

        if (canMutateOrReconcileOnCurrentNode)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CurrentNodeExecutable);
        }
        else if (!string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CurrentNodeBlocked);
        }

        if (providerOwnedControlPlaneOwnership.IsOwnershipReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.OwnershipReady);
        }

        if (providerOwnedControlPlaneOwnership.IsOwnershipBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.OwnershipBlocked);
        }

        if (providerOwnedControlPlaneOwnership.IsOwnershipActive)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.OwnershipActive);
        }

        if (providerOwnedControlPlaneOwnership.IsOwnershipPartial)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.OwnershipPartial);
        }

        if (providerOwnedControlPlaneOwnership.IsOwnershipRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.OwnershipRisk);
        }

        if (providerExecutionOrchestration.IsOrchestrationReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderExecutionReady);
        }

        if (providerExecutionOrchestration.IsOrchestrationBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderExecutionBlocked);
        }

        if (providerExecutionOrchestration.IsOrchestrationExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderExecutionExecuting);
        }

        if (providerExecutionOrchestration.IsOrchestrationCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderExecutionCompleted);
        }

        if (providerExecutionOrchestration.IsOrchestrationRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderExecutionRisk);
        }

        if (providerOwnedWritePathExecution.IsProviderExecutable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderExecutable);
        }

        if (providerOwnedWritePathExecution.IsProviderBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderBlocked);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderOwnedExecuting);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderOwnedCompleted);
        }

        if (providerOwnedWritePathExecution.IsProviderOwnedRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderOwnedRisk);
        }

        if (commandEnvelope.IsEngineReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CommandEnvelopeReady);
        }

        if (commandEnvelope.IsBlocked || commandEnvelope.IsApprovalGated)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CommandEnvelopeBlocked);
        }

        if (commandIssuance.IsAccepted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CommandIssuanceAccepted);
        }

        if (commandIssuance.IsIssued)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CommandIssuanceIssued);
        }

        if (commandRetry.IsRetryEligible || retryExecutionPolicy.IsRetryReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.RetryEligible);
        }

        if (commandRetry.IsRetryBlocked ||
            commandRetry.IsCooldown ||
            commandRetry.IsDuplicate ||
            retryExecutionPolicy.IsPolicyBlocked ||
            retryExecutionPolicy.RequiresManualApproval ||
            retryExecutionPolicy.IsCooldown ||
            retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.RetryBlocked);
        }

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.DestructiveOperation);
        }

        if (wouldApplyChanges)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.WouldApplyChanges);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.NoChangesRequired);
        }

        if (hasCommandJournalEvidence)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.CommandJournalEvidence);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.NoRecordedCommand);
        }

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.DurableJournalConfigured);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.PersistedHistory);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.RecoveredHistory);
        }

        if (hasCommandJournalEvidence && !hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.InMemoryJournalOnly);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderCommandOperatorOnly);
        }
        else if (latestCommandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderCommandUnavailable);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileCategories.ProviderCommandFailed);
        }

        return [.. categories];
    }

    private static string CreateManagedConnectorProviderOwnedControlPlaneMutationReconcileDescription(
        string state,
        string operationId,
        bool hasTargetOperation,
        bool isReconcileOperation,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        bool canMutateOrReconcileOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                CombineManagedConnectorCommandEnvelopeDetail(
                    CombineManagedConnectorCommandEnvelopeDetail(
                        providerOwnedControlPlaneOwnership.Description,
                        commandEnvelope.Description,
                        commandIssuance.Description),
                    latestCommandExecution.Description,
                    commandRetry.Description),
                retryExecutionPolicy.Description,
                commandJournal.Description),
            null);
        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon does not currently expose provider-owned control-plane mutation and reconcile for this execution runtime.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Provider-owned control-plane mutation and reconcile for {operationLabel} still remains operator-owned outside Cephalon.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Provider-owned control-plane mutation and reconcile for {operationLabel} currently remains risky because broader shared control-plane truth is not safe enough yet.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationExecuting, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is currently exercising provider-owned control-plane {(isReconcileOperation ? "reconcile" : "mutation")} for {operationLabel} through the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.ReconcileReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can reconcile provider-owned control-plane state for {operationLabel} on the current node through the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.ReconcileBlocked, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                hasTargetOperation
                    ? $"Cephalon cannot yet reconcile provider-owned control-plane state for {operationLabel} because the shared provider lane is still blocked."
                    : "Cephalon cannot yet reconcile provider-owned control-plane state because no reconcile operation is currently targeted.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.MutationReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                canMutateOrReconcileOnCurrentNode
                    ? $"Cephalon can exercise provider-owned control-plane mutation for {operationLabel} on the current node through the shared provider lane."
                    : $"Cephalon can derive provider-owned control-plane mutation for {operationLabel}, but the current node still cannot execute it safely.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            hasTargetOperation
                ? $"Cephalon cannot yet exercise provider-owned control-plane mutation for {operationLabel} because the shared provider lane is still blocked."
                : "Cephalon cannot yet exercise provider-owned control-plane mutation because no provider-owned mutation or reconcile operation is currently targeted.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedControlPlaneMutationReconcileSourceId(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        bool hasCommandJournalEvidence)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.Unknown;
        }

        if (latestCommandExecution.IsAdapted ||
            latestCommandExecution.IsNoOp ||
            latestCommandExecution.IsBlocked ||
            latestCommandExecution.IsOperatorOnly ||
            latestCommandExecution.IsUnavailable ||
            latestCommandExecution.IsFailed)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.CommandExecution;
        }

        if (commandIssuance.IsIssued ||
            commandIssuance.IsAccepted ||
            commandIssuance.IsRejected)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.CommandIssuance;
        }

        if (commandEnvelope.IsEngineReady ||
            commandEnvelope.IsBlocked ||
            commandEnvelope.IsApprovalGated ||
            commandEnvelope.IsOperatorOnly)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.CommandEnvelope;
        }

        if (retryExecutionPolicy.IsRetryReady ||
            retryExecutionPolicy.IsPolicyBlocked ||
            retryExecutionPolicy.RequiresManualApproval ||
            retryExecutionPolicy.IsCooldown ||
            retryExecutionPolicy.IsBackgroundRetryDisabled)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.RetryExecutionPolicy;
        }

        if (commandRetry.IsRetryEligible ||
            commandRetry.IsRetryBlocked ||
            commandRetry.IsCooldown ||
            commandRetry.IsDuplicate)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.CommandRetry;
        }

        if (providerOwnedControlPlaneOwnership.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.ProviderOwnedControlPlaneOwnership;
        }

        if (providerExecutionOrchestration.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.ProviderExecutionOrchestration;
        }

        if (providerOwnedWritePathExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.ProviderOwnedWritePathExecution;
        }

        if (hasCommandJournalEvidence)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.CommandJournal;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus CreateManagedConnectorProviderOwnedControlPlaneProvisioning(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.OperationId)
                ? providerOwnedControlPlaneMutationReconcile.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.OperationId)
                    ? providerOwnedControlPlaneOwnership.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(commandIssuance.OperationId)
                        ? commandIssuance.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(commandEnvelope.OperationId)
                            ? commandEnvelope.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
                                ? retryExecutionPolicy.OperationId.Trim()
                                : !string.IsNullOrWhiteSpace(commandRetry.OperationId)
                                    ? commandRetry.OperationId.Trim()
                                    : !string.IsNullOrWhiteSpace(latestCommandExecution.ResolvedOperationId)
                                        ? latestCommandExecution.ResolvedOperationId.Trim()
                                        : !string.IsNullOrWhiteSpace(latestCommandExecution.RequestedOperationId)
                                            ? latestCommandExecution.RequestedOperationId.Trim()
                                            : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector ||
             providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
             providerExecutionOrchestration.AppliesToManagedConnector ||
             providerOwnedWritePathExecution.AppliesToManagedConnector ||
             commandEnvelope.AppliesToManagedConnector ||
             commandIssuance.AppliesToManagedConnector ||
             commandRetry.AppliesToManagedConnector ||
             retryExecutionPolicy.AppliesToManagedConnector ||
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase));
        var hasTargetOperation = !string.Equals(
            normalizedOperationId,
            CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None,
            StringComparison.OrdinalIgnoreCase);
        var isReconcileOperation = hasTargetOperation &&
                                   string.Equals(
                                       normalizedOperationId,
                                       CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.Reconcile,
                                       StringComparison.OrdinalIgnoreCase);
        var isMutationOperation = hasTargetOperation && !isReconcileOperation;
        var hasCommandJournalEvidence =
            providerOwnedControlPlaneMutationReconcile.HasCommandJournalEvidence ||
            providerOwnedControlPlaneOwnership.HasCommandJournalEvidence ||
            (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) &&
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase));
        var hasDurableStoreConfigured =
            providerOwnedControlPlaneMutationReconcile.HasDurableStoreConfigured ||
            providerOwnedControlPlaneOwnership.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            providerOwnedControlPlaneMutationReconcile.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneOwnership.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            providerOwnedControlPlaneMutationReconcile.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneOwnership.HasRecoveredPersistedHistory;
        var wouldApplyChanges =
            providerOwnedControlPlaneMutationReconcile.WouldApplyChanges ||
            providerOwnedControlPlaneOwnership.WouldApplyChanges ||
            providerOwnedWritePathExecution.WouldApplyChanges ||
            commandEnvelope.WouldApplyChanges ||
            commandIssuance.WouldApplyChanges ||
            commandRetry.WouldApplyChanges ||
            retryExecutionPolicy.WouldApplyChanges ||
            latestCommandExecution.WouldApplyChanges;
        var requiresExplicitApproval =
            providerOwnedControlPlaneMutationReconcile.RequiresExplicitApproval ||
            providerOwnedControlPlaneOwnership.RequiresExplicitApproval ||
            commandEnvelope.RequiresExplicitApproval ||
            commandIssuance.RequiresExplicitApproval ||
            commandRetry.RequiresExplicitApproval ||
            retryExecutionPolicy.RequiresExplicitApproval ||
            latestCommandExecution.RequiresExplicitApproval;
        var isDestructiveOperation =
            providerOwnedControlPlaneMutationReconcile.IsDestructiveOperation ||
            providerOwnedControlPlaneOwnership.IsDestructiveOperation ||
            commandEnvelope.IsDestructiveOperation ||
            commandIssuance.IsDestructiveOperation ||
            commandRetry.IsDestructiveOperation ||
            retryExecutionPolicy.IsDestructiveOperation ||
            latestCommandExecution.IsDestructiveOperation;
        var canExerciseProviderOwnedControlPlaneOnCurrentNode =
            providerOwnedControlPlaneMutationReconcile.CanExerciseProviderOwnedControlPlaneOnCurrentNode ||
            providerOwnedControlPlaneOwnership.CanExerciseProviderOwnedControlPlaneOnCurrentNode;
        var canMutateOrReconcileOnCurrentNode = providerOwnedControlPlaneMutationReconcile.CanMutateOrReconcileOnCurrentNode;
        var canProvisionProviderOwnedControlPlaneOnCurrentNode =
            hasTargetOperation &&
            !requiresExplicitApproval &&
            !isDestructiveOperation &&
            (providerOwnedControlPlaneMutationReconcile.CanMutateOrReconcileOnCurrentNode ||
             (providerOwnedControlPlaneOwnership.CanExerciseProviderOwnedControlPlaneOnCurrentNode &&
              (providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
               providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
               providerOwnedControlPlaneOwnership.IsOwnershipReady ||
               providerOwnedControlPlaneOwnership.IsOwnershipPartial ||
               providerOwnedControlPlaneOwnership.IsOwnershipActive ||
               providerExecutionOrchestration.IsOrchestrationReady ||
               providerExecutionOrchestration.IsOrchestrationCompleted ||
               providerOwnedWritePathExecution.IsProviderExecutable ||
               providerOwnedWritePathExecution.IsProviderOwnedCompleted ||
               commandEnvelope.IsEngineReady ||
               commandIssuance.IsAccepted ||
               commandIssuance.IsIssued ||
               retryExecutionPolicy.IsRetryReady)));
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.NotApplicable
                : providerOwnedControlPlaneMutationReconcile.IsOperatorOnly ||
                  providerOwnedControlPlaneOwnership.IsOperatorOnly ||
                  commandEnvelope.IsOperatorOnly ||
                  commandIssuance.IsOperatorOnly ||
                  commandRetry.IsOperatorOnly ||
                  retryExecutionPolicy.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.OperatorOnly
                    : providerOwnedControlPlaneMutationReconcile.IsMutationRisk ||
                      providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
                      providerExecutionOrchestration.IsOrchestrationRisk ||
                      providerOwnedWritePathExecution.IsProviderOwnedRisk ||
                      latestCommandExecution.IsFailed
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningRisk
                        : providerOwnedControlPlaneMutationReconcile.IsMutationExecuting ||
                          providerOwnedControlPlaneOwnership.IsOwnershipActive ||
                          providerExecutionOrchestration.IsOrchestrationExecuting ||
                          providerOwnedWritePathExecution.IsProviderOwnedExecuting ||
                          latestCommandExecution.IsAdapted
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningExecuting
                            : canProvisionProviderOwnedControlPlaneOnCurrentNode &&
                              (providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
                               providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
                               providerOwnedControlPlaneOwnership.IsOwnershipReady ||
                               providerExecutionOrchestration.IsOrchestrationReady ||
                               providerOwnedWritePathExecution.IsProviderExecutable ||
                               commandEnvelope.IsEngineReady ||
                               commandIssuance.IsAccepted ||
                               commandIssuance.IsIssued ||
                               retryExecutionPolicy.IsRetryReady)
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningReady
                                : providerOwnedControlPlaneOwnership.IsOwnershipPartial ||
                                  providerOwnedControlPlaneOwnership.IsOwnershipReady ||
                                  providerExecutionOrchestration.IsOrchestrationReady ||
                                  providerExecutionOrchestration.IsOrchestrationCompleted ||
                                  providerOwnedWritePathExecution.IsProviderExecutable ||
                                  providerOwnedWritePathExecution.IsProviderOwnedCompleted ||
                                  providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
                                  providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
                                  providerOwnedControlPlaneMutationReconcile.IsMutationBlocked ||
                                  providerOwnedControlPlaneMutationReconcile.IsReconcileBlocked ||
                                  requiresExplicitApproval ||
                                  isDestructiveOperation ||
                                  hasTargetOperation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningPartial
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningBlocked;
        var categories = CreateManagedConnectorProviderOwnedControlPlaneProvisioningCategories(
            state,
            isMutationOperation,
            isReconcileOperation,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneOwnership,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            commandEnvelope,
            commandIssuance,
            latestCommandExecution,
            commandRetry,
            retryExecutionPolicy,
            hasTargetOperation,
            canProvisionProviderOwnedControlPlaneOnCurrentNode,
            wouldApplyChanges,
            requiresExplicitApproval,
            isDestructiveOperation,
            hasCommandJournalEvidence,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory);
        var description = CreateManagedConnectorProviderOwnedControlPlaneProvisioningDescription(
            state,
            normalizedOperationId,
            hasTargetOperation,
            isReconcileOperation,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneOwnership,
            latestCommandExecution,
            commandJournal,
            canProvisionProviderOwnedControlPlaneOnCurrentNode,
            requiresExplicitApproval,
            isDestructiveOperation);
        var sourceId = ResolveManagedConnectorProviderOwnedControlPlaneProvisioningSourceId(
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneOwnership,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            commandEnvelope,
            commandIssuance,
            latestCommandExecution,
            commandRetry,
            retryExecutionPolicy,
            commandJournal);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            ProviderOwnedControlPlaneMutationReconcileState = providerOwnedControlPlaneMutationReconcile.State,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            AdapterId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.AdapterId)
                ? providerOwnedControlPlaneMutationReconcile.AdapterId
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.AdapterId)
                    ? providerOwnedControlPlaneOwnership.AdapterId
                    : providerOwnedWritePathExecution.AdapterId,
            ProviderId = providerOwnedControlPlaneMutationReconcile.ProviderId ??
                         providerOwnedControlPlaneOwnership.ProviderId ??
                         providerOwnedWritePathExecution.ProviderId ??
                         latestCommandExecution.ProviderId,
            ConnectClusterId = providerOwnedControlPlaneMutationReconcile.ConnectClusterId ??
                               providerOwnedControlPlaneOwnership.ConnectClusterId ??
                               providerOwnedWritePathExecution.ConnectClusterId ??
                               commandIssuance.ConnectClusterId ??
                               commandEnvelope.ConnectClusterId ??
                               retryExecutionPolicy.ConnectClusterId ??
                               commandRetry.ConnectClusterId ??
                               latestCommandExecution.ConnectClusterId,
            ConnectorClass = providerOwnedControlPlaneMutationReconcile.ConnectorClass ??
                             providerOwnedControlPlaneOwnership.ConnectorClass ??
                             providerOwnedWritePathExecution.ConnectorClass ??
                             commandIssuance.ConnectorClass ??
                             commandEnvelope.ConnectorClass ??
                             retryExecutionPolicy.ConnectorClass ??
                             commandRetry.ConnectorClass ??
                             latestCommandExecution.ConnectorClass,
            SourceProviderId = providerOwnedControlPlaneMutationReconcile.SourceProviderId ??
                               providerOwnedControlPlaneOwnership.SourceProviderId ??
                               providerOwnedWritePathExecution.SourceProviderId ??
                               commandIssuance.SourceProviderId ??
                               commandEnvelope.SourceProviderId ??
                               retryExecutionPolicy.SourceProviderId ??
                               commandRetry.SourceProviderId ??
                               latestCommandExecution.SourceProviderId,
            CommandFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.CommandFingerprint)
                ? providerOwnedControlPlaneMutationReconcile.CommandFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.CommandFingerprint)
                    ? providerOwnedControlPlaneOwnership.CommandFingerprint
                    : !string.IsNullOrWhiteSpace(commandIssuance.CommandFingerprint)
                        ? commandIssuance.CommandFingerprint
                        : !string.IsNullOrWhiteSpace(commandEnvelope.CommandFingerprint)
                            ? commandEnvelope.CommandFingerprint
                            : !string.IsNullOrWhiteSpace(commandRetry.CommandFingerprint)
                                ? commandRetry.CommandFingerprint
                                : latestCommandExecution.CommandFingerprint,
            IssuanceFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.IssuanceFingerprint)
                ? providerOwnedControlPlaneMutationReconcile.IssuanceFingerprint
                : !string.IsNullOrWhiteSpace(commandIssuance.IssuanceFingerprint)
                    ? commandIssuance.IssuanceFingerprint
                    : !string.IsNullOrWhiteSpace(commandRetry.IssuanceFingerprint)
                        ? commandRetry.IssuanceFingerprint
                        : retryExecutionPolicy.IssuanceFingerprint,
            LatestExecutionFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.LatestExecutionFingerprint)
                ? providerOwnedControlPlaneMutationReconcile.LatestExecutionFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.LatestExecutionFingerprint)
                    ? providerOwnedControlPlaneOwnership.LatestExecutionFingerprint
                    : latestCommandExecution.IsUnrecorded
                        ? string.Empty
                        : latestCommandExecution.ExecutionFingerprint,
            RetryFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.RetryFingerprint)
                ? providerOwnedControlPlaneMutationReconcile.RetryFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.RetryFingerprint)
                    ? providerOwnedControlPlaneOwnership.RetryFingerprint
                    : !string.IsNullOrWhiteSpace(commandRetry.RetryFingerprint)
                        ? commandRetry.RetryFingerprint
                        : retryExecutionPolicy.RetryFingerprint,
            PotentialChangeCount = providerOwnedControlPlaneMutationReconcile.PotentialChangeCount > 0
                ? providerOwnedControlPlaneMutationReconcile.PotentialChangeCount
                : providerOwnedControlPlaneOwnership.PotentialChangeCount > 0
                    ? providerOwnedControlPlaneOwnership.PotentialChangeCount
                    : commandIssuance.PotentialChangeCount > 0
                        ? commandIssuance.PotentialChangeCount
                        : commandEnvelope.PotentialChangeCount > 0
                            ? commandEnvelope.PotentialChangeCount
                            : commandRetry.PotentialChangeCount > 0
                                ? commandRetry.PotentialChangeCount
                                : retryExecutionPolicy.PotentialChangeCount,
            LatestAttemptId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.LatestAttemptId)
                ? providerOwnedControlPlaneMutationReconcile.LatestAttemptId
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.LatestAttemptId)
                    ? providerOwnedControlPlaneOwnership.LatestAttemptId
                    : !string.IsNullOrWhiteSpace(latestCommandExecution.AttemptId)
                        ? latestCommandExecution.AttemptId
                        : !string.IsNullOrWhiteSpace(commandRetry.LatestAttemptId)
                            ? commandRetry.LatestAttemptId
                            : retryExecutionPolicy.LatestAttemptId,
            LatestRecordedAtUtc = providerOwnedControlPlaneMutationReconcile.LatestRecordedAtUtc ??
                                  providerOwnedControlPlaneOwnership.LatestRecordedAtUtc ??
                                  latestCommandExecution.RecordedAtUtc ??
                                  commandRetry.LatestRecordedAtUtc ??
                                  retryExecutionPolicy.LatestRecordedAtUtc,
            CoordinationOwnerId = providerOwnedControlPlaneMutationReconcile.CoordinationOwnerId ??
                                  providerOwnedControlPlaneOwnership.CoordinationOwnerId,
            ActiveReporterId = providerOwnedControlPlaneMutationReconcile.ActiveReporterId ??
                               providerOwnedControlPlaneOwnership.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = providerOwnedControlPlaneMutationReconcile.ActiveReporterLeaseExpiresAtUtc ??
                                              providerOwnedControlPlaneOwnership.ActiveReporterLeaseExpiresAtUtc,
            SchedulerId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.SchedulerId)
                ? providerOwnedControlPlaneMutationReconcile.SchedulerId
                : providerOwnedControlPlaneOwnership.SchedulerId,
            SchedulerKind = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.SchedulerKind)
                ? providerOwnedControlPlaneMutationReconcile.SchedulerKind
                : providerOwnedControlPlaneOwnership.SchedulerKind,
            PollingIntervalSeconds = providerOwnedControlPlaneMutationReconcile.PollingIntervalSeconds > 0
                ? providerOwnedControlPlaneMutationReconcile.PollingIntervalSeconds
                : providerOwnedControlPlaneOwnership.PollingIntervalSeconds,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            HasTargetOperation = hasTargetOperation,
            IsMutationOperation = isMutationOperation,
            IsReconcileOperation = isReconcileOperation,
            HasCommandJournalEvidence = hasCommandJournalEvidence,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExerciseProviderOwnedControlPlaneOnCurrentNode = canExerciseProviderOwnedControlPlaneOnCurrentNode,
            CanMutateOrReconcileOnCurrentNode = canMutateOrReconcileOnCurrentNode,
            CanProvisionProviderOwnedControlPlaneOnCurrentNode = canProvisionProviderOwnedControlPlaneOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedControlPlaneProvisioningCategories(
        string state,
        bool isMutationOperation,
        bool isReconcileOperation,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        bool hasTargetOperation,
        bool canProvisionProviderOwnedControlPlaneOnCurrentNode,
        bool wouldApplyChanges,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool hasCommandJournalEvidence,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 40);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderOwnedControlPlaneProvisioning);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProvisioningReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProvisioningBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningExecuting, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProvisioningExecuting);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningPartial, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProvisioningPartial);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProvisioningRisk);
        }

        if (!hasTargetOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.NoTargetOperation);
        }
        else if (isReconcileOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ReconcileOperation);
        }
        else if (isMutationOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.MutationOperation);
        }

        AddCategory(
            categories,
            canProvisionProviderOwnedControlPlaneOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CurrentNodeExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CurrentNodeBlocked);

        if (providerOwnedControlPlaneOwnership.IsOwnershipReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.OwnershipReady);
        }
        else if (providerOwnedControlPlaneOwnership.IsOwnershipBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.OwnershipBlocked);
        }
        else if (providerOwnedControlPlaneOwnership.IsOwnershipActive)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.OwnershipActive);
        }
        else if (providerOwnedControlPlaneOwnership.IsOwnershipPartial)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.OwnershipPartial);
        }
        else if (providerOwnedControlPlaneOwnership.IsOwnershipRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.OwnershipRisk);
        }

        if (providerOwnedControlPlaneMutationReconcile.IsMutationReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.MutationReady);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsReconcileReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ReconcileReady);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.MutationBlocked);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsReconcileBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ReconcileBlocked);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.MutationExecuting);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.MutationRisk);
        }

        if (providerExecutionOrchestration.IsOrchestrationReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderExecutionReady);
        }
        else if (providerExecutionOrchestration.IsOrchestrationBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderExecutionBlocked);
        }
        else if (providerExecutionOrchestration.IsOrchestrationExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderExecutionExecuting);
        }
        else if (providerExecutionOrchestration.IsOrchestrationCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderExecutionCompleted);
        }
        else if (providerExecutionOrchestration.IsOrchestrationRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderExecutionRisk);
        }

        if (providerOwnedWritePathExecution.IsProviderExecutable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderExecutable);
        }
        else if (providerOwnedWritePathExecution.IsProviderBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderBlocked);
        }
        else if (providerOwnedWritePathExecution.IsProviderOwnedExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderOwnedExecuting);
        }
        else if (providerOwnedWritePathExecution.IsProviderOwnedCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderOwnedCompleted);
        }
        else if (providerOwnedWritePathExecution.IsProviderOwnedRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderOwnedRisk);
        }

        if (commandEnvelope.IsEngineReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CommandEnvelopeReady);
        }
        else if (commandEnvelope.IsBlocked || commandEnvelope.IsApprovalGated)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CommandEnvelopeBlocked);
        }

        if (commandIssuance.IsAccepted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CommandIssuanceAccepted);
        }
        else if (commandIssuance.IsIssued)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CommandIssuanceIssued);
        }

        if (commandRetry.IsRetryEligible || retryExecutionPolicy.IsRetryReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.RetryEligible);
        }
        else if (commandRetry.IsRetryBlocked || retryExecutionPolicy.IsPolicyBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.RetryBlocked);
        }

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.DestructiveOperation);
        }

        AddCategory(
            categories,
            wouldApplyChanges
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.WouldApplyChanges
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.NoChangesRequired);

        AddCategory(
            categories,
            hasCommandJournalEvidence
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.CommandJournalEvidence
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.NoRecordedCommand);

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.DurableJournalConfigured);
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.InMemoryJournalOnly);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.PersistedHistory);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.RecoveredHistory);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderCommandOperatorOnly);
        }
        else if (latestCommandExecution.IsUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderCommandUnavailable);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningCategories.ProviderCommandFailed);
        }

        return categories
            .OrderBy(static category => category, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string CreateManagedConnectorProviderOwnedControlPlaneProvisioningDescription(
        string state,
        string operationId,
        bool hasTargetOperation,
        bool isReconcileOperation,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        bool canProvisionProviderOwnedControlPlaneOnCurrentNode,
        bool requiresExplicitApproval,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);
        var latestCommandDescription = latestCommandExecution.IsUnrecorded ? null : latestCommandExecution.Description;
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            latestCommandDescription,
            providerOwnedControlPlaneMutationReconcile.Description,
            CombineManagedConnectorCommandEnvelopeDetail(
                providerOwnedControlPlaneOwnership.Description,
                commandJournal.Description));

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "The execution runtime does not currently represent managed-connector provider-owned control-plane provisioning.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can describe provider-owned control-plane provisioning for {operationLabel}, but the provisioning lane still remains operator-owned outside the engine.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Provider-owned control-plane provisioning for {operationLabel} currently remains risky because broader shared control-plane truth is not safe enough yet.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningExecuting, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is currently exercising one bounded provider-owned control-plane provisioning step for {operationLabel} through the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can currently provision provider-owned control-plane state for {operationLabel} on the current node through the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningPartial, StringComparison.OrdinalIgnoreCase))
        {
            var summary = !hasTargetOperation
                ? "Cephalon exposes broader provider-owned control-plane provisioning truth, but no specific provisioning operation is currently targeted."
                : requiresExplicitApproval
                    ? $"Cephalon can stage provider-owned control-plane provisioning for {operationLabel}, but approval must still clear before the current node should exercise it."
                    : isDestructiveOperation
                        ? $"Cephalon can stage provider-owned control-plane provisioning for {operationLabel}, but the targeted change is still destructive and should not execute automatically."
                        : canProvisionProviderOwnedControlPlaneOnCurrentNode
                            ? $"Cephalon exposes a partially ready provider-owned control-plane provisioning answer for {operationLabel} on the current node."
                            : $"Cephalon exposes a partially ready provider-owned control-plane provisioning answer for {operationLabel}, but broader control-plane follow-through is not executable on the current node yet.";

            return AppendManagedConnectorCommandEnvelopeDetail(summary, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStates.ProvisioningBlocked, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                hasTargetOperation
                    ? $"Cephalon cannot yet provision provider-owned control-plane state for {operationLabel} because the shared provider lane is still blocked."
                    : "Cephalon cannot yet provision provider-owned control-plane state because no specific provisioning operation is currently targeted.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon exposes provider-owned control-plane provisioning truth for {operationLabel}.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedControlPlaneProvisioningSourceId(
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal)
    {
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        if (!string.Equals(providerOwnedControlPlaneMutationReconcile.State, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.ProviderOwnedControlPlaneMutationReconcile;
        }

        if (!string.Equals(providerOwnedControlPlaneOwnership.State, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.ProviderOwnedControlPlaneOwnership;
        }

        if (!string.Equals(providerExecutionOrchestration.State, CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.ProviderExecutionOrchestration;
        }

        if (!string.Equals(providerOwnedWritePathExecution.State, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.ProviderOwnedWritePathExecution;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.CommandExecution;
        }

        if (!string.Equals(commandIssuance.State, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.CommandIssuance;
        }

        if (!string.Equals(commandEnvelope.State, CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.CommandEnvelope;
        }

        if (!string.Equals(commandRetry.State, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.CommandRetry;
        }

        if (!string.Equals(retryExecutionPolicy.State, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.RetryExecutionPolicy;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.CommandJournal;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus CreateManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecution(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.OperationId)
                ? providerOwnedControlPlaneProvisioning.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.OperationId)
                    ? providerOwnedControlPlaneMutationReconcile.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.OperationId)
                        ? providerOwnedControlPlaneOwnership.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(commandIssuance.OperationId)
                            ? commandIssuance.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(commandEnvelope.OperationId)
                                ? commandEnvelope.OperationId.Trim()
                                : !string.IsNullOrWhiteSpace(retryExecutionPolicy.OperationId)
                                    ? retryExecutionPolicy.OperationId.Trim()
                                    : !string.IsNullOrWhiteSpace(commandRetry.OperationId)
                                        ? commandRetry.OperationId.Trim()
                                        : !string.IsNullOrWhiteSpace(latestCommandExecution.ResolvedOperationId)
                                            ? latestCommandExecution.ResolvedOperationId.Trim()
                                            : !string.IsNullOrWhiteSpace(latestCommandExecution.RequestedOperationId)
                                                ? latestCommandExecution.RequestedOperationId.Trim()
                                                : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerOwnedControlPlaneProvisioning.AppliesToManagedConnector ||
             providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector ||
             providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
             providerExecutionOrchestration.AppliesToManagedConnector ||
             providerOwnedWritePathExecution.AppliesToManagedConnector ||
             commandEnvelope.AppliesToManagedConnector ||
             commandIssuance.AppliesToManagedConnector ||
             commandRetry.AppliesToManagedConnector ||
             retryExecutionPolicy.AppliesToManagedConnector ||
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase));
        var hasTargetOperation =
            providerOwnedControlPlaneProvisioning.HasTargetOperation ||
            providerOwnedControlPlaneMutationReconcile.HasTargetOperation ||
            !string.Equals(
                normalizedOperationId,
                CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None,
                StringComparison.OrdinalIgnoreCase);
        var isReconcileOperation =
            providerOwnedControlPlaneProvisioning.IsReconcileOperation ||
            providerOwnedControlPlaneMutationReconcile.IsReconcileOperation ||
            (hasTargetOperation &&
             string.Equals(
                 normalizedOperationId,
                 CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.Reconcile,
                 StringComparison.OrdinalIgnoreCase));
        var isMutationOperation = hasTargetOperation && !isReconcileOperation;
        var hasCommandJournalEvidence =
            providerOwnedControlPlaneProvisioning.HasCommandJournalEvidence ||
            providerOwnedControlPlaneMutationReconcile.HasCommandJournalEvidence ||
            providerOwnedControlPlaneOwnership.HasCommandJournalEvidence ||
            (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase) &&
             !string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.Empty, StringComparison.OrdinalIgnoreCase));
        var hasDurableStoreConfigured =
            providerOwnedControlPlaneProvisioning.HasDurableStoreConfigured ||
            providerOwnedControlPlaneMutationReconcile.HasDurableStoreConfigured ||
            providerOwnedControlPlaneOwnership.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            providerOwnedControlPlaneProvisioning.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneOwnership.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            providerOwnedControlPlaneProvisioning.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneOwnership.HasRecoveredPersistedHistory;
        var wouldApplyChanges =
            providerOwnedControlPlaneProvisioning.WouldApplyChanges ||
            providerOwnedControlPlaneMutationReconcile.WouldApplyChanges ||
            providerOwnedControlPlaneOwnership.WouldApplyChanges ||
            providerOwnedWritePathExecution.WouldApplyChanges ||
            commandEnvelope.WouldApplyChanges ||
            commandIssuance.WouldApplyChanges ||
            commandRetry.WouldApplyChanges ||
            retryExecutionPolicy.WouldApplyChanges ||
            latestCommandExecution.WouldApplyChanges;
        var requiresExplicitApproval =
            providerOwnedControlPlaneProvisioning.RequiresExplicitApproval ||
            providerOwnedControlPlaneMutationReconcile.RequiresExplicitApproval ||
            providerOwnedControlPlaneOwnership.RequiresExplicitApproval ||
            commandEnvelope.RequiresExplicitApproval ||
            commandIssuance.RequiresExplicitApproval ||
            commandRetry.RequiresExplicitApproval ||
            retryExecutionPolicy.RequiresExplicitApproval ||
            latestCommandExecution.RequiresExplicitApproval;
        var isDestructiveOperation =
            providerOwnedControlPlaneProvisioning.IsDestructiveOperation ||
            providerOwnedControlPlaneMutationReconcile.IsDestructiveOperation ||
            providerOwnedControlPlaneOwnership.IsDestructiveOperation ||
            commandEnvelope.IsDestructiveOperation ||
            commandIssuance.IsDestructiveOperation ||
            commandRetry.IsDestructiveOperation ||
            retryExecutionPolicy.IsDestructiveOperation ||
            latestCommandExecution.IsDestructiveOperation;
        var canExerciseProviderOwnedControlPlaneOnCurrentNode =
            providerOwnedControlPlaneProvisioning.CanExerciseProviderOwnedControlPlaneOnCurrentNode ||
            providerOwnedControlPlaneMutationReconcile.CanExerciseProviderOwnedControlPlaneOnCurrentNode ||
            providerOwnedControlPlaneOwnership.CanExerciseProviderOwnedControlPlaneOnCurrentNode;
        var canMutateOrReconcileOnCurrentNode =
            providerOwnedControlPlaneProvisioning.CanMutateOrReconcileOnCurrentNode ||
            providerOwnedControlPlaneMutationReconcile.CanMutateOrReconcileOnCurrentNode;
        var canProvisionProviderOwnedControlPlaneOnCurrentNode =
            providerOwnedControlPlaneProvisioning.CanProvisionProviderOwnedControlPlaneOnCurrentNode;
        var canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode =
            hasTargetOperation &&
            (canProvisionProviderOwnedControlPlaneOnCurrentNode ||
             canMutateOrReconcileOnCurrentNode ||
             canExerciseProviderOwnedControlPlaneOnCurrentNode) &&
            !latestCommandExecution.IsAdapted &&
            !latestCommandExecution.IsNoOp &&
            !latestCommandExecution.IsFailed &&
            ((retryExecutionPolicy.IsRetryReady || commandRetry.IsRetryEligible) ||
             (!requiresExplicitApproval && !isDestructiveOperation)) &&
            (providerOwnedControlPlaneProvisioning.IsProvisioningReady ||
             providerOwnedControlPlaneProvisioning.IsProvisioningPartial ||
             providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
             providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
             providerOwnedControlPlaneOwnership.IsOwnershipReady ||
             providerExecutionOrchestration.IsOrchestrationReady ||
             providerOwnedWritePathExecution.IsProviderExecutable ||
             commandEnvelope.IsEngineReady ||
             commandIssuance.IsAccepted ||
             commandIssuance.IsIssued ||
             retryExecutionPolicy.IsRetryReady);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.NotApplicable
                : providerOwnedControlPlaneProvisioning.IsOperatorOnly ||
                  providerOwnedControlPlaneMutationReconcile.IsOperatorOnly ||
                  providerOwnedControlPlaneOwnership.IsOperatorOnly ||
                  commandEnvelope.IsOperatorOnly ||
                  commandIssuance.IsOperatorOnly ||
                  commandRetry.IsOperatorOnly ||
                  retryExecutionPolicy.IsOperatorOnly ||
                  latestCommandExecution.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.OperatorOnly
                    : providerOwnedControlPlaneProvisioning.IsProvisioningRisk ||
                      providerOwnedControlPlaneMutationReconcile.IsMutationRisk ||
                      providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
                      providerExecutionOrchestration.IsOrchestrationRisk ||
                      providerOwnedWritePathExecution.IsProviderOwnedRisk ||
                      latestCommandExecution.IsFailed
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileRisk
                        : latestCommandExecution.IsAdapted ||
                          providerOwnedControlPlaneProvisioning.IsProvisioningExecuting ||
                          providerOwnedControlPlaneMutationReconcile.IsMutationExecuting ||
                          providerOwnedControlPlaneOwnership.IsOwnershipActive ||
                          providerExecutionOrchestration.IsOrchestrationExecuting ||
                          providerOwnedWritePathExecution.IsProviderOwnedExecuting
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileExecuting
                            : latestCommandExecution.IsNoOp ||
                              (!wouldApplyChanges &&
                               hasTargetOperation &&
                               (providerOwnedWritePathExecution.IsProviderOwnedCompleted ||
                                providerExecutionOrchestration.IsOrchestrationCompleted ||
                                providerOwnedControlPlaneProvisioning.IsProvisioningReady ||
                                providerOwnedControlPlaneProvisioning.IsProvisioningPartial))
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileCompleted
                                : canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileReady
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileBlocked;
        var categories = CreateManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories(
            state,
            providerOwnedControlPlaneProvisioning.CategoryIds,
            latestCommandExecution,
            hasTargetOperation,
            canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode,
            wouldApplyChanges,
            requiresExplicitApproval,
            isDestructiveOperation);
        var description = CreateManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionDescription(
            state,
            normalizedOperationId,
            hasTargetOperation,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneMutationReconcile,
            latestCommandExecution,
            commandJournal,
            canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode,
            requiresExplicitApproval,
            isDestructiveOperation);
        var sourceId = ResolveManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSourceId(
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneOwnership,
            providerExecutionOrchestration,
            providerOwnedWritePathExecution,
            commandEnvelope,
            commandIssuance,
            latestCommandExecution,
            commandRetry,
            retryExecutionPolicy,
            commandJournal);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            ProviderOwnedControlPlaneProvisioningState = providerOwnedControlPlaneProvisioning.State,
            ProviderOwnedControlPlaneMutationReconcileState = providerOwnedControlPlaneMutationReconcile.State,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            LatestCommandExecutionInvocationSourceId = latestCommandExecution.InvocationSourceId,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            AdapterId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.AdapterId)
                ? providerOwnedControlPlaneProvisioning.AdapterId
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.AdapterId)
                    ? providerOwnedControlPlaneMutationReconcile.AdapterId
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.AdapterId)
                        ? providerOwnedControlPlaneOwnership.AdapterId
                        : providerOwnedWritePathExecution.AdapterId,
            ProviderId = providerOwnedControlPlaneProvisioning.ProviderId ??
                         providerOwnedControlPlaneMutationReconcile.ProviderId ??
                         providerOwnedControlPlaneOwnership.ProviderId ??
                         providerOwnedWritePathExecution.ProviderId ??
                         latestCommandExecution.ProviderId,
            ConnectClusterId = providerOwnedControlPlaneProvisioning.ConnectClusterId ??
                               providerOwnedControlPlaneMutationReconcile.ConnectClusterId ??
                               providerOwnedControlPlaneOwnership.ConnectClusterId ??
                               providerOwnedWritePathExecution.ConnectClusterId ??
                               commandIssuance.ConnectClusterId ??
                               commandEnvelope.ConnectClusterId ??
                               retryExecutionPolicy.ConnectClusterId ??
                               commandRetry.ConnectClusterId ??
                               latestCommandExecution.ConnectClusterId,
            ConnectorClass = providerOwnedControlPlaneProvisioning.ConnectorClass ??
                             providerOwnedControlPlaneMutationReconcile.ConnectorClass ??
                             providerOwnedControlPlaneOwnership.ConnectorClass ??
                             providerOwnedWritePathExecution.ConnectorClass ??
                             commandIssuance.ConnectorClass ??
                             commandEnvelope.ConnectorClass ??
                             retryExecutionPolicy.ConnectorClass ??
                             commandRetry.ConnectorClass ??
                             latestCommandExecution.ConnectorClass,
            SourceProviderId = providerOwnedControlPlaneProvisioning.SourceProviderId ??
                               providerOwnedControlPlaneMutationReconcile.SourceProviderId ??
                               providerOwnedControlPlaneOwnership.SourceProviderId ??
                               providerOwnedWritePathExecution.SourceProviderId ??
                               commandIssuance.SourceProviderId ??
                               commandEnvelope.SourceProviderId ??
                               retryExecutionPolicy.SourceProviderId ??
                               commandRetry.SourceProviderId ??
                               latestCommandExecution.SourceProviderId,
            CommandFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.CommandFingerprint)
                ? providerOwnedControlPlaneProvisioning.CommandFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.CommandFingerprint)
                    ? providerOwnedControlPlaneMutationReconcile.CommandFingerprint
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.CommandFingerprint)
                        ? providerOwnedControlPlaneOwnership.CommandFingerprint
                        : !string.IsNullOrWhiteSpace(commandIssuance.CommandFingerprint)
                            ? commandIssuance.CommandFingerprint
                            : !string.IsNullOrWhiteSpace(commandEnvelope.CommandFingerprint)
                                ? commandEnvelope.CommandFingerprint
                                : !string.IsNullOrWhiteSpace(commandRetry.CommandFingerprint)
                                    ? commandRetry.CommandFingerprint
                                    : latestCommandExecution.CommandFingerprint,
            IssuanceFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.IssuanceFingerprint)
                ? providerOwnedControlPlaneProvisioning.IssuanceFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.IssuanceFingerprint)
                    ? providerOwnedControlPlaneMutationReconcile.IssuanceFingerprint
                    : !string.IsNullOrWhiteSpace(commandIssuance.IssuanceFingerprint)
                        ? commandIssuance.IssuanceFingerprint
                        : !string.IsNullOrWhiteSpace(commandRetry.IssuanceFingerprint)
                            ? commandRetry.IssuanceFingerprint
                            : retryExecutionPolicy.IssuanceFingerprint,
            LatestExecutionFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.LatestExecutionFingerprint)
                ? providerOwnedControlPlaneProvisioning.LatestExecutionFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.LatestExecutionFingerprint)
                    ? providerOwnedControlPlaneMutationReconcile.LatestExecutionFingerprint
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.LatestExecutionFingerprint)
                        ? providerOwnedControlPlaneOwnership.LatestExecutionFingerprint
                        : latestCommandExecution.IsUnrecorded
                            ? string.Empty
                            : latestCommandExecution.ExecutionFingerprint,
            RetryFingerprint = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.RetryFingerprint)
                ? providerOwnedControlPlaneProvisioning.RetryFingerprint
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.RetryFingerprint)
                    ? providerOwnedControlPlaneMutationReconcile.RetryFingerprint
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.RetryFingerprint)
                        ? providerOwnedControlPlaneOwnership.RetryFingerprint
                        : !string.IsNullOrWhiteSpace(commandRetry.RetryFingerprint)
                            ? commandRetry.RetryFingerprint
                            : retryExecutionPolicy.RetryFingerprint,
            PotentialChangeCount = providerOwnedControlPlaneProvisioning.PotentialChangeCount > 0
                ? providerOwnedControlPlaneProvisioning.PotentialChangeCount
                : providerOwnedControlPlaneMutationReconcile.PotentialChangeCount > 0
                    ? providerOwnedControlPlaneMutationReconcile.PotentialChangeCount
                    : providerOwnedControlPlaneOwnership.PotentialChangeCount > 0
                        ? providerOwnedControlPlaneOwnership.PotentialChangeCount
                        : commandIssuance.PotentialChangeCount > 0
                            ? commandIssuance.PotentialChangeCount
                            : commandEnvelope.PotentialChangeCount > 0
                                ? commandEnvelope.PotentialChangeCount
                                : commandRetry.PotentialChangeCount > 0
                                    ? commandRetry.PotentialChangeCount
                                    : retryExecutionPolicy.PotentialChangeCount,
            LatestAttemptId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.LatestAttemptId)
                ? providerOwnedControlPlaneProvisioning.LatestAttemptId
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.LatestAttemptId)
                    ? providerOwnedControlPlaneMutationReconcile.LatestAttemptId
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneOwnership.LatestAttemptId)
                        ? providerOwnedControlPlaneOwnership.LatestAttemptId
                        : !string.IsNullOrWhiteSpace(latestCommandExecution.AttemptId)
                            ? latestCommandExecution.AttemptId
                            : !string.IsNullOrWhiteSpace(commandRetry.LatestAttemptId)
                                ? commandRetry.LatestAttemptId
                                : retryExecutionPolicy.LatestAttemptId,
            LatestRecordedAtUtc = providerOwnedControlPlaneProvisioning.LatestRecordedAtUtc ??
                                  providerOwnedControlPlaneMutationReconcile.LatestRecordedAtUtc ??
                                  providerOwnedControlPlaneOwnership.LatestRecordedAtUtc ??
                                  latestCommandExecution.RecordedAtUtc ??
                                  commandRetry.LatestRecordedAtUtc ??
                                  retryExecutionPolicy.LatestRecordedAtUtc,
            CoordinationOwnerId = providerOwnedControlPlaneProvisioning.CoordinationOwnerId ??
                                  providerOwnedControlPlaneMutationReconcile.CoordinationOwnerId ??
                                  providerOwnedControlPlaneOwnership.CoordinationOwnerId,
            ActiveReporterId = providerOwnedControlPlaneProvisioning.ActiveReporterId ??
                               providerOwnedControlPlaneMutationReconcile.ActiveReporterId ??
                               providerOwnedControlPlaneOwnership.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = providerOwnedControlPlaneProvisioning.ActiveReporterLeaseExpiresAtUtc ??
                                              providerOwnedControlPlaneMutationReconcile.ActiveReporterLeaseExpiresAtUtc ??
                                              providerOwnedControlPlaneOwnership.ActiveReporterLeaseExpiresAtUtc,
            SchedulerId = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.SchedulerId)
                ? providerOwnedControlPlaneProvisioning.SchedulerId
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.SchedulerId)
                    ? providerOwnedControlPlaneMutationReconcile.SchedulerId
                    : providerOwnedControlPlaneOwnership.SchedulerId,
            SchedulerKind = !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.SchedulerKind)
                ? providerOwnedControlPlaneProvisioning.SchedulerKind
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.SchedulerKind)
                    ? providerOwnedControlPlaneMutationReconcile.SchedulerKind
                    : providerOwnedControlPlaneOwnership.SchedulerKind,
            PollingIntervalSeconds = providerOwnedControlPlaneProvisioning.PollingIntervalSeconds > 0
                ? providerOwnedControlPlaneProvisioning.PollingIntervalSeconds
                : providerOwnedControlPlaneMutationReconcile.PollingIntervalSeconds > 0
                    ? providerOwnedControlPlaneMutationReconcile.PollingIntervalSeconds
                    : providerOwnedControlPlaneOwnership.PollingIntervalSeconds,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            HasTargetOperation = hasTargetOperation,
            IsMutationOperation = isMutationOperation,
            IsReconcileOperation = isReconcileOperation,
            HasCommandJournalEvidence = hasCommandJournalEvidence,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExerciseProviderOwnedControlPlaneOnCurrentNode = canExerciseProviderOwnedControlPlaneOnCurrentNode,
            CanMutateOrReconcileOnCurrentNode = canMutateOrReconcileOnCurrentNode,
            CanProvisionProviderOwnedControlPlaneOnCurrentNode = canProvisionProviderOwnedControlPlaneOnCurrentNode,
            CanExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode = canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories(
        string state,
        IReadOnlyList<string> provisioningCategories,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        bool hasTargetOperation,
        bool canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode,
        bool wouldApplyChanges,
        bool requiresExplicitApproval,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(provisioningCategories);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderOwnedControlPlaneApplyAndReconcileExecution
        };

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileReady, StringComparison.OrdinalIgnoreCase))
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ApplyAndReconcileReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileBlocked, StringComparison.OrdinalIgnoreCase))
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ApplyAndReconcileBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileExecuting, StringComparison.OrdinalIgnoreCase))
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ApplyAndReconcileExecuting);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileCompleted, StringComparison.OrdinalIgnoreCase))
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ApplyAndReconcileCompleted);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileRisk, StringComparison.OrdinalIgnoreCase))
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ApplyAndReconcileRisk);
        }

        foreach (var category in provisioningCategories)
        {
            categories.Add(category);
        }

        categories.Add(
            hasTargetOperation
                ? canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.CurrentNodeExecutable
                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.CurrentNodeBlocked
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.NoTargetOperation);

        categories.Add(
            wouldApplyChanges
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.WouldApplyChanges
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.NoChangesRequired);

        if (requiresExplicitApproval)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.DestructiveOperation);
        }

        if (latestCommandExecution.IsAdapted)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsOperatorOnly)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderCommandOperatorOnly);
        }
        else if (latestCommandExecution.IsUnavailable)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderCommandUnavailable);
        }
        else if (latestCommandExecution.IsFailed)
        {
            categories.Add(CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionCategories.ProviderCommandFailed);
        }

        return categories
            .OrderBy(static category => category, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string CreateManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionDescription(
        string state,
        string operationId,
        bool hasTargetOperation,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        bool canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode,
        bool requiresExplicitApproval,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);

        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);
        var latestCommandDescription = latestCommandExecution.IsUnrecorded ? null : latestCommandExecution.Description;
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            latestCommandDescription,
            providerOwnedControlPlaneProvisioning.Description,
            CombineManagedConnectorCommandEnvelopeDetail(
                providerOwnedControlPlaneMutationReconcile.Description,
                commandJournal.Description));

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "The execution runtime does not currently represent managed-connector provider-owned control-plane apply-and-reconcile execution.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can describe provider-owned control-plane apply-and-reconcile execution for {operationLabel}, but the execution lane still remains operator-owned outside the engine.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Provider-owned control-plane apply-and-reconcile execution for {operationLabel} currently remains risky because broader shared execution truth is not safe enough yet.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileExecuting, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is currently exercising one bounded provider-owned control-plane apply-and-reconcile step for {operationLabel} through the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileCompleted, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                latestCommandExecution.IsNoOp
                    ? $"Cephalon evaluated provider-owned control-plane apply-and-reconcile execution for {operationLabel} and no further shared execution step is currently required."
                    : $"Cephalon no longer needs another shared provider-owned control-plane apply-and-reconcile execution step for {operationLabel}.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can currently execute provider-owned control-plane apply-and-reconcile for {operationLabel} on the current node through the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStates.ApplyAndReconcileBlocked, StringComparison.OrdinalIgnoreCase))
        {
            var summary = !hasTargetOperation
                ? "Cephalon cannot yet execute provider-owned control-plane apply-and-reconcile because no specific operation is currently targeted."
                : requiresExplicitApproval
                    ? $"Cephalon can stage provider-owned control-plane apply-and-reconcile for {operationLabel}, but approval must still clear before the current node should execute it."
                    : isDestructiveOperation
                        ? $"Cephalon can stage provider-owned control-plane apply-and-reconcile for {operationLabel}, but the targeted change is still destructive and should not execute automatically."
                        : canExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode
                            ? $"Cephalon exposes blocked provider-owned control-plane apply-and-reconcile execution for {operationLabel} even though the current node still appears eligible."
                            : $"Cephalon cannot yet execute provider-owned control-plane apply-and-reconcile for {operationLabel} because the shared provider lane is still blocked on the current node.";

            return AppendManagedConnectorCommandEnvelopeDetail(summary, detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon exposes provider-owned control-plane apply-and-reconcile execution truth for {operationLabel}.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSourceId(
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal)
    {
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.CommandExecution;
        }

        if (providerOwnedControlPlaneProvisioning.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.ProviderOwnedControlPlaneProvisioning;
        }

        if (providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.ProviderOwnedControlPlaneMutationReconcile;
        }

        if (providerOwnedControlPlaneOwnership.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.ProviderOwnedControlPlaneOwnership;
        }

        if (providerExecutionOrchestration.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.ProviderExecutionOrchestration;
        }

        if (providerOwnedWritePathExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.ProviderOwnedWritePathExecution;
        }

        if (!string.Equals(commandIssuance.State, CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.CommandIssuance;
        }

        if (!string.Equals(commandEnvelope.State, CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.CommandEnvelope;
        }

        if (!string.Equals(commandRetry.State, CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.CommandRetry;
        }

        if (!string.Equals(retryExecutionPolicy.State, CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.RetryExecutionPolicy;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.CommandJournal;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStatus CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardening(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string executionOwnership,
        string executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        ManagedConnectorMetadataSnapshot metadataSnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(metadataSnapshot);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId = string.IsNullOrWhiteSpace(providerOwnedControlPlaneApplyAndReconcileExecution.OperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None
            : providerOwnedControlPlaneApplyAndReconcileExecution.OperationId.Trim();
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector ||
             providerOwnedControlPlaneProvisioning.AppliesToManagedConnector ||
             providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector ||
             providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
             providerExecutionOrchestration.AppliesToManagedConnector ||
             providerOwnedWritePathExecution.AppliesToManagedConnector ||
             governance.AppliesToManagedConnector ||
             drift.CanEvaluateDrift);
        var hasDeclaredDependencyIdentity =
            !string.IsNullOrWhiteSpace(metadataSnapshot.DeclaredConnectClusterId) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.DeclaredConnectorClass) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.DeclaredSourceProviderId);
        var hasReportedDependencyIdentity =
            !string.IsNullOrWhiteSpace(metadataSnapshot.ReportedConnectClusterId) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.ReportedConnectorClass) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.ReportedSourceProviderId);
        var hasTaskBaseline = metadataSnapshot.ExpectedTaskCount.HasValue || metadataSnapshot.DeclaredTaskIds.Length > 0;
        var hasReportedTaskTopology = metadataSnapshot.ReportedTaskCount.HasValue || metadataSnapshot.ReportedTaskIds.Length > 0;
        var hasActiveTaskTopology = metadataSnapshot.ActiveTaskIds.Length > 0;
        var hasDependencyIdentityMismatch =
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase);
        var hasTaskTopologyMismatch =
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.TaskCountMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingDeclaredTaskReports, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.UnexpectedReportedTasks, StringComparer.OrdinalIgnoreCase);
        var hasTaskTopologyGap =
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingTaskBaseline, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskTopologyUnavailable, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskIdentityUnavailable, StringComparer.OrdinalIgnoreCase);
        var hasReconciliationDegraded = !IsManagedConnectorReconciliationStable(metadataSnapshot.ReconciliationState);
        var hasReporterLease = summary.HasActiveReporterLease;
        var hasReporterLeaseIssue = !hasReporterLease || summary.HasReporterCoordinationIssue || summary.HasStaleObservations;
        var hasDurableStoreConfigured =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasDurableStoreConfigured ||
            providerOwnedControlPlaneProvisioning.HasDurableStoreConfigured ||
            providerOwnedControlPlaneMutationReconcile.HasDurableStoreConfigured ||
            providerOwnedControlPlaneOwnership.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneProvisioning.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneOwnership.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneProvisioning.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneOwnership.HasRecoveredPersistedHistory;
        var canExecuteDependencyAwareApplyAndReconcileOnCurrentNode =
            providerOwnedControlPlaneApplyAndReconcileExecution.CanExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode &&
            hasDeclaredDependencyIdentity &&
            hasTaskBaseline &&
            hasReportedTaskTopology;
        var hasDependencyRisk =
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk ||
            providerOwnedControlPlaneProvisioning.IsProvisioningRisk ||
            providerOwnedControlPlaneMutationReconcile.IsMutationRisk ||
            providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
            providerExecutionOrchestration.IsOrchestrationRisk ||
            providerOwnedWritePathExecution.IsProviderOwnedRisk ||
            latestCommandExecution.IsFailed;
        var hasDependencyBlockers =
            !hasDeclaredDependencyIdentity ||
            !hasTaskBaseline ||
            !hasReportedTaskTopology ||
            !providerOwnedControlPlaneApplyAndReconcileExecution.HasTargetOperation ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileBlocked;
        var hasDependencyDegradation =
            hasDependencyIdentityMismatch ||
            hasTaskTopologyMismatch ||
            hasTaskTopologyGap ||
            !hasReportedDependencyIdentity ||
            !hasActiveTaskTopology ||
            hasReconciliationDegraded ||
            hasReporterLeaseIssue ||
            latestCommandExecution.IsBlocked ||
            latestCommandExecution.IsUnavailable;
        var hasHardenedEvidence =
            hasDeclaredDependencyIdentity &&
            hasReportedDependencyIdentity &&
            hasTaskBaseline &&
            hasReportedTaskTopology &&
            hasActiveTaskTopology &&
            !hasDependencyIdentityMismatch &&
            !hasTaskTopologyMismatch &&
            !hasTaskTopologyGap &&
            !hasReconciliationDegraded &&
            !hasReporterLeaseIssue &&
            (hasDurableStoreConfigured || hasPersistedRecordedHistory);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.NotApplicable
                : providerOwnedControlPlaneApplyAndReconcileExecution.IsOperatorOnly ||
                  providerOwnedControlPlaneProvisioning.IsOperatorOnly ||
                  providerOwnedControlPlaneMutationReconcile.IsOperatorOnly ||
                  providerOwnedControlPlaneOwnership.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.OperatorOnly
                    : hasDependencyRisk
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyRisk
                        : hasDependencyBlockers
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyBlocked
                            : hasHardenedEvidence &&
                              (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady ||
                               providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting ||
                               providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted)
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.ApplyAndReconcileHardened
                                : hasDependencyDegradation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyDegraded
                                    : canExecuteDependencyAwareApplyAndReconcileOnCurrentNode ||
                                      providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady
                                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyReady
                                        : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyBlocked;
        var categories = CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories(
            state,
            governance,
            drift,
            summary,
            latestCommandExecution,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            hasDeclaredDependencyIdentity,
            hasReportedDependencyIdentity,
            hasTaskBaseline,
            hasReportedTaskTopology,
            hasActiveTaskTopology,
            hasReconciliationDegraded,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory,
            canExecuteDependencyAwareApplyAndReconcileOnCurrentNode);
        var description = CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningDescription(
            state,
            normalizedOperationId,
            summary,
            latestCommandExecution,
            commandJournal,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            hasDeclaredDependencyIdentity,
            hasReportedDependencyIdentity,
            hasTaskBaseline,
            hasReportedTaskTopology,
            hasActiveTaskTopology,
            hasReconciliationDegraded,
            hasReporterLeaseIssue,
            metadataSnapshot.ReconciliationReason);
        var sourceId = ResolveManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSourceId(
            governance,
            drift,
            latestCommandExecution,
            commandJournal,
            providerOwnedControlPlaneOwnership,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneApplyAndReconcileExecution);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ProviderOwnedControlPlaneApplyAndReconcileExecutionState = providerOwnedControlPlaneApplyAndReconcileExecution.State,
            ProviderOwnedControlPlaneProvisioningState = providerOwnedControlPlaneProvisioning.State,
            ProviderOwnedControlPlaneMutationReconcileState = providerOwnedControlPlaneMutationReconcile.State,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            ConnectClusterId = ResolveManagedConnectorCommandTargetValue(
                metadataSnapshot.DeclaredConnectClusterId,
                metadataSnapshot.ReportedConnectClusterId),
            ConnectorClass = ResolveManagedConnectorCommandTargetValue(
                metadataSnapshot.DeclaredConnectorClass,
                metadataSnapshot.ReportedConnectorClass),
            SourceProviderId = ResolveManagedConnectorCommandTargetValue(
                metadataSnapshot.DeclaredSourceProviderId,
                metadataSnapshot.ReportedSourceProviderId),
            DeclaredConnectClusterId = metadataSnapshot.DeclaredConnectClusterId,
            ReportedConnectClusterId = metadataSnapshot.ReportedConnectClusterId,
            DeclaredConnectorClass = metadataSnapshot.DeclaredConnectorClass,
            ReportedConnectorClass = metadataSnapshot.ReportedConnectorClass,
            DeclaredSourceProviderId = metadataSnapshot.DeclaredSourceProviderId,
            ReportedSourceProviderId = metadataSnapshot.ReportedSourceProviderId,
            ExpectedTaskCount = metadataSnapshot.ExpectedTaskCount,
            ReportedTaskCount = metadataSnapshot.ReportedTaskCount,
            DeclaredTaskIds = metadataSnapshot.DeclaredTaskIds,
            ReportedTaskIds = metadataSnapshot.ReportedTaskIds,
            ActiveTaskIds = metadataSnapshot.ActiveTaskIds,
            ReconciliationState = metadataSnapshot.ReconciliationState,
            ReconciliationReason = metadataSnapshot.ReconciliationReason,
            PotentialChangeCount = providerOwnedControlPlaneApplyAndReconcileExecution.PotentialChangeCount,
            LatestAttemptId = latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = latestCommandExecution.RecordedAtUtc,
            ActiveReporterId = summary.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = summary.ReporterLeaseExpiresAtUtc,
            WouldApplyChanges = providerOwnedControlPlaneApplyAndReconcileExecution.WouldApplyChanges,
            RequiresExplicitApproval = providerOwnedControlPlaneApplyAndReconcileExecution.RequiresExplicitApproval,
            IsDestructiveOperation = providerOwnedControlPlaneApplyAndReconcileExecution.IsDestructiveOperation,
            HasTargetOperation = providerOwnedControlPlaneApplyAndReconcileExecution.HasTargetOperation,
            HasDeclaredDependencyIdentity = hasDeclaredDependencyIdentity,
            HasReportedDependencyIdentity = hasReportedDependencyIdentity,
            HasTaskBaseline = hasTaskBaseline,
            HasReportedTaskTopology = hasReportedTaskTopology,
            HasActiveTaskTopology = hasActiveTaskTopology,
            HasDependencyIdentityMismatch = hasDependencyIdentityMismatch,
            HasTaskTopologyMismatch = hasTaskTopologyMismatch,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExecuteDependencyAwareApplyAndReconcileOnCurrentNode = canExecuteDependencyAwareApplyAndReconcileOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity,
        bool hasTaskBaseline,
        bool hasReportedTaskTopology,
        bool hasActiveTaskTopology,
        bool hasReconciliationDegraded,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory,
        bool canExecuteDependencyAwareApplyAndReconcileOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);

        if (!providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector &&
            !governance.AppliesToManagedConnector &&
            !drift.CanEvaluateDrift)
        {
            return [];
        }

        var categories = new List<string>(capacity: 32);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(
            categories,
            CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DependencyReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DependencyBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyDegraded, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DependencyDegraded);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.ApplyAndReconcileHardened, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApplyAndReconcileHardened);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DependencyRisk);
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApplyAndReconcileReady);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApplyAndReconcileBlocked);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApplyAndReconcileExecuting);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApplyAndReconcileCompleted);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApplyAndReconcileRisk);
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.HasTargetOperation)
        {
            AddCategory(
                categories,
                canExecuteDependencyAwareApplyAndReconcileOnCurrentNode
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.CurrentNodeExecutable
                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.CurrentNodeBlocked);
        }

        AddCategory(
            categories,
            providerOwnedControlPlaneApplyAndReconcileExecution.WouldApplyChanges
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.WouldApplyChanges
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.NoChangesRequired);

        if (providerOwnedControlPlaneApplyAndReconcileExecution.RequiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ApprovalRequired);
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.IsDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DestructiveOperation);
        }

        if (hasDeclaredDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DependencyIdentityReady);
        }

        if (hasReportedDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ReportedDependencyIdentityReady);
        }

        foreach (var category in governance.CategoryIds)
        {
            AddCategory(categories, category);
        }

        foreach (var category in drift.CategoryIds)
        {
            AddCategory(categories, category);
        }

        AddCategory(
            categories,
            hasActiveTaskTopology
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ActiveTaskTopology
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.NoActiveTaskTopology);

        AddCategory(
            categories,
            hasReconciliationDegraded
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ReconciliationDegraded
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ReconciliationStable);

        AddCategory(
            categories,
            summary.HasActiveReporterLease && !summary.HasReporterCoordinationIssue && !summary.HasStaleObservations
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ReporterLeaseActive
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ReporterLeaseMissingOrStale);

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.DurableJournalConfigured);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.PersistedHistory);
        }
        else if (!hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.InMemoryJournalOnly);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.RecoveredHistory);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningCategories.ProviderCommandFailed);
        }

        return categories
            .OrderBy(static category => category, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity,
        bool hasTaskBaseline,
        bool hasReportedTaskTopology,
        bool hasActiveTaskTopology,
        bool hasReconciliationDegraded,
        bool hasReporterLeaseIssue,
        string? reconciliationReason)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);

        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                providerOwnedControlPlaneApplyAndReconcileExecution.Description,
                latestCommandExecution.IsUnrecorded ? null : latestCommandExecution.Description,
                reconciliationReason),
            summary.ReporterCoordination.Description,
            commandJournal.Description);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "The execution runtime does not currently represent managed-connector provider-owned control-plane dependency-aware apply-and-reconcile hardening.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can describe dependency-aware provider-owned control-plane apply-and-reconcile hardening for {operationLabel}, but the lane still remains operator-owned outside the engine.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Provider-owned control-plane dependency-aware apply-and-reconcile hardening for {operationLabel} currently remains risky because broader provider or runtime truth is not safe enough yet.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string summaryText;
            if (!hasDeclaredDependencyIdentity)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane apply-and-reconcile for {operationLabel} because declared connector dependency identity is incomplete.";
            }
            else if (!hasTaskBaseline)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane apply-and-reconcile for {operationLabel} because the declared task baseline is missing.";
            }
            else if (!hasReportedTaskTopology)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane apply-and-reconcile for {operationLabel} because reported task topology is still unavailable.";
            }
            else if (!providerOwnedControlPlaneApplyAndReconcileExecution.HasTargetOperation)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane apply-and-reconcile for {operationLabel} because no concrete target operation is selected.";
            }
            else
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane apply-and-reconcile for {operationLabel} because the shared provider lane still remains blocked.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyDegraded, StringComparison.OrdinalIgnoreCase))
        {
            var summaryText =
                !hasReportedDependencyIdentity
                    ? $"Cephalon can stage dependency-aware provider-owned control-plane apply-and-reconcile for {operationLabel}, but reported dependency identity is still incomplete."
                    : !hasActiveTaskTopology
                        ? $"Cephalon can stage dependency-aware provider-owned control-plane apply-and-reconcile for {operationLabel}, but no active task topology is currently reported."
                        : hasReconciliationDegraded
                            ? $"Cephalon can stage dependency-aware provider-owned control-plane apply-and-reconcile for {operationLabel}, but the managed connector currently reports degraded reconciliation truth."
                            : hasReporterLeaseIssue
                                ? $"Cephalon can stage dependency-aware provider-owned control-plane apply-and-reconcile for {operationLabel}, but reporter lease or freshness truth is currently degraded."
                                : $"Cephalon can stage dependency-aware provider-owned control-plane apply-and-reconcile for {operationLabel}, but declared-versus-observed dependency truth is still degraded.";

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.ApplyAndReconcileHardened, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can dependency-harden provider-owned control-plane apply-and-reconcile for {operationLabel} because declared and reported dependency identity, task topology, reporter lease, and command-journal evidence are all present.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStates.DependencyReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can currently stage dependency-aware provider-owned control-plane apply-and-reconcile for {operationLabel} because the shared runtime exposes enough dependency truth, even though full hardening evidence is not complete yet.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon exposes provider-owned control-plane dependency-aware apply-and-reconcile hardening truth for {operationLabel}.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSourceId(
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution)
    {
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);

        if (!latestCommandExecution.IsUnrecorded && latestCommandExecution.IsFailed)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.CommandExecution;
        }

        if (governance.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingConnectClusterId, StringComparer.OrdinalIgnoreCase) ||
            governance.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingConnectorClass, StringComparer.OrdinalIgnoreCase) ||
            governance.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingSourceProviderId, StringComparer.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.ManagedConnectorGovernance;
        }

        if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingTaskBaseline, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskTopologyUnavailable, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskIdentityUnavailable, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.TaskCountMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingDeclaredTaskReports, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.UnexpectedReportedTasks, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.ManagedConnectorDrift;
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.ProviderOwnedControlPlaneApplyAndReconcileExecution;
        }

        if (providerOwnedControlPlaneProvisioning.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.ProviderOwnedControlPlaneProvisioning;
        }

        if (providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.ProviderOwnedControlPlaneMutationReconcile;
        }

        if (providerOwnedControlPlaneOwnership.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.ProviderOwnedControlPlaneOwnership;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.CommandJournal;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.CommandExecution;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string? executionOwnership,
        string? executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStatus providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening,
        ManagedConnectorMetadataSnapshot metadataSnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening);
        ArgumentNullException.ThrowIfNull(metadataSnapshot);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var normalizedOperationId =
            string.IsNullOrWhiteSpace(providerOwnedControlPlaneApplyAndReconcileExecution.OperationId)
                ? string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.OperationId)
                    ? string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.OperationId)
                        ? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None
                        : providerOwnedControlPlaneProvisioning.OperationId.Trim()
                    : providerOwnedControlPlaneMutationReconcile.OperationId.Trim()
                : providerOwnedControlPlaneApplyAndReconcileExecution.OperationId.Trim();
        var appliesToManagedConnector =
            string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
            (providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.AppliesToManagedConnector ||
             providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector ||
             providerOwnedControlPlaneProvisioning.AppliesToManagedConnector ||
             providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector ||
             providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
             providerExecutionOrchestration.AppliesToManagedConnector ||
             providerOwnedWritePathExecution.AppliesToManagedConnector ||
             governance.AppliesToManagedConnector ||
             drift.CanEvaluateDrift);
        var hasDeclaredDependencyIdentity =
            !string.IsNullOrWhiteSpace(metadataSnapshot.DeclaredConnectClusterId) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.DeclaredConnectorClass) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.DeclaredSourceProviderId);
        var hasReportedDependencyIdentity =
            !string.IsNullOrWhiteSpace(metadataSnapshot.ReportedConnectClusterId) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.ReportedConnectorClass) &&
            !string.IsNullOrWhiteSpace(metadataSnapshot.ReportedSourceProviderId);
        var hasTaskBaseline = metadataSnapshot.ExpectedTaskCount.HasValue || metadataSnapshot.DeclaredTaskIds.Length > 0;
        var hasReportedTaskTopology = metadataSnapshot.ReportedTaskCount.HasValue || metadataSnapshot.ReportedTaskIds.Length > 0;
        var hasActiveTaskTopology = metadataSnapshot.ActiveTaskIds.Length > 0;
        var hasDependencyIdentityMismatch =
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase);
        var hasTaskTopologyMismatch =
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.TaskCountMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingDeclaredTaskReports, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.UnexpectedReportedTasks, StringComparer.OrdinalIgnoreCase);
        var hasTaskTopologyGap =
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingTaskBaseline, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskTopologyUnavailable, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskIdentityUnavailable, StringComparer.OrdinalIgnoreCase);
        var hasReconciliationDegraded = !IsManagedConnectorReconciliationStable(metadataSnapshot.ReconciliationState);
        var hasReporterLease = summary.HasActiveReporterLease;
        var hasReporterLeaseIssue = !hasReporterLease || summary.HasReporterCoordinationIssue || summary.HasStaleObservations;
        var hasDurableStoreConfigured =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasDurableStoreConfigured ||
            providerOwnedControlPlaneProvisioning.HasDurableStoreConfigured ||
            providerOwnedControlPlaneMutationReconcile.HasDurableStoreConfigured ||
            providerOwnedControlPlaneOwnership.HasDurableStoreConfigured ||
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneProvisioning.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneOwnership.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneProvisioning.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneOwnership.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.HasRecoveredPersistedHistory;
        var hasTargetOperation =
            providerOwnedControlPlaneApplyAndReconcileExecution.HasTargetOperation ||
            providerOwnedControlPlaneMutationReconcile.HasTargetOperation ||
            providerOwnedControlPlaneProvisioning.HasTargetOperation;
        var isMutationOperation =
            providerOwnedControlPlaneApplyAndReconcileExecution.IsMutationOperation ||
            providerOwnedControlPlaneMutationReconcile.IsMutationOperation;
        var isReconcileOperation =
            providerOwnedControlPlaneApplyAndReconcileExecution.IsReconcileOperation ||
            providerOwnedControlPlaneMutationReconcile.IsReconcileOperation;
        var isProvisioningOperation = !isMutationOperation && !isReconcileOperation;
        var canExecuteDependencyAwareProvisioningOnCurrentNode =
            providerOwnedControlPlaneProvisioning.CanProvisionProviderOwnedControlPlaneOnCurrentNode &&
            hasDeclaredDependencyIdentity &&
            hasTaskBaseline &&
            hasReportedTaskTopology;
        var canExecuteDependencyAwareMutationOnCurrentNode =
            (providerOwnedControlPlaneMutationReconcile.CanMutateOrReconcileOnCurrentNode ||
             providerOwnedControlPlaneApplyAndReconcileExecution.CanExecuteProviderOwnedControlPlaneApplyAndReconcileOnCurrentNode) &&
            hasDeclaredDependencyIdentity &&
            hasTaskBaseline &&
            hasReportedTaskTopology;
        var canExecuteDependencyAwareProvisioningAndMutationOnCurrentNode =
            canExecuteDependencyAwareProvisioningOnCurrentNode ||
            canExecuteDependencyAwareMutationOnCurrentNode;
        var wouldApplyChanges =
            providerOwnedControlPlaneApplyAndReconcileExecution.WouldApplyChanges ||
            providerOwnedControlPlaneProvisioning.WouldApplyChanges ||
            providerOwnedControlPlaneMutationReconcile.WouldApplyChanges;
        var requiresExplicitApproval =
            providerOwnedControlPlaneApplyAndReconcileExecution.RequiresExplicitApproval ||
            providerOwnedControlPlaneProvisioning.RequiresExplicitApproval ||
            providerOwnedControlPlaneMutationReconcile.RequiresExplicitApproval;
        var isDestructiveOperation =
            providerOwnedControlPlaneApplyAndReconcileExecution.IsDestructiveOperation ||
            providerOwnedControlPlaneProvisioning.IsDestructiveOperation ||
            providerOwnedControlPlaneMutationReconcile.IsDestructiveOperation;
        var potentialChangeCount = Math.Max(
            providerOwnedControlPlaneApplyAndReconcileExecution.PotentialChangeCount,
            Math.Max(
                providerOwnedControlPlaneProvisioning.PotentialChangeCount,
                providerOwnedControlPlaneMutationReconcile.PotentialChangeCount));
        var hasDependencyRisk =
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.IsDependencyRisk ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk ||
            providerOwnedControlPlaneProvisioning.IsProvisioningRisk ||
            providerOwnedControlPlaneMutationReconcile.IsMutationRisk ||
            providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
            providerExecutionOrchestration.IsOrchestrationRisk ||
            providerOwnedWritePathExecution.IsProviderOwnedRisk ||
            latestCommandExecution.IsFailed;
        var hasDependencyDegradation =
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.IsDependencyDegraded ||
            hasDependencyIdentityMismatch ||
            hasTaskTopologyMismatch ||
            hasTaskTopologyGap ||
            !hasReportedDependencyIdentity ||
            !hasActiveTaskTopology ||
            hasReconciliationDegraded ||
            hasReporterLeaseIssue ||
            latestCommandExecution.IsBlocked ||
            latestCommandExecution.IsUnavailable;
        var hasCommonHardeningEvidence =
            hasDeclaredDependencyIdentity &&
            hasReportedDependencyIdentity &&
            hasTaskBaseline &&
            hasReportedTaskTopology &&
            hasActiveTaskTopology &&
            !hasDependencyIdentityMismatch &&
            !hasTaskTopologyMismatch &&
            !hasTaskTopologyGap &&
            !hasReconciliationDegraded &&
            !hasReporterLeaseIssue &&
            (hasDurableStoreConfigured || hasPersistedRecordedHistory);
        var hasProvisioningHardenedEvidence =
            hasCommonHardeningEvidence &&
            !providerOwnedControlPlaneProvisioning.IsProvisioningBlocked &&
            (providerOwnedControlPlaneProvisioning.IsProvisioningReady ||
             providerOwnedControlPlaneProvisioning.IsProvisioningExecuting ||
             providerOwnedControlPlaneProvisioning.IsProvisioningPartial ||
             canExecuteDependencyAwareProvisioningOnCurrentNode);
        var hasMutationBlockers =
            !hasDeclaredDependencyIdentity ||
            !hasTaskBaseline ||
            !hasReportedTaskTopology ||
            providerOwnedControlPlaneMutationReconcile.IsMutationBlocked ||
            providerOwnedControlPlaneMutationReconcile.IsReconcileBlocked ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileBlocked ||
            ((isMutationOperation || isReconcileOperation) && !hasTargetOperation);
        var hasMutationHardenedEvidence =
            hasCommonHardeningEvidence &&
            !hasMutationBlockers &&
            (providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
             providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
             providerOwnedControlPlaneMutationReconcile.IsMutationExecuting ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted ||
             canExecuteDependencyAwareMutationOnCurrentNode);
        var hasProvisioningReadyLane =
            canExecuteDependencyAwareProvisioningOnCurrentNode ||
            providerOwnedControlPlaneProvisioning.IsProvisioningReady ||
            providerOwnedControlPlaneProvisioning.IsProvisioningExecuting ||
            providerOwnedControlPlaneProvisioning.IsProvisioningPartial;
        var hasMutationReadyLane =
            canExecuteDependencyAwareMutationOnCurrentNode ||
            providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
            providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
            providerOwnedControlPlaneMutationReconcile.IsMutationExecuting ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted;
        var prefersMutationState =
            isMutationOperation ||
            isReconcileOperation ||
            providerOwnedControlPlaneMutationReconcile.HasTargetOperation ||
            providerOwnedControlPlaneApplyAndReconcileExecution.HasTargetOperation ||
            !providerOwnedControlPlaneProvisioning.AppliesToManagedConnector;
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.NotApplicable
                : providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.IsOperatorOnly ||
                  providerOwnedControlPlaneApplyAndReconcileExecution.IsOperatorOnly ||
                  providerOwnedControlPlaneProvisioning.IsOperatorOnly ||
                  providerOwnedControlPlaneMutationReconcile.IsOperatorOnly ||
                  providerOwnedControlPlaneOwnership.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.OperatorOnly
                    : hasDependencyRisk
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyRisk
                        : prefersMutationState
                            ? hasMutationHardenedEvidence
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.MutationHardened
                                : hasDependencyDegradation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyDegraded
                                    : hasMutationReadyLane
                                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyReady
                                        : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.MutationBlocked
                            : hasProvisioningHardenedEvidence
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.ProvisioningHardened
                                : hasDependencyDegradation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyDegraded
                                    : hasProvisioningReadyLane
                                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyReady
                                        : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.ProvisioningBlocked;
        var categories = CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories(
            state,
            governance,
            drift,
            summary,
            latestCommandExecution,
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneMutationReconcile,
            hasTargetOperation,
            isProvisioningOperation,
            isMutationOperation,
            isReconcileOperation,
            wouldApplyChanges,
            requiresExplicitApproval,
            isDestructiveOperation,
            hasDeclaredDependencyIdentity,
            hasReportedDependencyIdentity,
            hasTaskBaseline,
            hasReportedTaskTopology,
            hasActiveTaskTopology,
            hasReconciliationDegraded,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory,
            canExecuteDependencyAwareProvisioningAndMutationOnCurrentNode,
            canExecuteDependencyAwareProvisioningOnCurrentNode,
            canExecuteDependencyAwareMutationOnCurrentNode);
        var description = CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningDescription(
            state,
            normalizedOperationId,
            summary,
            latestCommandExecution,
            commandJournal,
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneMutationReconcile,
            hasDeclaredDependencyIdentity,
            hasReportedDependencyIdentity,
            hasTaskBaseline,
            hasReportedTaskTopology,
            hasActiveTaskTopology,
            hasReconciliationDegraded,
            hasReporterLeaseIssue,
            metadataSnapshot.ReconciliationReason);
        var sourceId = ResolveManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSourceId(
            governance,
            drift,
            latestCommandExecution,
            commandJournal,
            providerOwnedWritePathExecution,
            providerExecutionOrchestration,
            providerOwnedControlPlaneOwnership,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = normalizedOperationId,
            SourceId = sourceId,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningState = providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.State,
            ProviderOwnedControlPlaneApplyAndReconcileExecutionState = providerOwnedControlPlaneApplyAndReconcileExecution.State,
            ProviderOwnedControlPlaneProvisioningState = providerOwnedControlPlaneProvisioning.State,
            ProviderOwnedControlPlaneMutationReconcileState = providerOwnedControlPlaneMutationReconcile.State,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            ConnectClusterId = ResolveManagedConnectorCommandTargetValue(
                metadataSnapshot.DeclaredConnectClusterId,
                metadataSnapshot.ReportedConnectClusterId),
            ConnectorClass = ResolveManagedConnectorCommandTargetValue(
                metadataSnapshot.DeclaredConnectorClass,
                metadataSnapshot.ReportedConnectorClass),
            SourceProviderId = ResolveManagedConnectorCommandTargetValue(
                metadataSnapshot.DeclaredSourceProviderId,
                metadataSnapshot.ReportedSourceProviderId),
            DeclaredConnectClusterId = metadataSnapshot.DeclaredConnectClusterId,
            ReportedConnectClusterId = metadataSnapshot.ReportedConnectClusterId,
            DeclaredConnectorClass = metadataSnapshot.DeclaredConnectorClass,
            ReportedConnectorClass = metadataSnapshot.ReportedConnectorClass,
            DeclaredSourceProviderId = metadataSnapshot.DeclaredSourceProviderId,
            ReportedSourceProviderId = metadataSnapshot.ReportedSourceProviderId,
            ExpectedTaskCount = metadataSnapshot.ExpectedTaskCount,
            ReportedTaskCount = metadataSnapshot.ReportedTaskCount,
            DeclaredTaskIds = metadataSnapshot.DeclaredTaskIds,
            ReportedTaskIds = metadataSnapshot.ReportedTaskIds,
            ActiveTaskIds = metadataSnapshot.ActiveTaskIds,
            ReconciliationState = metadataSnapshot.ReconciliationState,
            ReconciliationReason = metadataSnapshot.ReconciliationReason,
            PotentialChangeCount = potentialChangeCount,
            LatestAttemptId = latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = latestCommandExecution.RecordedAtUtc,
            ActiveReporterId = summary.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = summary.ReporterLeaseExpiresAtUtc,
            WouldApplyChanges = wouldApplyChanges,
            RequiresExplicitApproval = requiresExplicitApproval,
            IsDestructiveOperation = isDestructiveOperation,
            HasTargetOperation = hasTargetOperation,
            IsProvisioningOperation = isProvisioningOperation,
            IsMutationOperation = isMutationOperation,
            IsReconcileOperation = isReconcileOperation,
            HasDeclaredDependencyIdentity = hasDeclaredDependencyIdentity,
            HasReportedDependencyIdentity = hasReportedDependencyIdentity,
            HasTaskBaseline = hasTaskBaseline,
            HasReportedTaskTopology = hasReportedTaskTopology,
            HasActiveTaskTopology = hasActiveTaskTopology,
            HasDependencyIdentityMismatch = hasDependencyIdentityMismatch,
            HasTaskTopologyMismatch = hasTaskTopologyMismatch,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExecuteDependencyAwareProvisioningAndMutationOnCurrentNode = canExecuteDependencyAwareProvisioningAndMutationOnCurrentNode,
            CanExecuteDependencyAwareProvisioningOnCurrentNode = canExecuteDependencyAwareProvisioningOnCurrentNode,
            CanExecuteDependencyAwareMutationOnCurrentNode = canExecuteDependencyAwareMutationOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories(
        string state,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStatus providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        bool hasTargetOperation,
        bool isProvisioningOperation,
        bool isMutationOperation,
        bool isReconcileOperation,
        bool wouldApplyChanges,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity,
        bool hasTaskBaseline,
        bool hasReportedTaskTopology,
        bool hasActiveTaskTopology,
        bool hasReconciliationDegraded,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory,
        bool canExecuteDependencyAwareProvisioningAndMutationOnCurrentNode,
        bool canExecuteDependencyAwareProvisioningOnCurrentNode,
        bool canExecuteDependencyAwareMutationOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);

        if (!providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.AppliesToManagedConnector &&
            !providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector &&
            !providerOwnedControlPlaneProvisioning.AppliesToManagedConnector &&
            !providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector &&
            !governance.AppliesToManagedConnector &&
            !drift.CanEvaluateDrift)
        {
            return [];
        }

        var categories = new List<string>(capacity: 48);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(
            categories,
            CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.DependencyReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.ProvisioningBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.MutationBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyDegraded, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.DependencyDegraded);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.ProvisioningHardened, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningHardened);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.MutationHardened, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationHardened);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.DependencyRisk);
        }

        if (providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.IsApplyAndReconcileHardened)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApplyAndReconcileHardened);
        }

        if (providerOwnedControlPlaneProvisioning.IsProvisioningReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningReady);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningBlocked);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningExecuting);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningPartial)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningPartial);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProvisioningRisk);
        }

        if (providerOwnedControlPlaneMutationReconcile.IsMutationReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationReady);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsReconcileReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReconcileReady);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationBlocked);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsReconcileBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationBlocked);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationExecuting);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationRisk);
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApplyAndReconcileReady);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApplyAndReconcileBlocked);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApplyAndReconcileExecuting);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApplyAndReconcileCompleted);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApplyAndReconcileRisk);
        }

        if (hasTargetOperation)
        {
            AddCategory(
                categories,
                canExecuteDependencyAwareProvisioningAndMutationOnCurrentNode
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.CurrentNodeExecutable
                    : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.CurrentNodeBlocked);
        }

        AddCategory(
            categories,
            canExecuteDependencyAwareProvisioningOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.CurrentNodeProvisioningExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.CurrentNodeProvisioningBlocked);
        AddCategory(
            categories,
            canExecuteDependencyAwareMutationOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.CurrentNodeMutationExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.CurrentNodeMutationBlocked);

        if (isMutationOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.MutationOperation);
        }
        else if (isReconcileOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReconcileOperation);
        }
        else if (isProvisioningOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.NoTargetOperation);
        }

        AddCategory(
            categories,
            wouldApplyChanges
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.WouldApplyChanges
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.NoChangesRequired);

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.DestructiveOperation);
        }

        if (hasDeclaredDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.DependencyIdentityReady);
        }

        if (hasReportedDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReportedDependencyIdentityReady);
        }

        foreach (var category in governance.CategoryIds)
        {
            AddCategory(categories, category);
        }

        foreach (var category in drift.CategoryIds)
        {
            AddCategory(categories, category);
        }

        AddCategory(
            categories,
            hasActiveTaskTopology
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ActiveTaskTopology
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.NoActiveTaskTopology);
        AddCategory(
            categories,
            hasReconciliationDegraded
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReconciliationDegraded
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReconciliationStable);
        AddCategory(
            categories,
            summary.HasActiveReporterLease && !summary.HasReporterCoordinationIssue && !summary.HasStaleObservations
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReporterLeaseActive
                : CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ReporterLeaseMissingOrStale);

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.DurableJournalConfigured);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.PersistedHistory);
        }
        else if (!hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.InMemoryJournalOnly);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.RecoveredHistory);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningCategories.ProviderCommandFailed);
        }

        return categories
            .OrderBy(static category => category, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string CreateManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningDescription(
        string state,
        string operationId,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStatus providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity,
        bool hasTaskBaseline,
        bool hasReportedTaskTopology,
        bool hasActiveTaskTopology,
        bool hasReconciliationDegraded,
        bool hasReporterLeaseIssue,
        string? reconciliationReason)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);

        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                CombineManagedConnectorCommandEnvelopeDetail(
                    providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.Description,
                    providerOwnedControlPlaneProvisioning.Description,
                    providerOwnedControlPlaneMutationReconcile.Description),
                providerOwnedControlPlaneApplyAndReconcileExecution.Description,
                latestCommandExecution.IsUnrecorded ? null : latestCommandExecution.Description),
            CombineManagedConnectorCommandEnvelopeDetail(
                summary.ReporterCoordination.Description,
                commandJournal.Description,
                reconciliationReason));

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "The execution runtime does not currently represent managed-connector provider-owned control-plane dependency-aware provisioning and mutation hardening.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can describe dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel}, but the lane still remains operator-owned outside the engine.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Provider-owned control-plane dependency-aware provisioning and mutation hardening for {operationLabel} currently remains risky because broader provider or runtime truth is not safe enough yet.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.ProvisioningBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string summaryText;
            if (!hasDeclaredDependencyIdentity)
            {
                summaryText = "Cephalon cannot yet dependency-harden provider-owned control-plane provisioning because declared connector dependency identity is incomplete.";
            }
            else if (!hasTaskBaseline)
            {
                summaryText = "Cephalon cannot yet dependency-harden provider-owned control-plane provisioning because the declared task baseline is missing.";
            }
            else if (!hasReportedTaskTopology)
            {
                summaryText = "Cephalon cannot yet dependency-harden provider-owned control-plane provisioning because reported task topology is still unavailable.";
            }
            else
            {
                summaryText = "Cephalon cannot yet dependency-harden provider-owned control-plane provisioning because the shared provider provisioning lane still remains blocked.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.MutationBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string summaryText;
            if (!hasDeclaredDependencyIdentity)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane mutation for {operationLabel} because declared connector dependency identity is incomplete.";
            }
            else if (!hasTaskBaseline)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane mutation for {operationLabel} because the declared task baseline is missing.";
            }
            else if (!hasReportedTaskTopology)
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane mutation for {operationLabel} because reported task topology is still unavailable.";
            }
            else
            {
                summaryText = $"Cephalon cannot yet dependency-harden provider-owned control-plane mutation for {operationLabel} because the shared mutation or apply-and-reconcile lane still remains blocked.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyDegraded, StringComparison.OrdinalIgnoreCase))
        {
            var summaryText =
                !hasReportedDependencyIdentity
                    ? $"Cephalon can stage dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel}, but reported dependency identity is still incomplete."
                    : !hasActiveTaskTopology
                        ? $"Cephalon can stage dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel}, but no active task topology is currently reported."
                        : hasReconciliationDegraded
                            ? $"Cephalon can stage dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel}, but the managed connector currently reports degraded reconciliation truth."
                            : hasReporterLeaseIssue
                                ? $"Cephalon can stage dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel}, but reporter lease or freshness truth is currently degraded."
                                : $"Cephalon can stage dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel}, but declared-versus-observed dependency truth is still degraded.";

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.ProvisioningHardened, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "Cephalon can dependency-harden provider-owned control-plane provisioning because declared and reported dependency identity, task topology, reporter lease, and command-journal evidence are all present.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.MutationHardened, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can dependency-harden provider-owned control-plane mutation for {operationLabel} because declared and reported dependency identity, task topology, reporter lease, and command-journal evidence are all present.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStates.DependencyReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can currently stage dependency-aware provider-owned control-plane provisioning and mutation hardening for {operationLabel} because the shared runtime exposes enough dependency truth, even though full hardening evidence is not complete yet.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon exposes provider-owned control-plane dependency-aware provisioning and mutation hardening truth for {operationLabel}.",
            detail);
    }

    private static string ResolveManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSourceId(
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardeningStatus providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening)
    {
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening);

        if (!latestCommandExecution.IsUnrecorded && latestCommandExecution.IsFailed)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.CommandExecution;
        }

        if (governance.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingConnectClusterId, StringComparer.OrdinalIgnoreCase) ||
            governance.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingConnectorClass, StringComparer.OrdinalIgnoreCase) ||
            governance.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingSourceProviderId, StringComparer.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ManagedConnectorGovernance;
        }

        if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingTaskBaseline, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskTopologyUnavailable, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ReportedTaskIdentityUnavailable, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.TaskCountMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingDeclaredTaskReports, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.UnexpectedReportedTasks, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase) ||
            drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ManagedConnectorDrift;
        }

        if (providerOwnedControlPlaneDependencyAwareApplyAndReconcileHardening.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderOwnedControlPlaneDependencyAwareApplyAndReconcileHardening;
        }

        if (providerOwnedControlPlaneProvisioning.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderOwnedControlPlaneProvisioning;
        }

        if (providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderOwnedControlPlaneMutationReconcile;
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderOwnedControlPlaneApplyAndReconcileExecution;
        }

        if (providerOwnedControlPlaneOwnership.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderOwnedControlPlaneOwnership;
        }

        if (providerExecutionOrchestration.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderExecutionOrchestration;
        }

        if (providerOwnedWritePathExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.ProviderOwnedWritePathExecution;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.CommandJournal;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.CommandExecution;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningSources.Unknown;
    }

    private static bool IsManagedConnectorReconciliationStable(string? reconciliationState)
    {
        if (string.IsNullOrWhiteSpace(reconciliationState))
        {
            return true;
        }

        return string.Equals(reconciliationState, "current", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reconciliationState, "aligned", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reconciliationState, "in-sync", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reconciliationState, "stable", StringComparison.OrdinalIgnoreCase);
    }

    private static string CreateManagedConnectorBlockedAutomaticRetryExecutionDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal)
    {
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);

        string summary;
        if (retryExecutionPolicy.IsCooldown)
        {
            summary = retryExecutionPolicy.CooldownUntilUtc.HasValue
                ? $"Cephalon is holding automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} until the cooldown window ends at '{retryExecutionPolicy.CooldownUntilUtc.Value:O}'."
                : $"Cephalon is holding automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} while the current cooldown window remains active.";
        }
        else if (retryExecutionPolicy.RequiresManualApproval)
        {
            summary = $"Cephalon can evaluate automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but manual approval must clear before it should continue.";
        }
        else if (retryExecutionPolicy.IsOperatorOnly)
        {
            summary = $"Cephalon can observe retry posture for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)}, but automatic background retry remains operator-owned until a later managed control-plane slice ships.";
        }
        else if (retryExecutionPolicy.IsNotNeeded)
        {
            summary = $"Cephalon does not currently need an automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the shared runtime truth already converged.";
        }
        else
        {
            summary = $"Cephalon is not currently able to continue automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} because the shared runtime truth still blocks it.";
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(retryExecutionPolicy.Description, commandJournal.Description));
    }

    private static string CreateManagedConnectorCompletedAutomaticRetryExecutionDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult? latestAutomaticExecution,
        string? retryExecutionPolicyDescription,
        string? commandJournalDescription)
    {
        string summary;
        if (latestAutomaticExecution is null)
        {
            summary = $"Cephalon already recorded one automatic background retry attempt for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared command lane.";
        }
        else
        {
            var attemptId = NormalizeManagedConnectorFingerprintSegment(latestAutomaticExecution.AttemptId);
            summary = latestAutomaticExecution.State switch
            {
                CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.NoOp =>
                    $"Cephalon already ran one automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} and recorded attempt '{attemptId}' as a no-op because no provider command is needed right now.",
                CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Adapted =>
                    $"Cephalon already ran one automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} and translated provider command shape during attempt '{attemptId}'.",
                CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Blocked =>
                    $"Cephalon already ran one automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} but attempt '{attemptId}' remained blocked by the current provider translation truth.",
                CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Unavailable =>
                    $"Cephalon already ran one automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} but attempt '{attemptId}' could not resolve a provider execution adapter.",
                CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionStates.Failed =>
                    $"Cephalon already ran one automatic background retry for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} but attempt '{attemptId}' failed while translating the provider command.",
                _ =>
                    $"Cephalon already recorded one automatic background retry attempt '{attemptId}' for {CreateManagedConnectorExecutionAdapterOperationLabel(operationId)} on the shared command lane."
            };
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            summary,
            CombineManagedConnectorCommandEnvelopeDetail(latestAutomaticExecution?.Description, retryExecutionPolicyDescription, commandJournalDescription));
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus CreateManagedConnectorExecutionAdapterStatus(
        string state,
        string description,
        IReadOnlyList<string> categoryIds,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        string sourceId,
        string adapterId,
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        ManagedConnectorMetadataSnapshot metadataSnapshot)
    {
        var normalizedOperationId = string.IsNullOrWhiteSpace(operationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None
            : operationId.Trim();
        var normalizedAdapterId = string.IsNullOrWhiteSpace(adapterId)
            ? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterIds.None
            : adapterId.Trim();
        var connectClusterId = commandIssuance.ConnectClusterId ?? ResolveManagedConnectorCommandTargetValue(
            metadataSnapshot.DeclaredConnectClusterId,
            metadataSnapshot.ReportedConnectClusterId);
        var connectorClass = commandIssuance.ConnectorClass ?? ResolveManagedConnectorCommandTargetValue(
            metadataSnapshot.DeclaredConnectorClass,
            metadataSnapshot.ReportedConnectorClass);
        var sourceProviderId = commandIssuance.SourceProviderId ?? ResolveManagedConnectorCommandTargetValue(
            metadataSnapshot.DeclaredSourceProviderId,
            metadataSnapshot.ReportedSourceProviderId);

        return new CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus(state, description)
        {
            CategoryIds = categoryIds,
            OperationId = normalizedOperationId,
            ManagementMode = governance.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            DryRunState = dryRun.State,
            ExecutionIntentState = executionIntent.State,
            ExecutionApprovalState = executionApproval.State,
            CommandEnvelopeState = commandEnvelope.State,
            CommandIssuanceState = commandIssuance.State,
            PrimaryActionId = actionPlan.PrimaryActionId,
            SourceId = sourceId,
            CommandIssuanceSourceId = commandIssuance.SourceId,
            CommandEnvelopeSourceId = commandEnvelope.SourceId,
            ExecutionIntentConfidenceSourceId = executionIntent.ConfidenceSourceId,
            ExecutionApprovalSourceId = executionApproval.SourceId,
            AdapterId = normalizedAdapterId,
            PotentialChangeCount = commandIssuance.PotentialChangeCount,
            WouldApplyChanges = commandIssuance.WouldApplyChanges,
            RequiresExplicitApproval = commandIssuance.RequiresExplicitApproval,
            IsDestructiveOperation = commandIssuance.IsDestructiveOperation,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ConnectClusterId = connectClusterId,
            ConnectorClass = connectorClass,
            SourceProviderId = sourceProviderId,
            CommandFingerprint = commandIssuance.CommandFingerprint,
            IssuanceFingerprint = commandIssuance.IssuanceFingerprint,
            AdapterFingerprint = CreateManagedConnectorExecutionAdapterFingerprint(
                state,
                normalizedOperationId,
                sourceId,
                normalizedAdapterId,
                commandIssuance.State,
                commandEnvelope.State,
                executionApproval.State,
                executionIntent.State,
                commandIssuance.CommandFingerprint,
                commandIssuance.IssuanceFingerprint,
                commandIssuance.RequiresExplicitApproval,
                commandIssuance.WouldApplyChanges,
                commandIssuance.IsDestructiveOperation)
        };
    }

    private static string[] CreateManagedConnectorExecutionAdapterCategories(
        string executionTopology,
        string state,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus dryRun,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        string operationId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(writePathReadiness);
        ArgumentNullException.ThrowIfNull(preflight);
        ArgumentNullException.ThrowIfNull(dryRun);
        ArgumentNullException.ThrowIfNull(executionIntent);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(commandIssuance);

        if (!string.Equals(executionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase))
        {
            return [];
        }

        var categories = new List<string>(capacity: 18);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        if (!commandIssuance.AppliesToManagedConnector || executionIntent.IsDeferred)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.ObserveOnlyMode);
        }

        if (remediation.IsBlocked ||
            commandIssuance.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.BlockingRemediation,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.BlockingRemediation);
        }

        if (commandIssuance.CategoryIds.Contains(
            CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.StaleObservation,
            StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.StaleObservation);
        }

        if (!reportingCoverage.HasFullCoverage ||
            commandIssuance.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.IncompleteReportingCoverage,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.IncompleteReportingCoverage);
        }

        if (actionPlan.IsWaiting ||
            commandIssuance.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase) ||
            preflight.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorPreflightCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase) ||
            writePathReadiness.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessCategories.RuntimeTruthIncomplete,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.RuntimeTruthIncomplete);
        }

        if (governance.IsOutOfPolicy)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.GovernanceOutOfPolicy);
        }

        if (commandIssuance.IsOperatorOnly)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.ControlPlaneOwnershipGap);
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.OperatorOnly);
        }

        if (commandIssuance.WouldApplyChanges || dryRun.WouldApplyChanges)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.ChangePlanned);
        }

        if (WouldManagedConnectorDryRunRequireLifecycleChange(operationId, commandIssuance.WouldApplyChanges || dryRun.WouldApplyChanges))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.LifecycleChange);
        }

        if (commandIssuance.IsDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.DestructiveOperation);
        }

        if (executionApproval.IsApprovalRequired)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.ApprovalRequired);
        }
        else if (executionApproval.IsApprovalReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.ApprovalReady);
        }

        if (commandIssuance.IsRejected ||
            commandIssuance.CategoryIds.Contains(
                CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceCategories.NoExecutionNeeded,
                StringComparer.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.NoExecutionNeeded);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.Ready, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.AdapterReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStates.Unavailable, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterCategories.AdapterUnavailable);
        }

        return [.. categories];
    }

    private static string ResolveManagedConnectorExecutionAdapterSource(
        CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStatus commandIssuance,
        CdcCaptureExecutionRuntimeManagedConnectorCommandEnvelopeStatus commandEnvelope,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionApprovalStatus executionApproval,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionIntentStatus executionIntent)
    {
        ArgumentNullException.ThrowIfNull(commandIssuance);
        ArgumentNullException.ThrowIfNull(commandEnvelope);
        ArgumentNullException.ThrowIfNull(executionApproval);
        ArgumentNullException.ThrowIfNull(executionIntent);

        if (commandIssuance.AppliesToManagedConnector ||
            string.Equals(
                commandIssuance.State,
                CdcCaptureExecutionRuntimeManagedConnectorCommandIssuanceStates.NotApplicable,
                StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterSources.CommandIssuance;
        }

        if (commandEnvelope.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterSources.CommandEnvelope;
        }

        if (executionApproval.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterSources.ExecutionApproval;
        }

        if (executionIntent.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterSources.ExecutionIntent;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterSources.Unknown;
    }

    private static string ResolveManagedConnectorExecutionAdapterOperationId(
        string? commandIssuanceOperationId,
        string? commandEnvelopeOperationId,
        string? executionApprovalOperationId,
        string? executionIntentOperationId)
    {
        if (!string.IsNullOrWhiteSpace(commandIssuanceOperationId))
        {
            return commandIssuanceOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(commandEnvelopeOperationId))
        {
            return commandEnvelopeOperationId.Trim();
        }

        if (!string.IsNullOrWhiteSpace(executionApprovalOperationId))
        {
            return executionApprovalOperationId.Trim();
        }

        return string.IsNullOrWhiteSpace(executionIntentOperationId)
            ? CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None
            : executionIntentOperationId.Trim();
    }

    private static string CreateManagedConnectorExecutionAdapterFingerprint(
        string state,
        string operationId,
        string sourceId,
        string adapterId,
        string commandIssuanceState,
        string commandEnvelopeState,
        string executionApprovalState,
        string executionIntentState,
        string commandFingerprint,
        string issuanceFingerprint,
        bool requiresExplicitApproval,
        bool wouldApplyChanges,
        bool isDestructiveOperation)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        ArgumentException.ThrowIfNullOrWhiteSpace(sourceId);
        ArgumentException.ThrowIfNullOrWhiteSpace(adapterId);
        ArgumentException.ThrowIfNullOrWhiteSpace(commandIssuanceState);
        ArgumentException.ThrowIfNullOrWhiteSpace(commandEnvelopeState);
        ArgumentException.ThrowIfNullOrWhiteSpace(executionApprovalState);
        ArgumentException.ThrowIfNullOrWhiteSpace(executionIntentState);
        ArgumentException.ThrowIfNullOrWhiteSpace(commandFingerprint);
        ArgumentException.ThrowIfNullOrWhiteSpace(issuanceFingerprint);

        return string.Join(
            "|",
            [
                "cephalon-managed-connector-execution-adapter/v1",
                $"state={state.Trim()}",
                $"operation={operationId.Trim()}",
                $"source={sourceId.Trim()}",
                $"adapter={adapterId.Trim()}",
                $"commandIssuance={commandIssuanceState.Trim()}",
                $"commandEnvelope={commandEnvelopeState.Trim()}",
                $"executionApproval={executionApprovalState.Trim()}",
                $"executionIntent={executionIntentState.Trim()}",
                $"commandFingerprint={commandFingerprint.Trim()}",
                $"issuanceFingerprint={issuanceFingerprint.Trim()}",
                $"requiresExplicitApproval={requiresExplicitApproval.ToString().ToLowerInvariant()}",
                $"wouldApplyChanges={wouldApplyChanges.ToString().ToLowerInvariant()}",
                $"destructive={isDestructiveOperation.ToString().ToLowerInvariant()}"
            ]);
    }

