    private static string CreateManagedConnectorPreflightOperationLabel(string operationId)
    {
        if (string.Equals(
            operationId,
            CdcCaptureExecutionRuntimeManagedConnectorPreflightOperationIds.Reconcile,
            StringComparison.OrdinalIgnoreCase))
        {
            return "future reconcile follow-through";
        }

        if (string.Equals(
            operationId,
            CdcCaptureExecutionRuntimeManagedConnectorPreflightOperationIds.Pause,
            StringComparison.OrdinalIgnoreCase))
        {
            return "future pause follow-through";
        }

        if (string.Equals(
            operationId,
            CdcCaptureExecutionRuntimeManagedConnectorPreflightOperationIds.Resume,
            StringComparison.OrdinalIgnoreCase))
        {
            return "future resume follow-through";
        }

        if (string.Equals(
            operationId,
            CdcCaptureExecutionRuntimeManagedConnectorPreflightOperationIds.Restart,
            StringComparison.OrdinalIgnoreCase))
        {
            return "future restart follow-through";
        }

        if (string.Equals(
            operationId,
            CdcCaptureExecutionRuntimeManagedConnectorPreflightOperationIds.Delete,
            StringComparison.OrdinalIgnoreCase))
        {
            return "future delete follow-through";
        }

        return "future managed-connector follow-through";
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus CreateManagedConnectorDryRunStatus(
        string state,
        string description,
        IReadOnlyList<string> categoryIds,
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorWritePathReadinessStatus writePathReadiness,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        int potentialChangeCount,
        bool wouldApplyChanges)
    {
        return new CdcCaptureExecutionRuntimeManagedConnectorDryRunStatus(state, description)
        {
            CategoryIds = categoryIds,
            OperationId = operationId,
            ManagementMode = governance.ManagementMode,
            ReportingCoverageState = reportingCoverage.State,
            RemediationState = remediation.State,
            GovernanceState = governance.State,
            DriftState = drift.State,
            ActionPlanState = actionPlan.State,
            WritePathReadinessState = writePathReadiness.State,
            PreflightState = preflight.State,
            PrimaryActionId = actionPlan.PrimaryActionId,
            ConnectorLifecycleState = drift.ConnectorLifecycleState,
            ReconciliationState = drift.ReconciliationState,
            MissingDeclaredTaskIds = drift.MissingDeclaredTaskIds,
            UnexpectedReportedTaskIds = drift.UnexpectedReportedTaskIds,
            PotentialChangeCount = potentialChangeCount,
            WouldApplyChanges = wouldApplyChanges
        };
    }

    private static string[] CreateManagedConnectorDryRunCategories(
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        CdcCaptureExecutionRuntimeRemediationStatus remediation,
        CdcCaptureExecutionRuntimeManagedConnectorGovernanceStatus governance,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeManagedConnectorActionPlanStatus actionPlan,
        CdcCaptureExecutionRuntimeManagedConnectorPreflightStatus preflight,
        string operationId,
        bool wouldApplyChanges)
    {
        ArgumentNullException.ThrowIfNull(reportingCoverage);
        ArgumentNullException.ThrowIfNull(remediation);
        ArgumentNullException.ThrowIfNull(governance);
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(actionPlan);
        ArgumentNullException.ThrowIfNull(preflight);

        var categories = new List<string>(capacity: 10);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        var hasRuntimeRemediationAttention =
            remediation.CategoryIds.Contains(CdcCaptureExecutionRuntimeRemediationCategories.StaleObservations, StringComparer.OrdinalIgnoreCase) ||
            remediation.CategoryIds.Contains(CdcCaptureExecutionRuntimeRemediationCategories.ReporterCoordinationIssues, StringComparer.OrdinalIgnoreCase);
        var isRuntimeTruthIncomplete =
            actionPlan.IsWaiting ||
            string.Equals(drift.State, CdcCaptureExecutionRuntimeManagedConnectorDriftStates.Unknown, StringComparison.OrdinalIgnoreCase);

        if (remediation.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.BlockingRemediation);
        }
        else if (hasRuntimeRemediationAttention)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.RuntimeRemediation);
        }

        if (!reportingCoverage.HasFullCoverage)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.IncompleteReportingCoverage);
        }

        if (governance.IsOutOfPolicy)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.GovernanceOutOfPolicy);
        }

        if (isRuntimeTruthIncomplete)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.RuntimeTruthIncomplete);
        }

        if (preflight.IsDeferred)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.ObserveOnlyMode);
        }

        if (wouldApplyChanges)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.ChangePlanned);
        }
        else if (!preflight.IsDeferred && !preflight.RequiresAttention)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.NoChangesRequired);
        }

        if (WouldManagedConnectorDryRunRequireLifecycleChange(operationId, wouldApplyChanges))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.LifecycleChange);
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase))
        {
            if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase))
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.ConnectClusterChange);
            }

            if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase))
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.ConnectorClassChange);
            }

            if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase))
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.SourceProviderChange);
            }

            if (HasManagedConnectorTaskTopologyDrift(drift))
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorDryRunCategories.TaskTopologyChange);
            }
        }

        return [.. categories];
    }

    private static string ResolveManagedConnectorDryRunOperationId(string? managementMode)
    {
        if (string.IsNullOrWhiteSpace(managementMode))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.None;
        }

        var normalizedManagementMode = managementMode.Trim();
        if (string.Equals(normalizedManagementMode, "observe-only", StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.None;
        }

        if (string.Equals(normalizedManagementMode, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Pause, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Pause;
        }

        if (string.Equals(normalizedManagementMode, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Resume, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Resume;
        }

        if (string.Equals(normalizedManagementMode, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Restart, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Restart;
        }

        if (string.Equals(normalizedManagementMode, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Delete, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Delete;
        }

        return CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile;
    }

    private static bool WouldManagedConnectorDryRunApplyChanges(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage)
    {
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(reportingCoverage);

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.None, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase))
        {
            return drift.IsDrifted;
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Pause, StringComparison.OrdinalIgnoreCase))
        {
            return !string.Equals(drift.ConnectorLifecycleState, "paused", StringComparison.OrdinalIgnoreCase);
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Resume, StringComparison.OrdinalIgnoreCase))
        {
            return string.Equals(drift.ConnectorLifecycleState, "paused", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(drift.ConnectorLifecycleState, "inactive", StringComparison.OrdinalIgnoreCase);
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Restart, StringComparison.OrdinalIgnoreCase))
        {
            return !string.Equals(drift.ConnectorLifecycleState, "restarting", StringComparison.OrdinalIgnoreCase);
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Delete, StringComparison.OrdinalIgnoreCase))
        {
            return !string.IsNullOrWhiteSpace(drift.ConnectorLifecycleState) || reportingCoverage.ReportedCaptureCount > 0;
        }

        return true;
    }

    private static bool WouldManagedConnectorDryRunRequireLifecycleChange(string operationId, bool wouldApplyChanges)
    {
        if (!wouldApplyChanges)
        {
            return false;
        }

        return !string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.None, StringComparison.OrdinalIgnoreCase) &&
               !string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase);
    }

    private static bool HasManagedConnectorTaskTopologyDrift(CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift)
    {
        ArgumentNullException.ThrowIfNull(drift);

        return drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingDeclaredTaskReports, StringComparer.OrdinalIgnoreCase) ||
               drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.UnexpectedReportedTasks, StringComparer.OrdinalIgnoreCase) ||
               drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.TaskCountMismatch, StringComparer.OrdinalIgnoreCase);
    }

    private static int CountManagedConnectorDryRunPotentialChanges(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage,
        bool wouldApplyChanges)
    {
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(reportingCoverage);

        if (!wouldApplyChanges)
        {
            return 0;
        }

        if (!string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase))
        {
            return 1;
        }

        var count = 0;
        if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase))
        {
            count++;
        }

        if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase))
        {
            count++;
        }

        if (drift.CategoryIds.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase))
        {
            count++;
        }

        if (HasManagedConnectorTaskTopologyDrift(drift))
        {
            count++;
        }

        return Math.Max(count, 1);
    }

    private static string CreateManagedConnectorDeferredDryRunDescription(string? governanceDescription)
    {
        return AppendManagedConnectorDryRunDetail(
            "The managed connector remains healthy on the shared runtime surface, but dry-run write-path previews stay deferred while it remains observe-only.",
            governanceDescription);
    }

    private static string CreateManagedConnectorBlockedDryRunDescription(
        string? preflightDescription,
        string operationId,
        bool wouldApplyChanges,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage)
    {
        string? changeDetail = null;
        var summary = wouldApplyChanges
            ? $"Cephalon cannot trust a dry-run answer for {CreateManagedConnectorDryRunOperationLabel(operationId)} yet, but current runtime truth still suggests that operation would change the managed connector once blockers clear."
            : $"Cephalon cannot trust a dry-run answer for {CreateManagedConnectorDryRunOperationLabel(operationId)} yet because the managed connector has not satisfied shared preflight requirements.";
        var detail = wouldApplyChanges
            ? changeDetail = CreateManagedConnectorDryRunChangeDetail(operationId, drift, reportingCoverage)
            : preflightDescription;

        if (wouldApplyChanges && !string.IsNullOrWhiteSpace(preflightDescription))
        {
            detail = $"{preflightDescription.Trim()} {changeDetail!.Trim()}";
        }

        return AppendManagedConnectorDryRunDetail(summary, detail);
    }

    private static string CreateManagedConnectorWouldChangeDryRunDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage)
    {
        return AppendManagedConnectorDryRunDetail(
            $"If Cephalon executed {CreateManagedConnectorDryRunOperationLabel(operationId)} now, the shared runtime truth suggests it would change the managed connector.",
            CreateManagedConnectorDryRunChangeDetail(operationId, drift, reportingCoverage));
    }

    private static string CreateManagedConnectorNoOpDryRunDescription(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage)
    {
        return AppendManagedConnectorDryRunDetail(
            $"If Cephalon executed {CreateManagedConnectorDryRunOperationLabel(operationId)} now, the shared runtime truth suggests no managed-connector changes would be required.",
            CreateManagedConnectorDryRunNoOpDetail(operationId, drift, reportingCoverage));
    }

    private static string CreateManagedConnectorDryRunChangeDetail(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage)
    {
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(reportingCoverage);

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase))
        {
            return string.IsNullOrWhiteSpace(drift.Description)
                ? "The managed connector currently reports declared-versus-observed drift against its shared baseline."
                : drift.Description.Trim();
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Pause, StringComparison.OrdinalIgnoreCase))
        {
            return string.IsNullOrWhiteSpace(drift.ConnectorLifecycleState)
                ? "The managed connector does not currently report a paused lifecycle posture."
                : $"The managed connector currently reports lifecycle state '{drift.ConnectorLifecycleState}', so a pause operation would still change runtime posture.";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Resume, StringComparison.OrdinalIgnoreCase))
        {
            return string.IsNullOrWhiteSpace(drift.ConnectorLifecycleState)
                ? "The managed connector currently does not report an active lifecycle posture."
                : $"The managed connector currently reports lifecycle state '{drift.ConnectorLifecycleState}', so a resume operation would still change runtime posture.";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Restart, StringComparison.OrdinalIgnoreCase))
        {
            return string.IsNullOrWhiteSpace(drift.ConnectorLifecycleState)
                ? "The managed connector currently does not report a restarting lifecycle posture."
                : $"The managed connector currently reports lifecycle state '{drift.ConnectorLifecycleState}', so a restart operation would still change runtime posture.";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Delete, StringComparison.OrdinalIgnoreCase))
        {
            return reportingCoverage.ReportedCaptureCount > 0 || !string.IsNullOrWhiteSpace(drift.ConnectorLifecycleState)
                ? "The managed connector currently reports live runtime presence on the shared surface, so a delete operation would still change runtime posture."
                : "The managed connector would still be treated as a live managed-connector declaration until delete follow-through completes.";
        }

        return "The managed connector currently reports potential write-path changes on the shared surface.";
    }

    private static string CreateManagedConnectorDryRunNoOpDetail(
        string operationId,
        CdcCaptureExecutionRuntimeManagedConnectorDriftStatus drift,
        CdcCaptureExecutionRuntimeReportingCoverageStatus reportingCoverage)
    {
        ArgumentNullException.ThrowIfNull(drift);
        ArgumentNullException.ThrowIfNull(reportingCoverage);

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase))
        {
            return string.IsNullOrWhiteSpace(drift.Description)
                ? "The managed connector currently reports no declared-versus-observed drift."
                : drift.Description.Trim();
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Pause, StringComparison.OrdinalIgnoreCase))
        {
            return "The managed connector already reports a paused lifecycle posture.";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Resume, StringComparison.OrdinalIgnoreCase))
        {
            return "The managed connector already reports an active lifecycle posture.";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Restart, StringComparison.OrdinalIgnoreCase))
        {
            return "The managed connector already reports a restarting lifecycle posture.";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Delete, StringComparison.OrdinalIgnoreCase))
        {
            return reportingCoverage.ReportedCaptureCount == 0 && string.IsNullOrWhiteSpace(drift.ConnectorLifecycleState)
                ? "The shared runtime surface does not currently report live connector presence."
                : "The shared runtime surface already reflects the requested delete posture.";
        }

        return "The managed connector currently reports no shared write-path changes for the intended operation.";
    }

    private static string AppendManagedConnectorDryRunDetail(
        string summary,
        string? detail)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(summary);

        return string.IsNullOrWhiteSpace(detail)
            ? summary.Trim()
            : $"{summary.Trim()} {detail.Trim()}";
    }

    private static string CreateManagedConnectorDryRunOperationLabel(string operationId)
    {
        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Reconcile, StringComparison.OrdinalIgnoreCase))
        {
            return "reconcile the managed connector";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Pause, StringComparison.OrdinalIgnoreCase))
        {
            return "pause the managed connector";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Resume, StringComparison.OrdinalIgnoreCase))
        {
            return "resume the managed connector";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Restart, StringComparison.OrdinalIgnoreCase))
        {
            return "restart the managed connector";
        }

        if (string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorDryRunOperationIds.Delete, StringComparison.OrdinalIgnoreCase))
        {
            return "delete the managed connector";
        }

        return "change the managed connector";
    }

    private static string CreateManagedConnectorInSyncDescription(string? reconciliationState)
    {
        if (string.IsNullOrWhiteSpace(reconciliationState) ||
            string.Equals(reconciliationState, "current", StringComparison.OrdinalIgnoreCase))
        {
            return "The managed connector currently reports no declared-versus-observed drift.";
        }

        return $"The managed connector currently reports no declared-versus-observed drift. Last reported reconciliation state '{reconciliationState}'.";
    }

    private static string CreateManagedConnectorDriftDescription(
        IReadOnlyCollection<string> categories,
        ManagedConnectorMetadataSnapshot snapshot,
        string[] missingDeclaredTaskIds,
        string[] unexpectedReportedTaskIds)
    {
        ArgumentNullException.ThrowIfNull(categories);
        ArgumentNullException.ThrowIfNull(snapshot);

        var messages = new List<string>(capacity: 6);

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.TaskCountMismatch, StringComparer.OrdinalIgnoreCase) &&
            snapshot.ExpectedTaskCount.HasValue &&
            snapshot.ReportedTaskCount.HasValue)
        {
            messages.Add($"Declared task count '{snapshot.ExpectedTaskCount.Value}' but last reported '{snapshot.ReportedTaskCount.Value}'.");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.MissingDeclaredTaskReports, StringComparer.OrdinalIgnoreCase) &&
            missingDeclaredTaskIds.Length > 0)
        {
            messages.Add(missingDeclaredTaskIds.Length == 1
                ? $"Declared task '{missingDeclaredTaskIds[0]}' was not reported."
                : $"Declared tasks '{string.Join(",", missingDeclaredTaskIds)}' were not reported.");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.UnexpectedReportedTasks, StringComparer.OrdinalIgnoreCase) &&
            unexpectedReportedTaskIds.Length > 0)
        {
            messages.Add(unexpectedReportedTaskIds.Length == 1
                ? $"Reported task '{unexpectedReportedTaskIds[0]}' was not declared."
                : $"Reported tasks '{string.Join(",", unexpectedReportedTaskIds)}' were not declared.");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectClusterMismatch, StringComparer.OrdinalIgnoreCase) &&
            !string.IsNullOrWhiteSpace(snapshot.DeclaredConnectClusterId) &&
            !string.IsNullOrWhiteSpace(snapshot.ReportedConnectClusterId))
        {
            messages.Add($"Declared connector cluster '{snapshot.DeclaredConnectClusterId}' but last reported '{snapshot.ReportedConnectClusterId}'.");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.ConnectorClassMismatch, StringComparer.OrdinalIgnoreCase) &&
            !string.IsNullOrWhiteSpace(snapshot.DeclaredConnectorClass) &&
            !string.IsNullOrWhiteSpace(snapshot.ReportedConnectorClass))
        {
            messages.Add($"Declared connector class '{snapshot.DeclaredConnectorClass}' but last reported '{snapshot.ReportedConnectorClass}'.");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorDriftCategories.SourceProviderMismatch, StringComparer.OrdinalIgnoreCase) &&
            !string.IsNullOrWhiteSpace(snapshot.DeclaredSourceProviderId) &&
            !string.IsNullOrWhiteSpace(snapshot.ReportedSourceProviderId))
        {
            messages.Add($"Declared source provider '{snapshot.DeclaredSourceProviderId}' but last reported '{snapshot.ReportedSourceProviderId}'.");
        }

        return messages.Count == 0
            ? "The managed connector currently reports declared-versus-observed drift."
            : string.Join(" ", messages);
    }

    private static string CreateManagedConnectorObserveOnlyDescription(
        string? reconciliationState,
        string? reconciliationReason)
    {
        if (string.IsNullOrWhiteSpace(reconciliationState) ||
            string.Equals(reconciliationState, "current", StringComparison.OrdinalIgnoreCase))
        {
            return "The managed connector is currently governed in observe-only mode.";
        }

        if (!string.IsNullOrWhiteSpace(reconciliationReason))
        {
            return $"The managed connector is currently governed in observe-only mode. {reconciliationReason}";
        }

        return $"The managed connector is currently governed in observe-only mode and last reported reconciliation state '{reconciliationState}'.";
    }

    private static string CreateManagedConnectorOutOfPolicyDescription(
        IReadOnlyCollection<string> categories,
        string? managementMode)
    {
        ArgumentNullException.ThrowIfNull(categories);

        var missingMessages = new List<string>(capacity: 4);
        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingManagementMode, StringComparer.OrdinalIgnoreCase))
        {
            missingMessages.Add("management mode");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingConnectClusterId, StringComparer.OrdinalIgnoreCase))
        {
            missingMessages.Add("connector cluster id");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingConnectorClass, StringComparer.OrdinalIgnoreCase))
        {
            missingMessages.Add("connector class");
        }

        if (categories.Contains(CdcCaptureExecutionRuntimeManagedConnectorGovernanceCategories.MissingSourceProviderId, StringComparer.OrdinalIgnoreCase))
        {
            missingMessages.Add("source provider id");
        }

        var description = missingMessages.Count switch
        {
            0 => "The managed connector is currently out of policy.",
            1 => $"The managed connector is currently out of policy because it does not declare {missingMessages[0]}.",
            2 => $"The managed connector is currently out of policy because it does not declare {missingMessages[0]} or {missingMessages[1]}.",
            _ => $"The managed connector is currently out of policy because it does not declare {string.Join(", ", missingMessages.Take(missingMessages.Count - 1))}, or {missingMessages[^1]}."
        };

        if (!string.IsNullOrWhiteSpace(managementMode) &&
            !string.Equals(managementMode, CdcCaptureExecutionRuntimeManagedConnectorGovernanceStates.ObserveOnly, StringComparison.OrdinalIgnoreCase))
        {
            return $"{description} It also declares future management mode '{managementMode}', which remains a later control-plane slice.";
        }

        return description;
    }

    private static CdcCaptureReporterCoordinationStatus CreateReporterCoordination(
        CdcCaptureExecutionRuntimeDescriptor runtime)
    {
        if (runtime.ReporterLeaseSeconds is not int reporterLeaseSeconds ||
            reporterLeaseSeconds <= 0)
        {
            return new CdcCaptureReporterCoordinationStatus(
                CdcCaptureReporterCoordinationStates.NotConfigured,
                "The execution runtime does not currently declare reporter-lease coordination.");
        }

        return new CdcCaptureReporterCoordinationStatus(
            CdcCaptureReporterCoordinationStates.Unreported,
            "The execution runtime has not reported any external reporter observations yet.");
    }

    private static CdcCaptureExecutionRuntimeReportingCoverageStatus CreateReportingCoverage(
        IReadOnlyList<string> declaredCaptureIds,
        IReadOnlyList<CdcCaptureRuntimeState> matchingStates)
    {
        var normalizedDeclaredCaptureIds = declaredCaptureIds
            .Where(static cdcCaptureId => !string.IsNullOrWhiteSpace(cdcCaptureId))
            .Select(static cdcCaptureId => cdcCaptureId.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(static cdcCaptureId => cdcCaptureId, StringComparer.OrdinalIgnoreCase)
            .ToArray();
        var reportedCaptureIds = matchingStates
            .Where(static state => state.HasReports)
            .Select(static state => state.CdcCaptureId)
            .Where(static cdcCaptureId => !string.IsNullOrWhiteSpace(cdcCaptureId))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(static cdcCaptureId => cdcCaptureId, StringComparer.OrdinalIgnoreCase)
            .ToArray();

        if (normalizedDeclaredCaptureIds.Length == 0)
        {
            return new CdcCaptureExecutionRuntimeReportingCoverageStatus(
                CdcCaptureExecutionRuntimeReportingCoverageStates.NotBound,
                "The execution runtime does not currently resolve to any CDC captures.")
            {
                DeclaredCaptureCount = 0,
                ReportedCaptureCount = reportedCaptureIds.Length
            };
        }

        var unreportedCaptureIds = normalizedDeclaredCaptureIds
            .Except(reportedCaptureIds, StringComparer.OrdinalIgnoreCase)
            .OrderBy(static cdcCaptureId => cdcCaptureId, StringComparer.OrdinalIgnoreCase)
            .ToArray();

        if (reportedCaptureIds.Length == 0)
        {
            return new CdcCaptureExecutionRuntimeReportingCoverageStatus(
                CdcCaptureExecutionRuntimeReportingCoverageStates.Unreported,
                normalizedDeclaredCaptureIds.Length == 1
                    ? $"Declared CDC capture '{normalizedDeclaredCaptureIds[0]}' has not reported runtime state yet."
                    : $"{normalizedDeclaredCaptureIds.Length} declared CDC captures have not reported runtime state yet.")
            {
                DeclaredCaptureCount = normalizedDeclaredCaptureIds.Length,
                ReportedCaptureCount = 0,
                UnreportedCdcCaptureIds = normalizedDeclaredCaptureIds
            };
        }

        if (unreportedCaptureIds.Length > 0)
        {
            return new CdcCaptureExecutionRuntimeReportingCoverageStatus(
                CdcCaptureExecutionRuntimeReportingCoverageStates.PartiallyReported,
                unreportedCaptureIds.Length == 1
                    ? $"Declared CDC capture '{unreportedCaptureIds[0]}' has not reported runtime state yet."
                    : $"{unreportedCaptureIds.Length} declared CDC captures have not reported runtime state yet.")
            {
                DeclaredCaptureCount = normalizedDeclaredCaptureIds.Length,
                ReportedCaptureCount = reportedCaptureIds.Length,
                UnreportedCdcCaptureIds = unreportedCaptureIds
            };
        }

        return new CdcCaptureExecutionRuntimeReportingCoverageStatus(
            CdcCaptureExecutionRuntimeReportingCoverageStates.FullyReported,
            normalizedDeclaredCaptureIds.Length == 1
                ? "The declared CDC capture has reported runtime state for the execution runtime."
                : "All declared CDC captures have reported runtime state for the execution runtime.")
        {
            DeclaredCaptureCount = normalizedDeclaredCaptureIds.Length,
            ReportedCaptureCount = reportedCaptureIds.Length
        };
    }

    private static CdcCaptureFreshnessStatus AggregateObservationFreshness(
        IReadOnlyList<CdcCaptureRuntimeState> matchingStates)
    {
        var reportedStates = matchingStates
            .Where(static state => state.HasReports)
            .ToArray();
        if (reportedStates.Length == 0)
        {
            return new CdcCaptureFreshnessStatus(CdcCaptureFreshnessStates.Unknown);
        }

        var knownStates = reportedStates
            .Select(static state => state.ObservationFreshness)
            .Where(static freshness => !string.Equals(freshness.State, CdcCaptureFreshnessStates.Unknown, StringComparison.OrdinalIgnoreCase))
            .ToArray();
        if (knownStates.Length == 0)
        {
            return new CdcCaptureFreshnessStatus(CdcCaptureFreshnessStates.Unknown);
        }

        if (knownStates.Any(static freshness => string.Equals(freshness.State, CdcCaptureFreshnessStates.Stale, StringComparison.OrdinalIgnoreCase)))
        {
            var earliestKnownExpiry = knownStates
                .Where(static freshness => freshness.FreshUntilUtc.HasValue)
                .Select(static freshness => freshness.FreshUntilUtc)
                .Min();
            return new CdcCaptureFreshnessStatus(
                CdcCaptureFreshnessStates.Stale,
                freshUntilUtc: earliestKnownExpiry,
                description: "At least one CDC capture observation owned by the execution runtime is now stale.");
        }

        var freshStates = knownStates
            .Where(static freshness => string.Equals(freshness.State, CdcCaptureFreshnessStates.Fresh, StringComparison.OrdinalIgnoreCase))
            .ToArray();
        if (freshStates.Length == knownStates.Length &&
            freshStates.All(static freshness => freshness.FreshUntilUtc.HasValue))
        {
            return new CdcCaptureFreshnessStatus(
                CdcCaptureFreshnessStates.Fresh,
                freshStates.Min(static freshness => freshness.FreshUntilUtc!.Value),
                "All CDC capture observations owned by the execution runtime remain within the configured freshness window.");
        }

        var earliestFreshExpiry = freshStates
            .Where(static freshness => freshness.FreshUntilUtc.HasValue)
            .Select(static freshness => freshness.FreshUntilUtc)
            .Min();
        return new CdcCaptureFreshnessStatus(
            CdcCaptureFreshnessStates.Mixed,
            freshUntilUtc: earliestFreshExpiry,
            description: "CDC capture observations owned by the execution runtime do not currently share the same freshness posture.");
    }

    private static CdcCaptureExecutionRuntimeReporterCoordinationRollup CreateReporterCoordinationRollup(
        IReadOnlyList<CdcCaptureRuntimeState> matchingStates)
    {
        if (matchingStates.Count == 0)
        {
            return CdcCaptureExecutionRuntimeReporterCoordinationRollup.Empty;
        }

        return new CdcCaptureExecutionRuntimeReporterCoordinationRollup(
            CoordinationStateBreakdown: CreateReporterCoordinationBreakdown(
                matchingStates.Select(static state => state.ReporterCoordination.State),
                CdcCaptureReporterCoordinationStates.Unknown),
            DegradedReasonBreakdown: CreateReporterCoordinationBreakdown(
                matchingStates.Select(static state => state.ReporterCoordination.DegradedReason),
                CdcCaptureReporterCoordinationIssueReasons.None))
        {
            ActiveReporterIds = GetReporterIdsByRole(
                matchingStates,
                CdcCaptureReporterParticipantRoles.Active),
            StandbyReporterIds = GetReporterIdsByRole(
                matchingStates,
                CdcCaptureReporterParticipantRoles.Standby),
            RejectedReporterIds = GetReporterIdsByRole(
                matchingStates,
                CdcCaptureReporterParticipantRoles.Rejected),
            DegradedCdcCaptureIds = matchingStates
                .Where(static state => state.HasReporterCoordinationIssue)
                .Select(static state => state.CdcCaptureId)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(static cdcCaptureId => cdcCaptureId, StringComparer.OrdinalIgnoreCase)
                .ToArray()
        };
    }

    private static CdcCaptureReporterCoordinationBreakdownEntry[] CreateReporterCoordinationBreakdown(
        IEnumerable<string?> values,
        string fallbackId)
    {
        ArgumentNullException.ThrowIfNull(values);
        ArgumentException.ThrowIfNullOrWhiteSpace(fallbackId);

        return values
            .Select(value => string.IsNullOrWhiteSpace(value) ? fallbackId.Trim() : value.Trim())
            .GroupBy(static value => value, StringComparer.OrdinalIgnoreCase)
            .Select(static group => new CdcCaptureReporterCoordinationBreakdownEntry(group.Key, group.Count()))
            .OrderBy(static item => item.Id, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string[] GetReporterIdsByRole(
        IReadOnlyList<CdcCaptureRuntimeState> matchingStates,
        string role)
    {
        ArgumentNullException.ThrowIfNull(matchingStates);
        ArgumentException.ThrowIfNullOrWhiteSpace(role);

        return matchingStates
            .SelectMany(static state => state.ReporterCoordination.ReporterParticipants)
            .Where(participant => string.Equals(participant.Role, role, StringComparison.OrdinalIgnoreCase))
            .Select(static participant => participant.ReporterId)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(static reporterId => reporterId, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private string[] ResolveCaptureIds(string executionRuntimeId)
    {
        return captureCatalog.GetByExecutionRuntimeId(executionRuntimeId)
            .Select(static cdcCapture => cdcCapture.Id)
            .OrderBy(static id => id, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string? ResolveActiveReporterId(
        IReadOnlyList<CdcCaptureRuntimeState> matchingStates,
        DateTimeOffset now)
    {
        var activeReporterIds = matchingStates
            .Where(state =>
                !string.IsNullOrWhiteSpace(state.LastReporterId) &&
                IsReporterLeaseActive(state.ReporterLeaseExpiresAtUtc, now))
            .Select(static state => state.LastReporterId!)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(static reporterId => reporterId, StringComparer.OrdinalIgnoreCase)
            .ToArray();

        return activeReporterIds.Length == 1
            ? activeReporterIds[0]
            : null;
    }

    private static DateTimeOffset? ResolveActiveReporterLeaseExpiry(
        IReadOnlyList<CdcCaptureRuntimeState> matchingStates,
        string? activeReporterId)
    {
        if (string.IsNullOrWhiteSpace(activeReporterId))
        {
            return null;
        }

        return matchingStates
            .Where(state => string.Equals(state.LastReporterId, activeReporterId, StringComparison.OrdinalIgnoreCase))
            .Where(static state => state.ReporterLeaseExpiresAtUtc.HasValue)
            .Select(static state => state.ReporterLeaseExpiresAtUtc)
            .Max();
    }

    private static bool IsReporterLeaseActive(
        DateTimeOffset? reporterLeaseExpiresAtUtc,
        DateTimeOffset now)
    {
        return !reporterLeaseExpiresAtUtc.HasValue ||
               reporterLeaseExpiresAtUtc.Value >= now;
    }

    private static string[] ResolveDelimitedMetadata(
        IReadOnlyDictionary<string, string> metadata,
        params string[] keys)
    {
        foreach (var key in keys)
        {
            if (!metadata.TryGetValue(key, out var value) ||
                string.IsNullOrWhiteSpace(value))
            {
                continue;
            }

            return value
                .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Where(static item => !string.IsNullOrWhiteSpace(item))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(static item => item, StringComparer.OrdinalIgnoreCase)
                .ToArray();
        }

        return [];
    }

    private static string? ResolveMetadata(
        IReadOnlyDictionary<string, string> metadata,
        params string[] keys)
    {
        foreach (var key in keys)
        {
            if (metadata.TryGetValue(key, out var value) &&
                !string.IsNullOrWhiteSpace(value))
            {
                return value.Trim();
            }
        }

        return null;
    }

    private static int? ResolveNullableIntMetadata(
        IReadOnlyDictionary<string, string> metadata,
        params string[] keys)
    {
        foreach (var key in keys)
        {
            if (!metadata.TryGetValue(key, out var value) ||
                string.IsNullOrWhiteSpace(value))
            {
                continue;
            }

            if (int.TryParse(value.Trim(), out var parsed))
            {
                return parsed;
            }
        }

        return null;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStatus CreateManagedConnectorProviderSpecificControlPlaneMaterializer(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string? executionOwnership,
        string? executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        ManagedConnectorMetadataSnapshot metadataSnapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(metadataSnapshot);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var operationId =
            !string.IsNullOrWhiteSpace(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.OperationId)
                ? providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneApplyAndReconcileExecution.OperationId)
                    ? providerOwnedControlPlaneApplyAndReconcileExecution.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.OperationId)
                        ? providerOwnedControlPlaneMutationReconcile.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.OperationId)
                            ? providerOwnedControlPlaneProvisioning.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(executionAdapter.OperationId)
                                ? executionAdapter.OperationId.Trim()
                                : !string.IsNullOrWhiteSpace(latestCommandExecution.ResolvedOperationId)
                                    ? latestCommandExecution.ResolvedOperationId.Trim()
                                    : !string.IsNullOrWhiteSpace(latestCommandExecution.RequestedOperationId)
                                        ? latestCommandExecution.RequestedOperationId.Trim()
                                    : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var providerId = string.IsNullOrWhiteSpace(metadataSnapshot.ProviderSpecificControlPlaneProviderId)
            ? null
            : metadataSnapshot.ProviderSpecificControlPlaneProviderId.Trim();
        var materializerId = string.IsNullOrWhiteSpace(metadataSnapshot.ProviderSpecificControlPlaneMaterializerId)
            ? null
            : metadataSnapshot.ProviderSpecificControlPlaneMaterializerId.Trim();
        var transportKind = string.IsNullOrWhiteSpace(metadataSnapshot.ProviderSpecificControlPlaneTransportKind)
            ? null
            : metadataSnapshot.ProviderSpecificControlPlaneTransportKind.Trim();
        var providerSurfaceId = string.IsNullOrWhiteSpace(metadataSnapshot.ProviderSpecificControlPlaneSurfaceId)
            ? null
            : metadataSnapshot.ProviderSpecificControlPlaneSurfaceId.Trim();
        var connectorId = string.IsNullOrWhiteSpace(metadataSnapshot.ProviderSpecificControlPlaneConnectorId)
            ? null
            : metadataSnapshot.ProviderSpecificControlPlaneConnectorId.Trim();
        var workerId = string.IsNullOrWhiteSpace(metadataSnapshot.ProviderSpecificControlPlaneWorkerId)
            ? null
            : metadataSnapshot.ProviderSpecificControlPlaneWorkerId.Trim();
        var appliesToManagedConnector =
            executionAdapter.AppliesToManagedConnector ||
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.AppliesToManagedConnector ||
            providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector ||
            providerOwnedControlPlaneProvisioning.AppliesToManagedConnector ||
            providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector ||
            providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
            providerExecutionOrchestration.AppliesToManagedConnector ||
            providerOwnedWritePathExecution.AppliesToManagedConnector ||
            (string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
             (!string.IsNullOrWhiteSpace(providerId) || !string.IsNullOrWhiteSpace(materializerId)));
        var hasProviderIdentity = !string.IsNullOrWhiteSpace(providerId);
        var hasMaterializerIdentity = !string.IsNullOrWhiteSpace(materializerId);
        var hasTransportIdentity = !string.IsNullOrWhiteSpace(transportKind);
        var hasProviderSurfaceIdentity = !string.IsNullOrWhiteSpace(providerSurfaceId);
        var hasConnectorIdentity = !string.IsNullOrWhiteSpace(connectorId);
        var hasWorkerIdentity = !string.IsNullOrWhiteSpace(workerId);
        var hasTargetOperation =
            !string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None, StringComparison.OrdinalIgnoreCase);
        var isProvisioningOperation = providerOwnedControlPlaneProvisioning.HasTargetOperation && !providerOwnedControlPlaneMutationReconcile.HasTargetOperation;
        var isMutationOperation = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsMutationOperation;
        var isReconcileOperation = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsReconcileOperation;
        var canUseProviderSpecificControlPlaneMaterializerOnCurrentNode =
            hasProviderIdentity &&
            hasMaterializerIdentity &&
            hasTransportIdentity &&
            hasProviderSurfaceIdentity &&
            hasConnectorIdentity &&
            executionAdapter.CanUseProviderExecutionAdapter &&
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.CanExecuteDependencyAwareProvisioningAndMutationOnCurrentNode;
        var isRisk =
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDependencyRisk ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk ||
            providerOwnedControlPlaneProvisioning.IsProvisioningRisk ||
            providerOwnedControlPlaneMutationReconcile.IsMutationRisk ||
            providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
            providerExecutionOrchestration.IsOrchestrationRisk ||
            providerOwnedWritePathExecution.IsProviderOwnedRisk ||
            (executionAdapter.IsBlocked && hasMaterializerIdentity);
        var isExecuting =
            hasMaterializerIdentity &&
            (providerExecutionOrchestration.IsOrchestrationExecuting ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting ||
             providerOwnedControlPlaneProvisioning.IsProvisioningExecuting ||
             providerOwnedControlPlaneMutationReconcile.IsMutationExecuting ||
             providerOwnedWritePathExecution.IsProviderOwnedExecuting);
        var isSelected =
            hasMaterializerIdentity &&
            (latestCommandExecution.IsAdapted ||
             latestCommandExecution.IsNoOp ||
             providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsProvisioningHardened ||
             providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsMutationHardened ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted ||
             executionAdapter.HasAdaptableCommand);
        var isReady =
            hasMaterializerIdentity &&
            executionAdapter.CanUseProviderExecutionAdapter &&
            (providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDependencyReady ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady ||
             providerOwnedControlPlaneProvisioning.IsProvisioningReady ||
             providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
             providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
             providerExecutionOrchestration.IsOrchestrationReady ||
             providerOwnedWritePathExecution.IsProviderExecutable);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.NotApplicable
                : providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsOperatorOnly ||
                  providerOwnedControlPlaneApplyAndReconcileExecution.IsOperatorOnly ||
                  providerOwnedControlPlaneProvisioning.IsOperatorOnly ||
                  providerOwnedControlPlaneMutationReconcile.IsOperatorOnly ||
                  providerOwnedControlPlaneOwnership.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.OperatorOnly
                    : isRisk
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerRisk
                        : isExecuting
                            ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerExecuting
                            : isSelected
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerSelected
                                : isReady
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerReady
                                    : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerUnavailable;
        var categories = CreateManagedConnectorProviderSpecificControlPlaneMaterializerCategories(
            state,
            summary,
            latestCommandExecution,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
            hasProviderIdentity,
            hasMaterializerIdentity,
            hasTransportIdentity,
            hasProviderSurfaceIdentity,
            hasConnectorIdentity,
            hasWorkerIdentity,
            hasTargetOperation,
            isMutationOperation,
            isReconcileOperation,
            canUseProviderSpecificControlPlaneMaterializerOnCurrentNode,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.WouldApplyChanges,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.RequiresExplicitApproval,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDestructiveOperation,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasDeclaredDependencyIdentity,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasReportedDependencyIdentity);
        var description = CreateManagedConnectorProviderSpecificControlPlaneMaterializerDescription(
            state,
            operationId,
            providerId,
            materializerId,
            transportKind,
            providerSurfaceId,
            summary,
            latestCommandExecution,
            commandJournal,
            executionAdapter,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
            hasProviderIdentity,
            hasMaterializerIdentity,
            hasTransportIdentity,
            hasProviderSurfaceIdentity,
            hasConnectorIdentity,
            metadataSnapshot.ReconciliationReason);
        var sourceId = ResolveManagedConnectorProviderSpecificControlPlaneMaterializerSourceId(
            latestCommandExecution,
            commandJournal,
            providerOwnedWritePathExecution,
            providerExecutionOrchestration,
            providerOwnedControlPlaneOwnership,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
            executionAdapter,
            hasProviderIdentity,
            hasMaterializerIdentity);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = operationId,
            SourceId = sourceId,
            ProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningState = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.State,
            ProviderOwnedControlPlaneApplyAndReconcileExecutionState = providerOwnedControlPlaneApplyAndReconcileExecution.State,
            ProviderOwnedControlPlaneProvisioningState = providerOwnedControlPlaneProvisioning.State,
            ProviderOwnedControlPlaneMutationReconcileState = providerOwnedControlPlaneMutationReconcile.State,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            ProviderId = providerId,
            MaterializerId = materializerId,
            TransportKind = transportKind,
            ProviderSurfaceId = providerSurfaceId,
            ConnectClusterId = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.ConnectClusterId,
            ConnectorId = connectorId,
            ConnectorClass = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.ConnectorClass,
            SourceProviderId = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.SourceProviderId,
            WorkerId = workerId,
            ReconciliationState = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.ReconciliationState,
            ReconciliationReason = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.ReconciliationReason,
            PotentialChangeCount = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.PotentialChangeCount,
            LatestAttemptId = latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = latestCommandExecution.RecordedAtUtc,
            ActiveReporterId = summary.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = summary.ReporterLeaseExpiresAtUtc,
            WouldApplyChanges = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.WouldApplyChanges,
            RequiresExplicitApproval = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.RequiresExplicitApproval,
            IsDestructiveOperation = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDestructiveOperation,
            HasTargetOperation = hasTargetOperation,
            IsProvisioningOperation = isProvisioningOperation,
            IsMutationOperation = isMutationOperation,
            IsReconcileOperation = isReconcileOperation,
            HasProviderIdentity = hasProviderIdentity,
            HasMaterializerIdentity = hasMaterializerIdentity,
            HasTransportIdentity = hasTransportIdentity,
            HasProviderSurfaceIdentity = hasProviderSurfaceIdentity,
            HasConnectorIdentity = hasConnectorIdentity,
            HasWorkerIdentity = hasWorkerIdentity,
            HasDeclaredDependencyIdentity = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasDeclaredDependencyIdentity,
            HasReportedDependencyIdentity = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasReportedDependencyIdentity,
            CanUseProviderSpecificControlPlaneMaterializerOnCurrentNode = canUseProviderSpecificControlPlaneMaterializerOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderSpecificControlPlaneMaterializerCategories(
        string state,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        bool hasProviderIdentity,
        bool hasMaterializerIdentity,
        bool hasTransportIdentity,
        bool hasProviderSurfaceIdentity,
        bool hasConnectorIdentity,
        bool hasWorkerIdentity,
        bool hasTargetOperation,
        bool isMutationOperation,
        bool isReconcileOperation,
        bool canUseProviderSpecificControlPlaneMaterializerOnCurrentNode,
        bool wouldApplyChanges,
        bool requiresExplicitApproval,
        bool isDestructiveOperation,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);

        if (!providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.AppliesToManagedConnector &&
            !providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector &&
            !providerOwnedControlPlaneProvisioning.AppliesToManagedConnector &&
            !providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector)
        {
            return [];
        }

        var categories = new List<string>(capacity: 32);
        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderSpecificControlPlaneMaterializer);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerUnavailable, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MaterializerUnavailable);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MaterializerReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerSelected, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MaterializerSelected);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerExecuting, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MaterializerExecuting);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MaterializerRisk);
        }

        if (providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDependencyReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.DependencyReady);
        }

        if (providerOwnedControlPlaneProvisioning.IsProvisioningReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProvisioningReady);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProvisioningExecuting);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProvisioningBlocked);
        }
        else if (providerOwnedControlPlaneProvisioning.IsProvisioningRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProvisioningRisk);
        }

        if (providerOwnedControlPlaneMutationReconcile.IsMutationReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MutationReady);
        }

        if (providerOwnedControlPlaneMutationReconcile.IsReconcileReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ReconcileReady);
        }

        if (providerOwnedControlPlaneMutationReconcile.IsMutationExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MutationExecuting);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MutationBlocked);
        }
        else if (providerOwnedControlPlaneMutationReconcile.IsMutationRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MutationRisk);
        }

        if (providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsProvisioningHardened ||
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsMutationHardened)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ApplyAndReconcileHardened);
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ApplyAndReconcileExecuting);
        }
        else if (providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk ||
                 providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDependencyRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ApplyAndReconcileRisk);
        }

        if (hasTargetOperation)
        {
            if (isMutationOperation)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MutationOperation);
            }
            else if (isReconcileOperation)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ReconcileOperation);
            }
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.NoTargetOperation);
        }

        AddCategory(
            categories,
            canUseProviderSpecificControlPlaneMaterializerOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.CurrentNodeExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.CurrentNodeBlocked);

        AddCategory(
            categories,
            hasProviderIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MissingProviderId);
        AddCategory(
            categories,
            hasMaterializerIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MaterializerIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MissingMaterializerId);
        AddCategory(
            categories,
            hasTransportIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.TransportIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MissingTransportKind);
        AddCategory(
            categories,
            hasProviderSurfaceIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderSurfaceReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MissingProviderSurface);
        AddCategory(
            categories,
            hasConnectorIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ConnectorIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.MissingConnectorId);
        AddCategory(
            categories,
            hasWorkerIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.WorkerIdentityVisible
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.WorkerIdentityUnavailable);

        AddCategory(
            categories,
            wouldApplyChanges
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.WouldApplyChanges
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.NoChangesRequired);

        if (requiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ApprovalRequired);
        }

        if (isDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.DestructiveOperation);
        }

        if (hasDeclaredDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.DeclaredDependencyIdentityReady);
        }

        if (hasReportedDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ReportedDependencyIdentityReady);
        }

        AddCategory(
            categories,
            summary.HasActiveReporterLease
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ReporterLeaseActive
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ReporterLeaseMissingOrStale);

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerCategories.ProviderCommandFailed);
        }

        return categories
            .OrderBy(static category => category, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string CreateManagedConnectorProviderSpecificControlPlaneMaterializerDescription(
        string state,
        string operationId,
        string? providerId,
        string? materializerId,
        string? transportKind,
        string? providerSurfaceId,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        bool hasProviderIdentity,
        bool hasMaterializerIdentity,
        bool hasTransportIdentity,
        bool hasProviderSurfaceIdentity,
        bool hasConnectorIdentity,
        string? reconciliationReason)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);

        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);
        var providerLabel = string.IsNullOrWhiteSpace(providerId) ? "unknown-provider" : providerId.Trim();
        var materializerLabel = string.IsNullOrWhiteSpace(materializerId) ? "unknown-materializer" : materializerId.Trim();
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.Description,
                executionAdapter.Description,
                latestCommandExecution.IsUnrecorded ? null : latestCommandExecution.Description),
            summary.ReporterCoordination.Description,
            CombineManagedConnectorCommandEnvelopeDetail(commandJournal.Description, reconciliationReason, null));

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "The execution runtime does not currently represent managed-connector provider-specific control-plane materialization.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can describe provider-specific control-plane materializer follow-through for {operationLabel}, but the lane still remains operator-owned outside the engine.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can identify provider-specific materializer follow-through for provider '{providerLabel}', but the selected materializer '{materializerLabel}' still remains risky on the shared runtime surface.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerUnavailable, StringComparison.OrdinalIgnoreCase))
        {
            string summaryText;
            if (!hasProviderIdentity)
            {
                summaryText = $"Cephalon cannot yet select one provider-specific control-plane materializer for {operationLabel} because the provider identity is missing.";
            }
            else if (!hasMaterializerIdentity)
            {
                summaryText = $"Cephalon cannot yet select one provider-specific control-plane materializer for provider '{providerLabel}' because no materializer id is declared.";
            }
            else if (!hasTransportIdentity)
            {
                summaryText = $"Cephalon cannot yet use provider-specific materializer '{materializerLabel}' because the transport kind is missing.";
            }
            else if (!hasProviderSurfaceIdentity)
            {
                summaryText = $"Cephalon cannot yet use provider-specific materializer '{materializerLabel}' because the provider surface id is missing.";
            }
            else if (!hasConnectorIdentity)
            {
                summaryText = $"Cephalon cannot yet use provider-specific materializer '{materializerLabel}' because the connector identity is missing.";
            }
            else
            {
                summaryText = $"Cephalon cannot yet use provider-specific materializer '{materializerLabel}' for {operationLabel} because the shared provider adapter lane still remains unavailable.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerReady, StringComparison.OrdinalIgnoreCase))
        {
            var transportLabel = string.IsNullOrWhiteSpace(transportKind) ? "unknown-transport" : transportKind.Trim();
            var surfaceLabel = string.IsNullOrWhiteSpace(providerSurfaceId) ? "unknown-surface" : providerSurfaceId.Trim();
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is ready to use provider-specific materializer '{materializerLabel}' for provider '{providerLabel}' on {transportLabel} surface '{surfaceLabel}' when {operationLabel} needs a provider-owned control-plane step.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerSelected, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon selected provider-specific materializer '{materializerLabel}' for provider '{providerLabel}' while staging {operationLabel} on the shared provider lane.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStates.MaterializerExecuting, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon selected provider-specific materializer '{materializerLabel}' for provider '{providerLabel}', and that materializer is actively driving {operationLabel} on the shared provider lane.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon exposes provider-specific control-plane materializer truth for provider '{providerLabel}'.",
            detail);
    }

    private static string ResolveManagedConnectorProviderSpecificControlPlaneMaterializerSourceId(
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        bool hasProviderIdentity,
        bool hasMaterializerIdentity)
    {
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);
        ArgumentNullException.ThrowIfNull(executionAdapter);

        if (!latestCommandExecution.IsUnrecorded && latestCommandExecution.IsFailed)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.CommandExecution;
        }

        if (providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening;
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderOwnedControlPlaneApplyAndReconcileExecution;
        }

        if (providerOwnedControlPlaneProvisioning.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderOwnedControlPlaneProvisioning;
        }

        if (providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderOwnedControlPlaneMutationReconcile;
        }

        if (providerOwnedControlPlaneOwnership.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderOwnedControlPlaneOwnership;
        }

        if (providerExecutionOrchestration.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderExecutionOrchestration;
        }

        if (providerOwnedWritePathExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ProviderOwnedWritePathExecution;
        }

        if (executionAdapter.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.ExecutionAdapter;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.CommandJournal;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.CommandExecution;
        }

        return hasProviderIdentity || hasMaterializerIdentity
            ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.Metadata
            : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerSources.Unknown;
    }

    private static CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStatus CreateManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardening(
        string executionRuntimeId,
        IReadOnlyList<string> cdcCaptureIds,
        string? executionOwnership,
        string? executionTopology,
        string? managementMode,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandRetryStatus commandRetry,
        CdcCaptureExecutionRuntimeManagedConnectorRetryExecutionPolicyStatus retryExecutionPolicy,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStatus providerSpecificControlPlaneMaterializer)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(executionRuntimeId);
        ArgumentNullException.ThrowIfNull(cdcCaptureIds);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandRetry);
        ArgumentNullException.ThrowIfNull(retryExecutionPolicy);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);
        ArgumentNullException.ThrowIfNull(providerSpecificControlPlaneMaterializer);

        var normalizedExecutionOwnership = string.IsNullOrWhiteSpace(executionOwnership)
            ? "runtime-managed"
            : executionOwnership.Trim();
        var normalizedExecutionTopology = string.IsNullOrWhiteSpace(executionTopology)
            ? "not-configured"
            : executionTopology.Trim();
        var operationId =
            !string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.OperationId)
                ? providerSpecificControlPlaneMaterializer.OperationId.Trim()
                : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.OperationId)
                    ? providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.OperationId.Trim()
                    : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneApplyAndReconcileExecution.OperationId)
                        ? providerOwnedControlPlaneApplyAndReconcileExecution.OperationId.Trim()
                        : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneMutationReconcile.OperationId)
                            ? providerOwnedControlPlaneMutationReconcile.OperationId.Trim()
                            : !string.IsNullOrWhiteSpace(providerOwnedControlPlaneProvisioning.OperationId)
                                ? providerOwnedControlPlaneProvisioning.OperationId.Trim()
                                : !string.IsNullOrWhiteSpace(latestCommandExecution.ResolvedOperationId)
                                    ? latestCommandExecution.ResolvedOperationId.Trim()
                                    : !string.IsNullOrWhiteSpace(latestCommandExecution.RequestedOperationId)
                                        ? latestCommandExecution.RequestedOperationId.Trim()
                                        : CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None;
        var providerId = string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.ProviderId)
            ? null
            : providerSpecificControlPlaneMaterializer.ProviderId.Trim();
        var materializerId = string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.MaterializerId)
            ? null
            : providerSpecificControlPlaneMaterializer.MaterializerId.Trim();
        var transportKind = string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.TransportKind)
            ? null
            : providerSpecificControlPlaneMaterializer.TransportKind.Trim();
        var providerSurfaceId = string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.ProviderSurfaceId)
            ? null
            : providerSpecificControlPlaneMaterializer.ProviderSurfaceId.Trim();
        var connectorId = string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.ConnectorId)
            ? null
            : providerSpecificControlPlaneMaterializer.ConnectorId.Trim();
        var workerId = string.IsNullOrWhiteSpace(providerSpecificControlPlaneMaterializer.WorkerId)
            ? null
            : providerSpecificControlPlaneMaterializer.WorkerId.Trim();
        var appliesToManagedConnector =
            providerSpecificControlPlaneMaterializer.AppliesToManagedConnector ||
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.AppliesToManagedConnector ||
            providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector ||
            providerOwnedControlPlaneProvisioning.AppliesToManagedConnector ||
            providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector ||
            providerOwnedControlPlaneOwnership.AppliesToManagedConnector ||
            providerExecutionOrchestration.AppliesToManagedConnector ||
            providerOwnedWritePathExecution.AppliesToManagedConnector ||
            (string.Equals(normalizedExecutionTopology, "managed-connector", StringComparison.OrdinalIgnoreCase) &&
             (!string.IsNullOrWhiteSpace(providerId) || !string.IsNullOrWhiteSpace(materializerId)));
        var hasProviderIdentity = providerSpecificControlPlaneMaterializer.HasProviderIdentity;
        var hasMaterializerIdentity = providerSpecificControlPlaneMaterializer.HasMaterializerIdentity;
        var hasTransportIdentity = providerSpecificControlPlaneMaterializer.HasTransportIdentity;
        var hasProviderSurfaceIdentity = providerSpecificControlPlaneMaterializer.HasProviderSurfaceIdentity;
        var hasConnectorIdentity = providerSpecificControlPlaneMaterializer.HasConnectorIdentity;
        var hasWorkerIdentity = providerSpecificControlPlaneMaterializer.HasWorkerIdentity;
        var hasDeclaredDependencyIdentity = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasDeclaredDependencyIdentity;
        var hasReportedDependencyIdentity = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasReportedDependencyIdentity;
        var hasTaskBaseline = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasTaskBaseline;
        var hasReportedTaskTopology = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasReportedTaskTopology;
        var hasActiveTaskTopology = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasActiveTaskTopology;
        var hasDependencyIdentityMismatch = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasDependencyIdentityMismatch;
        var hasTaskTopologyMismatch = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasTaskTopologyMismatch;
        var hasDurableStoreConfigured =
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasDurableStoreConfigured ||
            providerOwnedControlPlaneApplyAndReconcileExecution.HasDurableStoreConfigured ||
            providerOwnedControlPlaneProvisioning.HasDurableStoreConfigured ||
            providerOwnedControlPlaneMutationReconcile.HasDurableStoreConfigured;
        var hasPersistedRecordedHistory =
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneApplyAndReconcileExecution.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneProvisioning.HasPersistedRecordedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasPersistedRecordedHistory;
        var hasRecoveredPersistedHistory =
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneApplyAndReconcileExecution.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneProvisioning.HasRecoveredPersistedHistory ||
            providerOwnedControlPlaneMutationReconcile.HasRecoveredPersistedHistory;
        var hasTargetOperation =
            providerSpecificControlPlaneMaterializer.HasTargetOperation ||
            !string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.None, StringComparison.OrdinalIgnoreCase);
        var isTeardownOperation =
            providerSpecificControlPlaneMaterializer.IsDestructiveOperation ||
            string.Equals(operationId, CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterOperationIds.Delete, StringComparison.OrdinalIgnoreCase);
        var isMutationOperation = providerSpecificControlPlaneMaterializer.IsMutationOperation;
        var isReconcileOperation = providerSpecificControlPlaneMaterializer.IsReconcileOperation;
        var isMutationExecutionOperation = hasTargetOperation && !isTeardownOperation;
        var canUseMaterializerOnCurrentNode = providerSpecificControlPlaneMaterializer.CanUseProviderSpecificControlPlaneMaterializerOnCurrentNode;
        var canExecuteDependencyAwareMutationExecutionOnCurrentNode =
            isMutationExecutionOperation &&
            canUseMaterializerOnCurrentNode &&
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.CanExecuteDependencyAwareMutationOnCurrentNode;
        var canExecuteDependencyAwareTeardownOnCurrentNode =
            isTeardownOperation &&
            canUseMaterializerOnCurrentNode &&
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.CanExecuteDependencyAwareMutationOnCurrentNode;
        var canExecuteDependencyAwareTeardownAndMutationExecutionOnCurrentNode =
            canExecuteDependencyAwareTeardownOnCurrentNode ||
            canExecuteDependencyAwareMutationExecutionOnCurrentNode;
        var hasReporterLeaseIssue = !summary.HasActiveReporterLease || summary.HasReporterCoordinationIssue || summary.HasStaleObservations;
        var hasDependencyRisk =
            providerSpecificControlPlaneMaterializer.IsMaterializerRisk ||
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDependencyRisk ||
            providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileRisk ||
            providerOwnedControlPlaneProvisioning.IsProvisioningRisk ||
            providerOwnedControlPlaneMutationReconcile.IsMutationRisk ||
            providerOwnedControlPlaneOwnership.IsOwnershipRisk ||
            providerExecutionOrchestration.IsOrchestrationRisk ||
            providerOwnedWritePathExecution.IsProviderOwnedRisk ||
            latestCommandExecution.IsFailed;
        var hasDependencyDegradation =
            providerSpecificControlPlaneMaterializer.IsMaterializerUnavailable ||
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsDependencyDegraded ||
            !hasProviderIdentity ||
            !hasMaterializerIdentity ||
            !hasTransportIdentity ||
            !hasProviderSurfaceIdentity ||
            !hasConnectorIdentity ||
            !hasReportedDependencyIdentity ||
            !hasActiveTaskTopology ||
            hasDependencyIdentityMismatch ||
            hasTaskTopologyMismatch ||
            hasReporterLeaseIssue ||
            latestCommandExecution.IsBlocked ||
            latestCommandExecution.IsUnavailable;
        var hasCommonHardeningEvidence =
            hasProviderIdentity &&
            hasMaterializerIdentity &&
            hasTransportIdentity &&
            hasProviderSurfaceIdentity &&
            hasConnectorIdentity &&
            hasDeclaredDependencyIdentity &&
            hasReportedDependencyIdentity &&
            hasTaskBaseline &&
            hasReportedTaskTopology &&
            hasActiveTaskTopology &&
            !hasDependencyIdentityMismatch &&
            !hasTaskTopologyMismatch &&
            !hasReporterLeaseIssue &&
            (hasDurableStoreConfigured || hasPersistedRecordedHistory);
        var hasTeardownHardenedEvidence =
            isTeardownOperation &&
            hasCommonHardeningEvidence &&
            canExecuteDependencyAwareTeardownOnCurrentNode &&
            (providerSpecificControlPlaneMaterializer.IsMaterializerSelected ||
             providerSpecificControlPlaneMaterializer.IsMaterializerExecuting ||
             latestCommandExecution.IsAdapted ||
             latestCommandExecution.IsNoOp);
        var hasMutationExecutionHardenedEvidence =
            isMutationExecutionOperation &&
            hasCommonHardeningEvidence &&
            canExecuteDependencyAwareMutationExecutionOnCurrentNode &&
            (providerSpecificControlPlaneMaterializer.IsMaterializerSelected ||
             providerSpecificControlPlaneMaterializer.IsMaterializerExecuting ||
             providerOwnedControlPlaneMutationReconcile.IsMutationExecuting ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting ||
             latestCommandExecution.IsAdapted ||
             latestCommandExecution.IsNoOp);
        var hasReadyMaterializerLane =
            providerSpecificControlPlaneMaterializer.IsMaterializerReady ||
            providerSpecificControlPlaneMaterializer.IsMaterializerSelected ||
            providerSpecificControlPlaneMaterializer.IsMaterializerExecuting;
        var hasTeardownReadyLane =
            isTeardownOperation &&
            hasTargetOperation &&
            hasReadyMaterializerLane &&
            hasProviderIdentity &&
            hasMaterializerIdentity &&
            hasTransportIdentity &&
            hasProviderSurfaceIdentity &&
            hasConnectorIdentity;
        var hasMutationExecutionReadyLane =
            isMutationExecutionOperation &&
            hasReadyMaterializerLane &&
            (canUseMaterializerOnCurrentNode ||
             providerOwnedControlPlaneMutationReconcile.IsMutationReady ||
             providerOwnedControlPlaneMutationReconcile.IsReconcileReady ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileReady ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileExecuting ||
             providerOwnedControlPlaneApplyAndReconcileExecution.IsApplyAndReconcileCompleted);
        var state =
            !appliesToManagedConnector
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.NotApplicable
                : providerSpecificControlPlaneMaterializer.IsOperatorOnly ||
                  providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.IsOperatorOnly ||
                  providerOwnedControlPlaneApplyAndReconcileExecution.IsOperatorOnly ||
                  providerOwnedControlPlaneProvisioning.IsOperatorOnly ||
                  providerOwnedControlPlaneMutationReconcile.IsOperatorOnly ||
                  providerOwnedControlPlaneOwnership.IsOperatorOnly
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.OperatorOnly
                    : hasDependencyRisk
                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyRisk
                        : isTeardownOperation
                            ? hasTeardownHardenedEvidence
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.TeardownHardened
                                : hasDependencyDegradation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyDegraded
                                    : hasTeardownReadyLane
                                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyReady
                                        : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.TeardownBlocked
                            : hasMutationExecutionHardenedEvidence
                                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.MutationExecutionHardened
                                : hasDependencyDegradation
                                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyDegraded
                                    : hasMutationExecutionReadyLane
                                        ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyReady
                                        : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.MutationExecutionBlocked;
        var categories = CreateManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories(
            state,
            summary,
            latestCommandExecution,
            providerSpecificControlPlaneMaterializer,
            hasProviderIdentity,
            hasMaterializerIdentity,
            hasTransportIdentity,
            hasProviderSurfaceIdentity,
            hasConnectorIdentity,
            hasWorkerIdentity,
            hasTargetOperation,
            isTeardownOperation,
            isMutationExecutionOperation,
            isMutationOperation,
            isReconcileOperation,
            hasDeclaredDependencyIdentity,
            hasReportedDependencyIdentity,
            hasTaskBaseline,
            hasReportedTaskTopology,
            hasActiveTaskTopology,
            hasDependencyIdentityMismatch,
            hasTaskTopologyMismatch,
            hasDurableStoreConfigured,
            hasPersistedRecordedHistory,
            hasRecoveredPersistedHistory,
            canExecuteDependencyAwareTeardownAndMutationExecutionOnCurrentNode,
            canExecuteDependencyAwareTeardownOnCurrentNode,
            canExecuteDependencyAwareMutationExecutionOnCurrentNode);
        var description = CreateManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningDescription(
            state,
            operationId,
            providerId,
            materializerId,
            providerSurfaceId,
            summary,
            latestCommandExecution,
            commandJournal,
            executionAdapter,
            providerSpecificControlPlaneMaterializer,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
            isTeardownOperation,
            hasProviderIdentity,
            hasMaterializerIdentity,
            hasTransportIdentity,
            hasProviderSurfaceIdentity,
            hasConnectorIdentity,
            hasDeclaredDependencyIdentity,
            hasReportedDependencyIdentity,
            hasTaskBaseline,
            hasReportedTaskTopology,
            hasActiveTaskTopology,
            providerSpecificControlPlaneMaterializer.ReconciliationReason);
        var sourceId = ResolveManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSourceId(
            latestCommandExecution,
            commandJournal,
            executionAdapter,
            providerOwnedWritePathExecution,
            providerExecutionOrchestration,
            providerOwnedControlPlaneOwnership,
            providerOwnedControlPlaneMutationReconcile,
            providerOwnedControlPlaneProvisioning,
            providerOwnedControlPlaneApplyAndReconcileExecution,
            providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
            providerSpecificControlPlaneMaterializer,
            hasProviderIdentity,
            hasMaterializerIdentity);

        return new CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStatus(state, description)
        {
            CategoryIds = categories,
            ExecutionRuntimeId = executionRuntimeId,
            CdcCaptureIds = cdcCaptureIds,
            ExecutionOwnership = normalizedExecutionOwnership,
            ExecutionTopology = normalizedExecutionTopology,
            ManagementMode = managementMode,
            OperationId = operationId,
            SourceId = sourceId,
            ProviderSpecificControlPlaneMaterializerState = providerSpecificControlPlaneMaterializer.State,
            ProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningState = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.State,
            ProviderOwnedControlPlaneApplyAndReconcileExecutionState = providerOwnedControlPlaneApplyAndReconcileExecution.State,
            ProviderOwnedControlPlaneProvisioningState = providerOwnedControlPlaneProvisioning.State,
            ProviderOwnedControlPlaneMutationReconcileState = providerOwnedControlPlaneMutationReconcile.State,
            ProviderOwnedControlPlaneOwnershipState = providerOwnedControlPlaneOwnership.State,
            ProviderExecutionOrchestrationState = providerExecutionOrchestration.State,
            ProviderOwnedWritePathExecutionState = providerOwnedWritePathExecution.State,
            ExecutionAdapterState = executionAdapter.State,
            LatestCommandExecutionState = latestCommandExecution.State,
            CommandRetryState = commandRetry.State,
            RetryExecutionPolicyState = retryExecutionPolicy.State,
            CommandJournalState = commandJournal.State,
            ProviderId = providerId,
            MaterializerId = materializerId,
            TransportKind = transportKind,
            ProviderSurfaceId = providerSurfaceId,
            ConnectClusterId = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.ConnectClusterId,
            ConnectorId = connectorId,
            ConnectorClass = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.ConnectorClass,
            SourceProviderId = providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.SourceProviderId,
            WorkerId = workerId,
            ReconciliationState = providerSpecificControlPlaneMaterializer.ReconciliationState,
            ReconciliationReason = providerSpecificControlPlaneMaterializer.ReconciliationReason,
            PotentialChangeCount = providerSpecificControlPlaneMaterializer.PotentialChangeCount,
            LatestAttemptId = latestCommandExecution.AttemptId,
            LatestRecordedAtUtc = latestCommandExecution.RecordedAtUtc,
            ActiveReporterId = summary.ActiveReporterId,
            ActiveReporterLeaseExpiresAtUtc = summary.ReporterLeaseExpiresAtUtc,
            WouldApplyChanges = providerSpecificControlPlaneMaterializer.WouldApplyChanges,
            RequiresExplicitApproval = providerSpecificControlPlaneMaterializer.RequiresExplicitApproval,
            IsDestructiveOperation = providerSpecificControlPlaneMaterializer.IsDestructiveOperation,
            HasTargetOperation = hasTargetOperation,
            IsTeardownOperation = isTeardownOperation,
            IsMutationExecutionOperation = isMutationExecutionOperation,
            IsMutationOperation = isMutationOperation,
            IsReconcileOperation = isReconcileOperation,
            HasProviderIdentity = hasProviderIdentity,
            HasMaterializerIdentity = hasMaterializerIdentity,
            HasTransportIdentity = hasTransportIdentity,
            HasProviderSurfaceIdentity = hasProviderSurfaceIdentity,
            HasConnectorIdentity = hasConnectorIdentity,
            HasWorkerIdentity = hasWorkerIdentity,
            HasDeclaredDependencyIdentity = hasDeclaredDependencyIdentity,
            HasReportedDependencyIdentity = hasReportedDependencyIdentity,
            HasTaskBaseline = hasTaskBaseline,
            HasReportedTaskTopology = hasReportedTaskTopology,
            HasActiveTaskTopology = hasActiveTaskTopology,
            HasDependencyIdentityMismatch = hasDependencyIdentityMismatch,
            HasTaskTopologyMismatch = hasTaskTopologyMismatch,
            HasDurableStoreConfigured = hasDurableStoreConfigured,
            HasPersistedRecordedHistory = hasPersistedRecordedHistory,
            HasRecoveredPersistedHistory = hasRecoveredPersistedHistory,
            CanExecuteDependencyAwareTeardownAndMutationExecutionOnCurrentNode = canExecuteDependencyAwareTeardownAndMutationExecutionOnCurrentNode,
            CanExecuteDependencyAwareTeardownOnCurrentNode = canExecuteDependencyAwareTeardownOnCurrentNode,
            CanExecuteDependencyAwareMutationExecutionOnCurrentNode = canExecuteDependencyAwareMutationExecutionOnCurrentNode
        };
    }

    private static string[] CreateManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories(
        string state,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStatus providerSpecificControlPlaneMaterializer,
        bool hasProviderIdentity,
        bool hasMaterializerIdentity,
        bool hasTransportIdentity,
        bool hasProviderSurfaceIdentity,
        bool hasConnectorIdentity,
        bool hasWorkerIdentity,
        bool hasTargetOperation,
        bool isTeardownOperation,
        bool isMutationExecutionOperation,
        bool isMutationOperation,
        bool isReconcileOperation,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity,
        bool hasTaskBaseline,
        bool hasReportedTaskTopology,
        bool hasActiveTaskTopology,
        bool hasDependencyIdentityMismatch,
        bool hasTaskTopologyMismatch,
        bool hasDurableStoreConfigured,
        bool hasPersistedRecordedHistory,
        bool hasRecoveredPersistedHistory,
        bool canExecuteDependencyAwareTeardownAndMutationExecutionOnCurrentNode,
        bool canExecuteDependencyAwareTeardownOnCurrentNode,
        bool canExecuteDependencyAwareMutationExecutionOnCurrentNode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(providerSpecificControlPlaneMaterializer);

        if (!providerSpecificControlPlaneMaterializer.AppliesToManagedConnector)
        {
            return [];
        }

        var categories = new List<string>(capacity: 40);

        static void AddCategory(List<string> values, string category)
        {
            if (!values.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                values.Add(category);
            }
        }

        AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardening);

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.OperatorOnly);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyReady, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DependencyReady);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.TeardownBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.TeardownBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.MutationExecutionBlocked, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MutationExecutionBlocked);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyDegraded, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DependencyDegraded);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.TeardownHardened, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.TeardownHardened);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.MutationExecutionHardened, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MutationExecutionHardened);
        }
        else if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DependencyRisk);
        }

        if (providerSpecificControlPlaneMaterializer.IsMaterializerUnavailable)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MaterializerUnavailable);
        }
        else if (providerSpecificControlPlaneMaterializer.IsMaterializerReady)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MaterializerReady);
        }
        else if (providerSpecificControlPlaneMaterializer.IsMaterializerSelected)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MaterializerSelected);
        }
        else if (providerSpecificControlPlaneMaterializer.IsMaterializerExecuting)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MaterializerExecuting);
        }
        else if (providerSpecificControlPlaneMaterializer.IsMaterializerRisk)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MaterializerRisk);
        }

        if (hasTargetOperation)
        {
            AddCategory(
                categories,
                isTeardownOperation
                    ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.TeardownOperation
                    : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MutationExecutionOperation);

            if (isMutationOperation)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MutationOperation);
            }

            if (isReconcileOperation)
            {
                AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ReconcileOperation);
            }
        }
        else
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.NoTargetOperation);
        }

        AddCategory(
            categories,
            canExecuteDependencyAwareTeardownAndMutationExecutionOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.CurrentNodeExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.CurrentNodeBlocked);
        AddCategory(
            categories,
            canExecuteDependencyAwareTeardownOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.CurrentNodeTeardownExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.CurrentNodeTeardownBlocked);
        AddCategory(
            categories,
            canExecuteDependencyAwareMutationExecutionOnCurrentNode
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.CurrentNodeMutationExecutionExecutable
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.CurrentNodeMutationExecutionBlocked);

        AddCategory(
            categories,
            hasProviderIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MissingProviderId);
        AddCategory(
            categories,
            hasMaterializerIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MaterializerIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MissingMaterializerId);
        AddCategory(
            categories,
            hasTransportIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.TransportIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MissingTransportKind);
        AddCategory(
            categories,
            hasProviderSurfaceIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderSurfaceReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MissingProviderSurface);
        AddCategory(
            categories,
            hasConnectorIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ConnectorIdentityReady
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.MissingConnectorId);
        AddCategory(
            categories,
            hasWorkerIdentity
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.WorkerIdentityVisible
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.WorkerIdentityUnavailable);

        if (hasDeclaredDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DeclaredDependencyIdentityReady);
        }

        if (hasReportedDependencyIdentity)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ReportedDependencyIdentityReady);
        }

        if (hasTaskBaseline)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.TaskBaselineReady);
        }

        if (hasReportedTaskTopology)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ReportedTaskTopologyReady);
        }

        if (hasActiveTaskTopology)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ActiveTaskTopologyReady);
        }

        if (hasDependencyIdentityMismatch)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DependencyIdentityMismatch);
        }

        if (hasTaskTopologyMismatch)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.TaskTopologyMismatch);
        }

        if (hasDurableStoreConfigured)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DurableStoreConfigured);
        }

        if (hasPersistedRecordedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.PersistedHistoryVisible);
        }

        if (hasRecoveredPersistedHistory)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.RecoveredPersistedHistory);
        }

        AddCategory(
            categories,
            summary.HasActiveReporterLease
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ReporterLeaseActive
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ReporterLeaseMissingOrStale);

        AddCategory(
            categories,
            providerSpecificControlPlaneMaterializer.WouldApplyChanges
                ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.WouldApplyChanges
                : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.NoChangesRequired);

        if (providerSpecificControlPlaneMaterializer.RequiresExplicitApproval)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ApprovalRequired);
        }

        if (providerSpecificControlPlaneMaterializer.IsDestructiveOperation)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.DestructiveOperation);
        }

        if (latestCommandExecution.IsAdapted)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderCommandAdapted);
        }
        else if (latestCommandExecution.IsNoOp)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderCommandNoOp);
        }
        else if (latestCommandExecution.IsBlocked)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderCommandBlocked);
        }
        else if (latestCommandExecution.IsFailed)
        {
            AddCategory(categories, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningCategories.ProviderCommandFailed);
        }

        return categories
            .OrderBy(static category => category, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string CreateManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningDescription(
        string state,
        string operationId,
        string? providerId,
        string? materializerId,
        string? providerSurfaceId,
        CdcCaptureExecutionRuntimeSummary summary,
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStatus providerSpecificControlPlaneMaterializer,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        bool isTeardownOperation,
        bool hasProviderIdentity,
        bool hasMaterializerIdentity,
        bool hasTransportIdentity,
        bool hasProviderSurfaceIdentity,
        bool hasConnectorIdentity,
        bool hasDeclaredDependencyIdentity,
        bool hasReportedDependencyIdentity,
        bool hasTaskBaseline,
        bool hasReportedTaskTopology,
        bool hasActiveTaskTopology,
        string? reconciliationReason)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentNullException.ThrowIfNull(summary);
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(providerSpecificControlPlaneMaterializer);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);

        var operationLabel = CreateManagedConnectorExecutionAdapterOperationLabel(operationId);
        var providerLabel = string.IsNullOrWhiteSpace(providerId) ? "unknown-provider" : providerId.Trim();
        var materializerLabel = string.IsNullOrWhiteSpace(materializerId) ? "unknown-materializer" : materializerId.Trim();
        var surfaceLabel = string.IsNullOrWhiteSpace(providerSurfaceId) ? "unknown-surface" : providerSurfaceId.Trim();
        var laneLabel = isTeardownOperation ? "teardown" : "mutation execution";
        var detail = CombineManagedConnectorCommandEnvelopeDetail(
            CombineManagedConnectorCommandEnvelopeDetail(
                providerSpecificControlPlaneMaterializer.Description,
                providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.Description,
                executionAdapter.Description),
            summary.ReporterCoordination.Description,
            CombineManagedConnectorCommandEnvelopeDetail(
                latestCommandExecution.IsUnrecorded ? null : latestCommandExecution.Description,
                commandJournal.Description,
                reconciliationReason));

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                "The execution runtime does not currently represent provider-specific dependency-aware teardown or mutation-execution hardening.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.OperatorOnly, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can describe provider-specific dependency-aware {laneLabel} hardening for {operationLabel}, but the lane still remains operator-owned outside the engine.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyRisk, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can identify provider-specific dependency-aware {laneLabel} hardening for provider '{providerLabel}', but materializer '{materializerLabel}' still remains risky on the shared runtime surface.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyDegraded, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon can identify provider-specific materializer '{materializerLabel}' for {laneLabel}, but dependency evidence for {operationLabel} is still degraded on surface '{surfaceLabel}'.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.TeardownBlocked, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.MutationExecutionBlocked, StringComparison.OrdinalIgnoreCase))
        {
            string summaryText;
            if (!hasProviderIdentity)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for {operationLabel} because the provider identity is missing.";
            }
            else if (!hasMaterializerIdentity)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for provider '{providerLabel}' because no materializer id is declared.";
            }
            else if (!hasTransportIdentity)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for materializer '{materializerLabel}' because the transport kind is missing.";
            }
            else if (!hasProviderSurfaceIdentity)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for materializer '{materializerLabel}' because the provider surface id is missing.";
            }
            else if (!hasConnectorIdentity)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for materializer '{materializerLabel}' because the connector identity is missing.";
            }
            else if (!hasDeclaredDependencyIdentity || !hasReportedDependencyIdentity)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for materializer '{materializerLabel}' because dependency identity evidence is incomplete.";
            }
            else if (!hasTaskBaseline || !hasReportedTaskTopology || !hasActiveTaskTopology)
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for materializer '{materializerLabel}' because task-topology evidence is incomplete.";
            }
            else
            {
                summaryText = $"Cephalon cannot yet harden provider-specific {laneLabel} for materializer '{materializerLabel}' because the current node still lacks one safe execution lane.";
            }

            return AppendManagedConnectorCommandEnvelopeDetail(summaryText, detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.DependencyReady, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon is ready to harden provider-specific {laneLabel} for {operationLabel} through materializer '{materializerLabel}' on surface '{surfaceLabel}'.",
                detail);
        }

        if (string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.TeardownHardened, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(state, CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningStates.MutationExecutionHardened, StringComparison.OrdinalIgnoreCase))
        {
            return AppendManagedConnectorCommandEnvelopeDetail(
                $"Cephalon hardened provider-specific {laneLabel} for {operationLabel} through materializer '{materializerLabel}' on provider '{providerLabel}'.",
                detail);
        }

        return AppendManagedConnectorCommandEnvelopeDetail(
            $"Cephalon exposes provider-specific dependency-aware {laneLabel} hardening for provider '{providerLabel}'.",
            detail);
    }

    private static string ResolveManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSourceId(
        CdcCaptureExecutionRuntimeManagedConnectorCommandExecutionResult latestCommandExecution,
        CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStatus commandJournal,
        CdcCaptureExecutionRuntimeManagedConnectorExecutionAdapterStatus executionAdapter,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedWritePathExecutionStatus providerOwnedWritePathExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderExecutionOrchestrationStatus providerExecutionOrchestration,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneOwnershipStatus providerOwnedControlPlaneOwnership,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneMutationReconcileStatus providerOwnedControlPlaneMutationReconcile,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneProvisioningStatus providerOwnedControlPlaneProvisioning,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneApplyAndReconcileExecutionStatus providerOwnedControlPlaneApplyAndReconcileExecution,
        CdcCaptureExecutionRuntimeManagedConnectorProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardeningStatus providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening,
        CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneMaterializerStatus providerSpecificControlPlaneMaterializer,
        bool hasProviderIdentity,
        bool hasMaterializerIdentity)
    {
        ArgumentNullException.ThrowIfNull(latestCommandExecution);
        ArgumentNullException.ThrowIfNull(commandJournal);
        ArgumentNullException.ThrowIfNull(executionAdapter);
        ArgumentNullException.ThrowIfNull(providerOwnedWritePathExecution);
        ArgumentNullException.ThrowIfNull(providerExecutionOrchestration);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneOwnership);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneMutationReconcile);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneProvisioning);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneApplyAndReconcileExecution);
        ArgumentNullException.ThrowIfNull(providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening);
        ArgumentNullException.ThrowIfNull(providerSpecificControlPlaneMaterializer);

        if (!latestCommandExecution.IsUnrecorded &&
            (latestCommandExecution.IsFailed || latestCommandExecution.IsBlocked))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.CommandExecution;
        }

        if (providerSpecificControlPlaneMaterializer.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderSpecificControlPlaneMaterializer;
        }

        if (providerOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderOwnedControlPlaneDependencyAwareProvisioningAndMutationHardening;
        }

        if (providerOwnedControlPlaneApplyAndReconcileExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderOwnedControlPlaneApplyAndReconcileExecution;
        }

        if (providerOwnedControlPlaneProvisioning.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderOwnedControlPlaneProvisioning;
        }

        if (providerOwnedControlPlaneMutationReconcile.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderOwnedControlPlaneMutationReconcile;
        }

        if (providerOwnedControlPlaneOwnership.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderOwnedControlPlaneOwnership;
        }

        if (providerExecutionOrchestration.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderExecutionOrchestration;
        }

        if (providerOwnedWritePathExecution.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ProviderOwnedWritePathExecution;
        }

        if (executionAdapter.AppliesToManagedConnector)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.ExecutionAdapter;
        }

        if (!string.Equals(commandJournal.State, CdcCaptureExecutionRuntimeManagedConnectorCommandJournalStates.NotApplicable, StringComparison.OrdinalIgnoreCase))
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.CommandJournal;
        }

        if (!latestCommandExecution.IsUnrecorded)
        {
            return CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.CommandExecution;
        }

        return hasProviderIdentity || hasMaterializerIdentity
            ? CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.Metadata
            : CdcCaptureExecutionRuntimeManagedConnectorProviderSpecificControlPlaneDependencyAwareTeardownAndMutationExecutionHardeningSources.Unknown;
    }

    private sealed record ManagedConnectorMetadataSnapshot(
        string? ManagementMode,
        string? DeclaredConnectClusterId,
        string? ReportedConnectClusterId,
        string? DeclaredConnectorClass,
        string? ReportedConnectorClass,
        string? DeclaredSourceProviderId,
        string? ReportedSourceProviderId,
        int? ExpectedTaskCount,
        int? ReportedTaskCount,
        string[] DeclaredTaskIds,
        string[] ReportedTaskIds,
        string[] ActiveTaskIds,
        string? ConnectorLifecycleState,
        string? TaskReconciliationState,
        string? ReconciliationState,
        string? ReconciliationReason,
        string? ProviderSpecificControlPlaneProviderId,
        string? ProviderSpecificControlPlaneMaterializerId,
        string? ProviderSpecificControlPlaneTransportKind,
        string? ProviderSpecificControlPlaneSurfaceId,
        string? ProviderSpecificControlPlaneConnectorId,
        string? ProviderSpecificControlPlaneWorkerId);
}
